def test_full_oracle(run, x):
    lines = x.strip().splitlines()
    first = lines[0].split()
    n = int(first[0])
    m = int(first[1])
    grid = lines[1:1+n]
    S = [set() for _ in range(n)]
    T = [set() for _ in range(m)]
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '#':
                S[i].add(j)
                T[j].add(i)
    row_ok = True
    for i in range(n):
        for j in range(i+1, n):
            if S[i] & S[j]:
                if S[i] != S[j]:
                    row_ok = False
                    break
        if not row_ok:
            break
    col_ok = True
    if row_ok:
        for i in range(m):
            for j in range(i+1, m):
                if T[i] & T[j]:
                    if T[i] != T[j]:
                        col_ok = False
                        break
            if not col_ok:
                break
    correct = row_ok and col_ok
    output = run(x).strip().lower()
    assert (output == 'yes') == correct

def test_row_necessary(run, x):
    lines = x.strip().splitlines()
    first = lines[0].split()
    n = int(first[0])
    m = int(first[1])
    grid = lines[1:1+n]
    output = run(x).strip().lower()
    if output == 'yes':
        S = [set() for _ in range(n)]
        for i in range(n):
            for j in range(m):
                if grid[i][j] == '#':
                    S[i].add(j)
        for i in range(n):
            for j in range(i+1, n):
                if S[i] & S[j]:
                    if S[i] != S[j]:
                        assert False

def test_column_necessary(run, x):
    lines = x.strip().splitlines()
