    n = int(first[0])
    m = int(first[1])
    grid = lines[1:1+n]
    output = run(x).strip().lower()
    if output == 'yes':
        T = [set() for _ in range(m)]
        for i in range(n):
            for j in range(m):
                if grid[i][j] == '#':
                    T[j].add(i)
        for i in range(m):
            for j in range(i+1, m):
                if T[i] & T[j]:
                    if T[i] != T[j]:
                        assert False

def test_single_rowcol(run, x):
    lines = x.strip().splitlines()
    first = lines[0].split()
    n = int(first[0])
    m = int(first[1])
    output = run(x).strip().lower()
    if n == 1 or m == 1:
        assert output == 'yes'

def test_no_black(run, x):
    lines = x.strip().splitlines()
    first = lines[0].split()
    n = int(first[0])
    m = int(first[1])
    grid = lines[1:1+n]
    output = run(x).strip().lower()
    black_count = sum(row.count('#') for row in grid)
    if black_count == 0:
        assert output == 'yes'

def test_one_black(run, x):
    lines = x.strip().splitlines()
    first = lines[0].split()
    n = int(first[0])
    m = int(first[1])
    grid = lines[1:1+n]
    output = run(x).strip().lower()
    black_count = sum(row.count('#') for row in grid)
    if black_count == 1:
        assert output == 'yes'

def test_all_black(run, x):
    lines = x.strip().splitlines()
    first = lines[0].split()
    n = int(first[0])
    m = int(first[1])
    grid = lines[1:1+n]
    output = run(x).strip().lower()
    total_cells = n * m
    black_count = sum(row.count('#') for row in grid)
    if black_count == total_cells:
        assert output == 'yes'

def test_examples(run, x):
    examples = {
        "5 8\n.#.#..#.\n.....#..\n.#.#..#.\n#.#....#\n.....#..\n": "Yes",
        "5 5\n..#..\n..#..\n#####\n..#..\n..#..\n": "No",
        "5 9\n........#\n#........\n..##.#...\n.......#.\n....#.#.#\n": "No"
    }
    if x in examples:
        expected = examples[x].lower()
        output = run(x).strip().lower()
        assert output == expected

def test_output_format(run, x):
    output = run(x).strip()
    assert output
    lower = output.lower()
    assert lower in ("yes", "no")

def test_no_necessary(run, x):
    lines = x.strip().splitlines()
    first = lines[0].split()
    n = int(first[0])
    m = int(first[1])
    grid = lines[1:1+n]
    output = run(x).strip().lower()
    if output == 'no':
        S = [set() for _ in range(n)]
        T = [set() for _ in range(m)]
        for i in range(n):
            for j in range(m):
                if grid[i][j] == '#':
                    S[i].add(j)
                    T[j].add(i)
        row_ok = True
        for i in range(n):
            for j in range(i+1, n):
                if S[i] & S[j]:
                    if S[i] != S[j]:
                        row_ok = False
                        break
            if not row_ok:
                break
        col_ok = True
        if row_ok:
            for i in range(m):
                for j in range(i+1, m):
                    if T[i] & T[j]:
                        if T[i] != T[j]:
                            col_ok = False
                            break
                if not col_ok:
                    break
        if row_ok and col_ok:
            assert False

def test_full_oracle(run, x):
    out = run(x)
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    grid = [list(line.rstrip()) for line in lines[1:1+n]]
    heights = [0]*m
    for col in range(m):
        cnt = 0
        for row in range(n):
            if grid[row][col] == '*':
                cnt += 1
        heights[col] = cnt
    max_ascent = 0
    max_descent = 0
    for i in range(1, m):
        diff = heights[i] - heights[i-1]
        if diff > 0:
            max_ascent = max(max_ascent, diff)
        elif diff < 0:
            max_descent = max(max_descent, -diff)
    expected = f'{max_ascent} {max_descent}'
    assert out.strip() == expected


def test_output_format(run, x):
    import re
    out = run(x)
    assert re.fullmatch(r'\d+ \d+\n?', out) is not None


def test_non_negative(run, x):
    out = run(x)
    a, b = map(int, out.split())
    assert a >= 0 and b >= 0


def test_no_ascent_implies_zero_ascent(run, x):
    out = run(x)
    a, b = map(int, out.split())
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    grid = [list(line.rstrip()) for line in lines[1:1+n]]
    heights = [0]*m
    for col in range(m):
        cnt = 0
        for row in range(n):
            if grid[row][col] == '*':
                cnt += 1
        heights[col] = cnt
    has_ascent = any(heights[i] > heights[i-1] for i in range(1, m))
    if not has_ascent:
        assert a == 0


def test_no_descent_implies_zero_descent(run, x):
    out = run(x)
    a, b = map(int, out.split())
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    grid = [list(line.rstrip()) for line in lines[1:1+n]]
    heights = [0]*m
    for col in range(m):
        cnt = 0
        for row in range(n):
            if grid[row][col] == '*':
                cnt += 1
        heights[col] = cnt
    has_descent = any(heights[i] < heights[i-1] for i in range(1, m))
    if not has_descent:
        assert b == 0


def test_at_least_individual_differences(run, x):
    out = run(x)
    a, b = map(int, out.split())
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    grid = [list(line.rstrip()) for line in lines[1:1+n]]
    heights = [0]*m
    for col in range(m):
        cnt = 0
        for row in range(n):
            if grid[row][col] == '*':
                cnt += 1
        heights[col] = cnt
    for i in range(1, m):
        diff = heights[i] - heights[i-1]
        if diff > 0:
            assert a >= diff
        elif diff < 0:
            assert b >= -diff


def test_upper_bound(run, x):
    out = run(x)
    a, b = map(int, out.split())
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    max_diff = n - 1
    assert a <= max_diff and b <= max_diff


def test_format_two_ints(run, x):
    out = run(x)
    parts = out.strip().split()
    assert len(parts) == 2
    int(parts[0])
    int(parts[1])


def test_single_column(run, x):
    out = run(x)
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    if m == 1:
        assert out.strip() == '0 0'


def test_zero_zero_implies_constant_heights(run, x):
    out = run(x)
    a, b = map(int, out.split())
    if a == 0 and b == 0:
        lines = x.strip().splitlines()
        n, m = map(int, lines[0].split())
        grid = [list(line.rstrip()) for line in lines[1:1+n]]
        heights = [0]*m
        for col in range(m):
            cnt = 0
            for row in range(n):
                if grid[row][col] == '*':
                    cnt += 1
            heights[col] = cnt
        assert all(h == heights[0] for h in heights)

