def test_exact_bfs(run, x):
    import sys
    from collections import deque
    output = run(x).strip()
    lines = x.strip().splitlines()
    n = int(lines[0])
    colors = list(map(int, lines[1].split()))
    # compress
    A = []
    for c in colors:
        if not A or c != A[-1]:
            A.append(c)
    L = len(A)
    if L == 1:
        expected = 0
    else:
        best = L-1
        for k in range(L):
            start = (k, k)
            dist = {start: 0}
            q = deque([start])
            while q:
                l, r = q.popleft()
                d = dist[(l, r)]
                if l == 0 and r == L-1:
                    if d < best:
                        best = d
                    break
                if l > 0:
                    new = (l-1, r)
                    if new not in dist:
                        dist[new] = d+1
                        q.append(new)
                if r < L-1:
                    new = (l, r+1)
                    if new not in dist:
                        dist[new] = d+1
                        q.append(new)
                if l > 0 and r < L-1 and A[l-1] == A[r+1]:
                    new = (l-1, r+1)
                    if new not in dist:
                        dist[new] = d+1
                        q.append(new)
        expected = best
    assert output.isdigit() or (output[0] == '-' and output[1:].isdigit())
    ans = int(output)
    assert ans == expected


