def test_format(run, x):
    # Input validity check
    lines_in = x.strip().split('\n')
    if not lines_in or len(lines_in) < 2:
        return
    try:
        n = int(lines_in[0])
    except:
        return
    if len(lines_in) != n + 1:
        return
    pairs = []
    for i in range(1, n+1):
        parts = lines_in[i].split()
        if len(parts) != 2:
            return
        a, b = map(int, parts)
        pairs.append((a, b))
    a_vals = [p[0] for p in pairs]
    b_vals = [p[1] for p in pairs]
    for i in range(n-1):
        if a_vals[i] >= a_vals[i+1]:
            return
        if b_vals[i] >= b_vals[i+1]:
            return
    all_vals = a_vals + b_vals
    if len(set(all_vals)) != 2*n:
        return
    # Test output
    output = run(x)
    lines = output.strip().split('\n')
    assert len(lines) == 2, f"Expected 2 lines, got {len(lines)}"
