def test_exact_oracle(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0].strip())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    total = sum(a)
    first = -1
    second = -1
    for val in b:
        if val > first:
            second = first
            first = val
        elif val > second:
            second = val
    max_pair_sum = first + second
    expected = 'YES' if max_pair_sum >= total else 'NO'
    output = run(x).strip().upper()
    assert output == expected, f'Expected {expected}, got {output}'

def test_output_valid(run, x):
