def test_equality_implies_yes(run, x):
    lines = x.strip().splitlines()
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    total = sum(a)
    first = -1
    second = -1
    for val in b:
        if val > first:
            second = first
            first = val
        elif val > second:
            second = val
    max_pair_sum = first + second
    if max_pair_sum == total:
        output = run(x).strip().upper()
