def test_exhaustive(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0].strip())
    pairs = [tuple(map(int, line.split())) for line in lines[1:1+n]]
    a = [p[0] for p in pairs]
    b = [p[1] for p in pairs]
    valid = True
    for i in range(1, n):
        if a[i] <= a[i-1]:
            valid = False
            break
    if valid:
        for i in range(1, n):
            if b[i] <= b[i-1]:
                valid = False
                break
    if valid:
        all_times = set()
        for t in a+b:
            if t in all_times:
                valid = False
                break
            all_times.add(t)
    if not valid:
        return
    chance1 = [False]*n
    chance2 = [False]*n
    maxk = n//2
    for k in range(maxk+1):
        selected = set()
        for i in range(k):
            selected.add(('A', i))
            selected.add(('B', i))
        remaining = []
        for i in range(k, n):
            remaining.append(('A', i, pairs[i][0]))
            remaining.append(('B', i, pairs[i][1]))
        remaining.sort(key=lambda t: t[2])
        for t in remaining[:n-2*k]:
            selected.add((t[0], t[1]))
        for (sem, idx) in selected:
            if sem == 'A':
                chance1[idx] = True
            else:
                chance2[idx] = True
    exp1 = ''.join('1' if chance1[i] else '0' for i in range(n))
    exp2 = ''.join('1' if chance2[i] else '0' for i in range(n))
    actual = run(x)
    out_lines = actual.rstrip('\n').splitlines()
    if len(out_lines) != 2:
        assert False, "Not two lines"
    actual1 = out_lines[0]
    actual2 = out_lines[1]
    assert actual1 == exp1 and actual2 == exp2


