    val = int(out.strip())
    assert val >= 0, f'Answer must be non-negative, got {val}'

def test_upper_bound(run, x):
    parts = x.strip().split()
    if len(parts) != 2:
        return
    N = int(parts[0])
    out = run(x)
    val = int(out.strip())
    assert val <= N**4, f'Answer {val} exceeds total quadruples {N**4}'

def test_sample(run, x):
    if x == '2 1\n':
        out = run(x)
        assert out.strip() == '4', f'For sample input, expected 4, got {out.strip()}'

def test_N1_valid(run, x):
    parts = x.strip().split()
    if len(parts) != 2:
        return
    N = int(parts[0])
    K = int(parts[1])
    if not (1 <= N <= 10**5 and -2*(N-1) <= K <= 2*(N-1)):
        return
    if N == 1:
        out = run(x)
        val = int(out.strip())
        assert val == 1, f'For N=1, answer must be 1, got {val}'

def test_max_K(run, x):
    parts = x.strip().split()
    if len(parts) != 2:
        return
    N = int(parts[0])
    K = int(parts[1])
    if not (1 <= N <= 10**5 and -2*(N-1) <= K <= 2*(N-1)):
        return
    if abs(K) == 2*(N-1):
        out = run(x)
        val = int(out.strip())
        assert val == 1, f'For |K|=2(N-1), answer must be 1, got {val}'

def test_bruteforce_small(run, x):
    parts = x.strip().split()
    if len(parts) != 2:
        return
    N = int(parts[0])
    K = int(parts[1])
    if not (1 <= N <= 10**5 and -2*(N-1) <= K <= 2*(N-1)):
        return
    if N > 10:
        return
    cnt = 0
    for a in range(1, N+1):
        for b in range(1, N+1):
            for c in range(1, N+1):
                for d in range(1, N+1):
                    if a + b - c - d == K:
                        cnt += 1
    out = run(x)
    val = int(out.strip())
    assert val == cnt, f'For N={N}, K={K}, brute force says {cnt}, got {val}'

def test_formula_k0(run, x):
    parts = x.strip().split()
    if len(parts) != 2:
        return
    N = int(parts[0])
    K = int(parts[1])
    if not (1 <= N <= 10**5 and -2*(N-1) <= K <= 2*(N-1)):
        return
    if K != 0:
        return
    total = 0
    for S in range(2, 2*N+1):
        f1 = min(S-1, 2*N - S + 1)
        total += f1 * f1
    out = run(x)
    val = int(out.strip())
    assert val == total, f'For K=0, expected {total}, got {val}'

def test_formula_general(run, x):
    parts = x.strip().split()
    if len(parts) != 2:
        return
    N = int(parts[0])
    K = int(parts[1])
    if not (1 <= N <= 10**5 and -2*(N-1) <= K <= 2*(N-1)):
        return
    total = 0
    for T in range(2, 2*N+1):
        S = T + K
        if 2 <= S <= 2*N:
            f1 = min(S-1, 2*N - S + 1)
            f2 = min(T-1, 2*N - T + 1)
            total += f1 * f2
    out = run(x)
    val = int(out.strip())
    assert val == total, f'Expected {total}, got {val}'

