tests_src:
def test_direct_oracle(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    pattern = lines[1].strip()
    names = ["vaporeon", "jolteon", "flareon", "espeon", "umbreon", "leafeon", "glaceon", "sylveon"]
    output = run(x).strip()
    matches = []
    for name in names:
        if len(name) != n:
            continue
        ok = True
        for i in range(n):
            if pattern[i] != '.' and name[i] != pattern[i]:
                ok = False
                break
        if ok:
            matches.append(name)
    assert len(matches) == 1
    assert output == matches[0]

def test_length_match(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    output = run(x).strip()
    assert len(output) == n

def test_is_lowercase_alpha(run, x):
    output = run(x).strip()
    assert output.islower() and output.isalpha()

def test_in_list(run, x):
    names = ["vaporeon", "jolteon", "flareon", "espeon", "umbreon", "leafeon", "glaceon", "sylveon"]
    output = run(x).strip()
    assert output in names

def test_pattern_match_all(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    pattern = lines[1].strip()
    output = run(x).strip()
    assert len(output) == n
    for i in range(n):
        if pattern[i] != '.':
            assert output[i] == pattern[i]

def test_ends_with_eon(run, x):
    output = run(x).strip()
    assert output.endswith('eon')

def test_n6_espeon(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    output = run(x).strip()
    if n == 6:
        assert output == "espeon"

def test_n8_vaporeon(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    output = run(x).strip()
    if n == 8:
        assert output == "vaporeon"

def test_no_dot_in_output(run, x):
    output = run(x).strip()
    assert '.' not in output

def test_n7_possible_names(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    output = run(x).strip()
    if n == 7:
        length7_names = ["jolteon", "flareon", "umbreon", "leafeon", "glaceon", "sylveon"]
        assert output in length7_names

