def test_bruteforce(run, x):
    def parse_input(x):
        lines = x.strip().splitlines()
        n = int(lines[0])
        a = list(map(int, lines[1].split()))
        return n, a
    n, a = parse_input(x)
    best = None
    for i in range(1, n-1):
        new_a = a[:i] + a[i+1:]
        max_diff = max(new_a[j+1] - new_a[j] for j in range(len(new_a)-1))
        if best is None or max_diff < best:
            best = max_diff
    out = run(x).strip()
    if out.startswith('-'):
        assert out[1:].isdigit()
    else:
        assert out.isdigit()
    out_val = int(out)
    assert out_val == best

