def test_format(run, x):
    parts = x.strip().split()
    if len(parts) < 1:
        return
    N = int(parts[0])
    out = run(x)
    lines = out.rstrip('\n').split('\n')
    assert len(lines) == N-1, f'Expected {N-1} lines, got {len(lines)}'

def test_non_negative(run, x):
    out = run(x)
    lines = out.rstrip('\n').split('\n')
    for line in lines:
        if line == '':
            continue
        val = int(line)
        assert val >= 0, f'Negative count: {val}'

def test_sum(run, x):
    parts = x.strip().split()
    if len(parts) < 1:
        return
    N = int(parts[0])
    out = run(x)
    lines = out.rstrip('\n').split('\n')
    total = 0
    for line in lines:
        if line == '':
            continue
        total += int(line)
    expected = N * (N-1) // 2
    assert total == expected, f'Sum of counts is {total}, expected {expected}'

def test_distance_one(run, x):
    parts = x.strip().split()
    if len(parts) < 1:
        return
    N = int(parts[0])
    out = run(x)
    lines = out.rstrip('\n').split('\n')
    if len(lines) == 0:
        assert False, 'No output'
    first = int(lines[0])
    assert first == N, f'Count for distance 1 is {first}, expected {N}'

def test_cycle_case(run, x):
    parts = x.strip().split()
    if len(parts) != 3:
        return
    N = int(parts[0])
    X = int(parts[1])
    Y = int(parts[2])
    if X != 1 or Y != N:
        return
    out = run(x)
    lines = out.rstrip('\n').split('\n')
    if N % 2 == 0:
        half = N // 2
        for idx, line in enumerate(lines, start=1):
            val = int(line)
            if idx < half:
                expected = N
            elif idx == half:
                expected = N // 2
            else:
                expected = 0
            assert val == expected, f'For cycle N={N}, k={idx}: expected {expected}, got {val}'
    else:
        half = N // 2
        for idx, line in enumerate(lines, start=1):
            val = int(line)
            if idx <= half:
                expected = N
            else:
                expected = 0
            assert val == expected, f'For cycle N={N}, k={idx}: expected {expected}, got {val}'

def test_small_bruteforce(run, x):
    parts = x.strip().split()
    if len(parts) != 3:
        return
    N = int(parts[0])
    X = int(parts[1])
    Y = int(parts[2])
    if N > 15:
        return
    from collections import deque
    out = run(x)
    lines = out.rstrip('\n').split('\n')
    adj = [[] for _ in range(N+1)]
    for i in range(1, N):
        adj[i].append(i+1)
        adj[i+1].append(i)
    adj[X].append(Y)
    adj[Y].append(X)
    cnt = [0] * (N+1)
    for s in range(1, N+1):
        dist = [-1] * (N+1)
        q = deque([s])
        dist[s] = 0
        while q:
            u = q.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    q.append(v)
        for t in range(s+1, N+1):
            d = dist[t]
            if d > 0:
                cnt[d] += 1
    for k in range(1, N):
        val = int(lines[k-1])
        assert val == cnt[k], f'For k={k}: expected {cnt[k]}, got {val}'

def test_formula_moderate(run, x):
    parts = x.strip().split()
    if len(parts) != 3:
        return
    N = int(parts[0])
    X = int(parts[1])
    Y = int(parts[2])
    if N > 200:
        return
    out = run(x)
    lines = out.rstrip('\n').split('\n')
    cnt = [0] * (N+1)
    for i in range(1, N+1):
        for j in range(i+1, N+1):
            d1 = j - i
            d2 = abs(i - X) + 1 + abs(j - Y)
            d3 = abs(i - Y) + 1 + abs(j - X)
            d = min(d1, d2, d3)
            cnt[d] += 1
    for k in range(1, N):
        val = int(lines[k-1])
        assert val == cnt[k], f'For k={k}: expected {cnt[k]}, got {val}'

def test_max_distance_zero(run, x):
    parts = x.strip().split()
    if len(parts) != 3:
        return
    N = int(parts[0])
    out = run(x)
    lines = out.rstrip('\n').split('\n')
    if N-1 <= 0:
        return
    last = int(lines[-1])
    assert last == 0, f'Count for distance N-1 (k={N-1}) is {last}, must be 0'

def test_sample(run, x):
    if x != '5 2 4\n':
        return
    out = run(x)
    expected = '5\n4\n1\n0\n'
    lines_out = out.rstrip('\n').split('\n')
    lines_exp = expected.rstrip('\n').split('\n')
    assert lines_out == lines_exp, f'Sample output mismatch. Got {out}, expected {expected}'

def test_no_extra_whitespace(run, x):
    out = run(x)
    lines = out.rstrip('\n').split('\n')
    for line in lines:
        if line == '':
            continue
        assert line.strip() == line, f'Extra whitespace in line: "{line}"'

