def test_brute_force_exact(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    if n * m > 100:   # guard: brute force too slow for larger grids
        return
    grid = [list(map(int, lines[i+1].split())) for i in range(n)]
    cnt = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 0:
                for k in range(j+1, m):
                    if grid[i][k] == 1:
                        cnt += 1
                        break
                for k in range(j-1, -1, -1):
                    if grid[i][k] == 1:
                        cnt += 1
                        break
                for k in range(i+1, n):
                    if grid[k][j] == 1:
                        cnt += 1
                        break
                for k in range(i-1, -1, -1):
                    if grid[k][j] == 1:
                        cnt += 1
                        break
    ans = int(run(x).strip())
    assert ans == cnt

def test_single_actor(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    grid = [list(map(int, lines[i+1].split())) for i in range(n)]
    actors = sum(sum(row) for row in grid)
    if actors == 1:
        ans = int(run(x).strip())
        expected = n + m - 2
        assert ans == expected

def test_all_actors(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    grid = [list(map(int, lines[i+1].split())) for i in range(n)]
    actors = sum(sum(row) for row in grid)
    if actors == n * m:
        ans = int(run(x).strip())
        assert ans == 0

def test_lower_bound(run, x):
    ans = int(run(x).strip())
    assert ans >= 0

def test_upper_bound(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    grid = [list(map(int, lines[i+1].split())) for i in range(n)]
    actors = sum(sum(row) for row in grid)
    empty = n * m - actors
    ans = int(run(x).strip())
    assert ans <= 4 * empty

def test_positive_if_empty(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    grid = [list(map(int, lines[i+1].split())) for i in range(n)]
    actors = sum(sum(row) for row in grid)
    if actors < n * m:
        ans = int(run(x).strip())
        assert ans > 0

def test_n_eq_1(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    if n == 1:
        grid = [list(map(int, lines[1].split()))]
        cnt = 0
        for j in range(m):
            if grid[0][j] == 0:
                for k in range(j-1, -1, -1):
                    if grid[0][k] == 1:
                        cnt += 1
                        break
                for k in range(j+1, m):
                    if grid[0][k] == 1:
                        cnt += 1
                        break
        ans = int(run(x).strip())
        assert ans == cnt

def test_m_eq_1(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    if m == 1:
        grid = [list(map(int, lines[i+1].split())) for i in range(n)]
        cnt = 0
        for i in range(n):
            if grid[i][0] == 0:
                for k in range(i-1, -1, -1):
                    if grid[k][0] == 1:
                        cnt += 1
                        break
                for k in range(i+1, n):
                    if grid[k][0] == 1:
                        cnt += 1
                        break
        ans = int(run(x).strip())
        assert ans == cnt

def test_integer_format(run, x):
    output = run(x).strip()
    assert output.isdigit()

def test_directional_scan(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    grid = [list(map(int, lines[i+1].split())) for i in range(n)]
    total = 0
    for i in range(n):
        seen = False
        for j in range(m):
            if grid[i][j] == 0 and seen:
                total += 1
            if grid[i][j] == 1:
                seen = True
        seen = False
        for j in range(m-1, -1, -1):
            if grid[i][j] == 0 and seen:
                total += 1
            if grid[i][j] == 1:
                seen = True
    for j in range(m):
        seen = False
        for i in range(n):
            if grid[i][j] == 0 and seen:
                total += 1
            if grid[i][j] == 1:
                seen = True
        seen = False
        for i in range(n-1, -1, -1):
            if grid[i][j] == 0 and seen:
                total += 1
            if grid[i][j] == 1:
                seen = True
    ans = int(run(x).strip())
    assert ans == total

