        nums = list(map(int, out.split()))
    except ValueError:
        assert False
    assert set(nums) == ids

def test_head(run, x):
    lines = x.strip().splitlines()
    if not lines:
        return
    n = int(lines[0])
    pairs = [tuple(map(int, line.split())) for line in lines[1:1+n] if line.strip()]
    first_set = set(a for a,_ in pairs if a != 0)
    second_set = set(b for _,b in pairs if b != 0)
    ids = first_set | second_set
    if len(ids) != n:
        return
    head_candidates = first_set - second_set
    if len(head_candidates) != 1:
