    if len(ids) != n:
        return
    out = run(x)
    try:
        nums = list(map(int, out.split()))
    except ValueError:
        assert False
    if len(nums) != n:
        assert False
    pair_set = set(pairs)
    for i in range(n):
        prev = nums[i-1] if i > 0 else 0
        nxt = nums[i+1] if i+1 < n else 0
        if (prev, nxt) not in pair_set:
            assert False

def test_pair_counts(run, x):
    lines = x.strip().splitlines()
    if not lines:
        return
    n = int(lines[0])
    pairs = [tuple(map(int, line.split())) for line in lines[1:1+n] if line.strip()]
