        if b: ids.add(b)
    if len(ids) != n:
        return
    out = run(x)
    try:
        nums = list(map(int, out.split()))
    except ValueError:
        assert False
    if len(nums) != n:
        assert False
    from collections import Counter
    out_pairs = []
    for i in range(n):
        prev = nums[i-1] if i > 0 else 0
