def test_bruteforce_small(run, x):
    MOD = 1000000007
    def parse(x):
        lines = x.strip().split('\n')
        first = lines[0].split()
        n = int(first[0])
        m = int(first[1])
        p = lines[1].strip()
        y = []
        if m > 0:
            y = list(map(int, lines[2].split()))
        return n, m, p, y
    n, m, p, y = parse(x)
    if n > 4:
        return
    import itertools
    L = len(p)
    count = 0
    for chars in itertools.product('abcdefghijklmnopqrstuvwxyz', repeat=n):
        s = ''.join(chars)
        ok = True
        for yi in y:
            if yi + L - 1 > n:
                ok = False
                break
            if s[yi-1:yi-1+L] != p:
                ok = False
                break
        if not ok:
            continue
        occ = []
        for i in range(1, n - L + 2):
            if s[i-1:i-1+L] == p:
                occ.append(i)
        idx = 0
        for o in occ:
            if idx < len(y) and o == y[idx]:
                idx += 1
        if idx == len(y):
            count += 1
    expected = count % MOD
    output = run(x).strip()
    assert output.isdigit()
    assert int(output) == expected

