def test_exact_match(run, x):
    import sys
    def simulate(n, tasks):
        busy = [0]*n
        res = []
        for t,k,d in tasks:
            free = [i for i in range(n) if busy[i] <= t]
            if len(free) < k:
                res.append(-1)
            else:
                chosen = sorted(free)[:k]
                s = sum(ch+1 for ch in chosen)
                for ch in chosen:
                    busy[ch] = t + d
                res.append(s)
        return res
    lines = x.strip().split('\n')
    n, q = map(int, lines[0].split())
    tasks = []
    for i in range(1, q+1):
        t,k,d = map(int, lines[i].split())
        tasks.append((t,k,d))
    expected = simulate(n, tasks)
    output = run(x).strip().split()
    if output == [] and q == 0:
        return
    assert len(output) == q
    for i in range(q):
        assert int(output[i]) == expected[i]

def test_sum_bounds(run, x):
    lines = x.strip().split('\n')
    n, q = map(int, lines[0].split())
    tasks = []
    for i in range(1, q+1):
        t,k,d = map(int, lines[i].split())
        tasks.append((t,k,d))
    output = list(map(int, run(x).strip().split()))
    for i in range(q):
        out = output[i]
        if out != -1:
            k = tasks[i][1]
            min_sum = k*(k+1)//2
            max_sum = k*(2*n - k + 1)//2
            assert min_sum <= out <= max_sum

def test_first_task(run, x):
    lines = x.strip().split('\n')
    n, q = map(int, lines[0].split())
    if q == 0:
        return
    first_task = tuple(map(int, lines[1].split()))
    t,k,d = first_task
    free = list(range(n))
    if len(free) < k:
        expected = -1
    else:
        chosen = sorted(free)[:k]
        expected = sum(ch+1 for ch in chosen)
    output = list(map(int, run(x).strip().split()))
    assert output[0] == expected

def test_no_negative_except_minus_one(run, x):
    output = list(map(int, run(x).strip().split()))
