def test_ignore_condition(run, x):
    def free_counts(n, tasks):
        busy = [0]*n
        counts = []
        for t,k,d in tasks:
            free = [i for i in range(n) if busy[i] <= t]
            counts.append(len(free))
            if len(free) >= k:
                chosen = sorted(free)[:k]
                for ch in chosen:
                    busy[ch] = t + d
        return counts
    lines = x.strip().split('\n')
    n, q = map(int, lines[0].split())
    tasks = []
    for i in range(1, q+1):
        t,k,d = map(int, lines[i].split())
        tasks.append((t,k,d))
    counts = free_counts(n, tasks)
    output = list(map(int, run(x).strip().split()))
