def test_last_operation_per_cell(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    if n * m * k > 2_000_000:
        return
    ops = []
    for i in range(1, k+1):
        parts = lines[i].split()
        t = int(parts[0])
        num = int(parts[1])
        color = int(parts[2])
        ops.append((t, num, color))
    out = run(x)
    out_lines = out.strip().split('\n')
    grid = [list(map(int, line.split())) for line in out_lines]
    for r in range(1, n+1):
        for c in range(1, m+1):
            last_color = 0
            for idx, (t, num, color) in enumerate(ops):
                if (t == 1 and num == r) or (t == 2 and num == c):
                    last_color = color
            assert grid[r-1][c-1] == last_color, f'Cell ({r},{c}) expected {last_color}, got {grid[r-1][c-1]}'

def test_timestamps(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    row_last = [(-1,0)]*n
    col_last = [(-1,0)]*m
    for idx in range(k):
        parts = lines[idx+1].split()
        t = int(parts[0])
        num = int(parts[1]) - 1
        color = int(parts[2])
        if t == 1:
            row_last[num] = (idx, color)
        else:
            col_last[num] = (idx, color)
    out = run(x)
    out_lines = out.strip().split('\n')
    grid = [list(map(int, line.split())) for line in out_lines]
    for r in range(n):
        for c in range(m):
            r_idx, r_color = row_last[r]
            c_idx, c_color = col_last[c]
            if r_idx >= c_idx:
                expected = r_color
            else:
                expected = c_color
            assert grid[r][c] == expected, f'Cell ({r+1},{c+1}) expected {expected}, got {grid[r][c]}'

def test_last_operation_consistency(run, x):
