    color = int(last_line[2])
    out = run(x)
    out_lines = out.strip().split('\n')
    grid = [list(map(int, line.split())) for line in out_lines]
    if t == 1:
        r = num-1
        for c in range(m):
            assert grid[r][c] == color, f'Cell ({num},{c+1}) should be {color} due to last operation, got {grid[r][c]}'
    else:
        c = num-1
        for r in range(n):
            assert grid[r][c] == color, f'Cell ({r+1},{num}) should be {color} due to last operation, got {grid[r][c]}'

def test_correct_by_simulation(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    if k * max(n, m) > 2_000_000:
        return
    ops = []
    for i in range(1, k+1):
        parts = lines[i].split()
        t = int(parts[0])
        num = int(parts[1])
        color = int(parts[2])
        ops.append((t, num, color))
    grid = [[0]*m for _ in range(n)]
    for t, num, color in ops:
        if t == 1:
            r = num-1
            for c in range(m):
                grid[r][c] = color
        else:
            c = num-1
            for r in range(n):
                grid[r][c] = color
    out = run(x)
