def test_small_brute(run, x):
    n = int(x.strip())
    if n > 8:
        return
    import itertools
    best = -1
    for perm in itertools.permutations(range(1, n + 1)):
        s = sum(i % p for i, p in enumerate(perm, start=1))
        if s > best:
            best = s
    out = run(x).strip()
    val = int(out)
    assert val == best

