def test_format(run, x):
    out = run(x)
    lines = [line.rstrip() for line in out.splitlines() if line.strip() != '']
    assert len(lines) >= 1, "No output"
    first = lines[0].strip()
    assert first in ("Yes", "No"), f"Invalid first line: {first}"
    if first == "Yes":
        assert len(lines) == 3, f"Yes output must have exactly 3 non-empty lines, got {len(lines)}"
        inp_lines = x.strip().splitlines()
        n, m = map(int, inp_lines[0].split())
        second = lines[1].split()
        third = lines[2].split()
        assert len(second) == n, f"Expected {n} numbers in second line, got {len(second)}"
        assert len(third) == m, f"Expected {m} numbers in third line, got {len(third)}"
    else:
        assert len(lines) == 1, f"No output should have exactly 1 non-empty line, got {len(lines)}"


