tests_src:
def test_bruteforce_small(run, x):
    N = int(x.strip())
    if N > 8:
        return
    import itertools
    max_sum = -1
    for perm in itertools.permutations(range(1, N+1)):
        s = sum(i % p for i, p in enumerate(perm, start=1))
        if s > max_sum:
            max_sum = s
    ans = int(run(x).strip())
    assert ans == max_sum

def test_formula_all(run, x):
    N = int(x.strip())
    ans = int(run(x).strip())
    expected = N * (N - 1) // 2
    assert ans == expected

def test_non_negative(run, x):
    ans = int(run(x).strip())
    assert ans >= 0

def test_N1(run, x):
    N = int(x.strip())
    if N == 1:
        ans = int(run(x).strip())
        assert ans == 0

def test_N2(run, x):
    N = int(x.strip())
    if N == 2:
        ans = int(run(x).strip())
        assert ans == 1

def test_N3(run, x):
    N = int(x.strip())
    if N == 3:
        ans = int(run(x).strip())
        assert ans == 3

def test_large_1e9(run, x):
    N = int(x.strip())
    if N == 1000000000:
        ans = int(run(x).strip())
        expected = 1000000000 * 999999999 // 2
        assert ans == expected

def test_large_1e9_minus_1(run, x):
    N = int(x.strip())
    if N == 999999999:
        ans = int(run(x).strip())
        expected = 999999999 * 999999998 // 2
        assert ans == expected

def test_lower_bound(run, x):
    N = int(x.strip())
    ans = int(run(x).strip())
    assert ans >= N * (N - 1) // 2

def test_specific_values(run, x):
    N = int(x.strip())
    if N not in {16, 18, 1000000001}:
        return
    ans = int(run(x).strip())
    expected = N * (N - 1) // 2
    assert ans == expected

