def test_n2_exact(run, x):
    out = run(x)
    ans = int(out.strip())
    data = x.strip().split()
    if len(data) < 2:
        return
    n = int(data[0])
    if n != 2:
        return
    a = list(map(int, data[1:]))
    if len(a) != n:
        return
    if any(v < 1 or v > 10000 for v in a):
        return
    expected = (a[0] + a[1]) ** 2
    assert ans == expected

def test_n4_bruteforce(run, x):
    out = run(x)
    ans = int(out.strip())
    data = x.strip().split()
    if len(data) < 2:
        return
    n = int(data[0])
    if n != 4:
        return
    a = list(map(int, data[1:]))
    if len(a) != n:
        return
    if any(v < 1 or v > 10000 for v in a):
        return
    best = sum(a) ** 2
    indices = [0,1,2,3]
    for i1,j1 in [(0,1),(0,2),(0,3)]:
        used = {i1,j1}
        other = [idx for idx in indices if idx not in used]
        i2,j2 = other[0], other[1]
        s1 = a[i1] + a[j1]
        s2 = a[i2] + a[j2]
        best = min(best, s1*s1 + s2*s2)
    assert ans == best

def test_n6_bruteforce(run, x):
    out = run(x)
    ans = int(out.strip())
    data = x.strip().split()
    if len(data) < 2:
        return
    n = int(data[0])
    if n != 6:
        return
    a = list(map(int, data[1:]))
    if len(a) != n:
        return
    if any(v < 1 or v > 10000 for v in a):
        return
    best = float('inf')
    def dfs(i, groups):
        nonlocal best
        if i == 6:
            if all(len(g) >= 2 for g in groups):
                total = 0
                for g in groups:
                    s = sum(a[idx] for idx in g)
                    total += s * s
                if total < best:
                    best = total
            return
        for g in groups:
            g.append(i)
            dfs(i+1, groups)
            g.pop()
        groups.append([i])
        dfs(i+1, groups)
        groups.pop()
    dfs(0, [])
    assert ans == best

def test_n8_bruteforce(run, x):
    out = run(x)
    ans = int(out.strip())
    data = x.strip().split()
    if len(data) < 2:
        return
    n = int(data[0])
    if n != 8:
        return
    a = list(map(int, data[1:]))
    if len(a) != n:
        return
    if any(v < 1 or v > 10000 for v in a):
        return
    best = float('inf')
    def dfs(i, groups):
        nonlocal best
        if i == 8:
            if all(len(g) >= 2 for g in groups):
                total = 0
                for g in groups:
                    s = sum(a[idx] for idx in g)
                    total += s * s
                if total < best:
                    best = total
            return
        for g in groups:
            g.append(i)
            dfs(i+1, groups)
            g.pop()
        groups.append([i])
        dfs(i+1, groups)
        groups.pop()
    dfs(0, [])
    assert ans == best

def test_pairing_upper_bound(run, x):
    out = run(x)
    ans = int(out.strip())
    data = x.strip().split()
    if len(data) < 2:
        return
    n = int(data[0])
    a = list(map(int, data[1:]))
    if len(a) != n:
        return
    if any(v < 1 or v > 10000 for v in a):
        return
    a_sorted = sorted(a)
    pairing_sum = 0
    for i in range(n // 2):
        pairing_sum += (a_sorted[i] + a_sorted[n-1-i]) ** 2
    assert ans <= pairing_sum

def test_lower_bound_cauchy(run, x):
    out = run(x)
    ans = int(out.strip())
    data = x.strip().split()
    if len(data) < 2:
        return
    n = int(data[0])
    a = list(map(int, data[1:]))
    if len(a) != n:
        return
    if any(v < 1 or v > 10000 for v in a):
        return
    total = sum(a)
    assert ans * n >= 2 * total * total

def test_all_equal(run, x):
    out = run(x)
    ans = int(out.strip())
    data = x.strip().split()
    if len(data) < 2:
        return
    n = int(data[0])
    a = list(map(int, data[1:]))
    if len(a) != n:
        return
    if any(v < 1 or v > 10000 for v in a):
        return
    if all(x == a[0] for x in a):
        v = a[0]
        expected = 2 * n * v * v
        assert ans == expected

def test_sample(run, x):
    out = run(x)
    if x == "4\n8 5 2 3\n":
        assert out.strip() == "164"
    elif x == "6\n1 1 1 2 2 2\n":
        assert out.strip() == "27"

def test_sum_squares_lower_bound(run, x):
    out = run(x)
    ans = int(out.strip())
    data = x.strip().split()
    if len(data) < 2:
        return
    n = int(data[0])
    a = list(map(int, data[1:]))
    if len(a) != n:
        return
    if any(v < 1 or v > 10000 for v in a):
        return
    individual_sq_sum = sum(x * x for x in a)
    assert ans >= individual_sq_sum

def test_output_positive_integer(run, x):
    out = run(x)
    s = out.strip()
    ans = int(s)
    data = x.strip().split()
    if len(data) < 2:
        return
    n = int(data[0])
    a = list(map(int, data[1:]))
    if len(a) != n:
        return
    if any(v < 1 or v > 10000 for v in a):
        return
    assert ans > 0

