def test_small_bruteforce(run, x):
    n = int(x.strip())
    if n > 1000:
        return
    fun_set = set()
    for k in range(1, n+1):
        visited = set()
        current = 1
        visited.add(current)
        while True:
            next_person = (current + k - 1) % n + 1
            if next_person == 1:
                break
            visited.add(next_person)
            current = next_person
        fun = sum(visited)
        fun_set.add(fun)
    expected = sorted(fun_set)
    output = run(x)
    out_str = output.strip()
    if out_str == "":
        out_list = []
    else:
        out_list = list(map(int, out_str.split()))
    assert out_list == expected, f"For n={n}, expected {expected}, got {out_list}"

def test_contains_one(run, x):
    n = int(x.strip())
    output = run(x)
    out_str = output.strip()
    if out_str == "":
        out_list = []
    else:
        out_list = list(map(int, out_str.split()))
    assert 1 in out_list, f"For n={n}, output does not contain 1"

def test_max_correct(run, x):
    n = int(x.strip())
    output = run(x)
    out_str = output.strip()
    if out_str == "":
        out_list = []
    else:
        out_list = list(map(int, out_str.split()))
    assert out_list, "output is empty"
    max_val = max(out_list)
    expected_max = n * (n + 1) // 2
    assert max_val == expected_max, f"For n={n}, expected max {expected_max}, got {max_val}"

def test_sorted(run, x):
    output = run(x)
    out_str = output.strip()
    if out_str == "":
        out_list = []
    else:
        out_list = list(map(int, out_str.split()))
    for i in range(len(out_list)-1):
        assert out_list[i] < out_list[i+1], f"Output not strictly increasing: {out_list}"

def test_all_integers(run, x):
    output = run(x)
    out_str = output.strip()
    if out_str == "":
        assert False, "Empty output"
    tokens = out_str.split()
    for t in tokens:
        if not t.isdigit():
            assert False, f"Non-integer token: {t}"
    out_list = list(map(int, tokens))
    for v in out_list:
        assert v > 0, f"Non-positive value {v}"

def test_output_size_bounded_by_divisors(run, x):
    n = int(x.strip())
    output = run(x)
    out_str = output.strip()
    if out_str == "":
        out_list = []
    else:
        out_list = list(map(int, out_str.split()))
    dcount = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            dcount += 1
            if i * i != n:
                dcount += 1
        i += 1
    assert len(out_list) <= dcount, f"For n={n}, output size {len(out_list)} exceeds divisor count {dcount}"

def test_prime_n(run, x):
    n = int(x.strip())
    if n < 2:
        return
    if n % 2 == 0:
        if n == 2:
            pass
        else:
            return
    i = 3
    while i * i <= n:
        if n % i == 0:
            return
        i += 2
    # n is prime
    output = run(x)
    out_str = output.strip()
    if out_str == "":
        out_list = []
    else:
        out_list = list(map(int, out_str.split()))
    expected = [1, n * (n + 1) // 2]
    assert out_list == expected, f"For prime n={n}, expected {expected}, got {out_list}"

def test_divisor_formula_match(run, x):
    n = int(x.strip())
    divisors = set()
    i = 1
    while i * i <= n:
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
        i += 1
    expected_set = set()
    for d in divisors:
        y = n // d
        val = y + d * y * (y - 1) // 2
        expected_set.add(val)
    expected = sorted(expected_set)
    output = run(x)
    out_str = output.strip()
    if out_str == "":
        out_list = []
    else:
        out_list = list(map(int, out_str.split()))
    assert out_list == expected, f"For n={n}, expected {expected}, got {out_list}"

def test_no_duplicates(run, x):
    output = run(x)
    out_str = output.strip()
    if out_str == "":
        out_list = []
    else:
        out_list = list(map(int, out_str.split()))
    assert len(out_list) == len(set(out_list)), f"Output contains duplicates: {out_list}"

def test_at_least_two_for_n_gt_1(run, x):
    n = int(x.strip())
    if n <= 1:
        return
    output = run(x)
    out_str = output.strip()
    if out_str == "":
        out_list = []
    else:
        out_list = list(map(int, out_str.split()))
    assert len(out_list) >= 2, f"For n={n}, output has less than 2 values: {out_list}"

