def test_nonnegative(run, x):
    out = run(x).strip()
    ans = int(out)
    assert ans >= 0

def test_integer(run, x):
    out = run(x).strip()
    try:
        int(out)
    except ValueError:
        assert False, 'Output must be an integer'

def test_no_o_zero(run, x):
    s = x.strip()
    if 'o' not in s:
        out = run(x).strip()
        ans = int(out)
        assert ans == 0

def test_no_vv_zero(run, x):
    s = x.strip()
    if 'vv' not in s:
        out = run(x).strip()
        ans = int(out)
        assert ans == 0

def test_brute_force_triples(run, x):
    s = x.strip()
    n = len(s)
    if n > 50:
        return
    cnt = 0
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                if i+1 < n and s[i] == 'v' and s[i+1] == 'v' and \
                   s[j] == 'o' and \
                   k+1 < n and s[k] == 'v' and s[k+1] == 'v':
                    cnt += 1
    out = run(x).strip()
    ans = int(out)
    assert ans == cnt

def test_left_right_sum(run, x):
    s = x.strip()
    n = len(s)
    # left_pairs[i] = number of "vv" pairs ending before i
    left = [0] * (n+1)
    for i in range(1, n):
        left[i+1] = left[i] + (1 if s[i] == 'v' and s[i-1] == 'v' else 0)
    # right_pairs[i] = number of "vv" pairs starting after i
    right = [0] * (n+1)
    for i in range(n-2, -1, -1):
        right[i] = right[i+1] + (1 if s[i] == 'v' and s[i+1] == 'v' else 0)
    total = 0
    for i in range(n):
        if s[i] == 'o':
            total += left[i] * right[i]
    out = run(x).strip()
    ans = int(out)
    assert ans == total

def test_reversal(run, x):
    s = x.strip()
    n = len(s)
    if n > 50:
        return
    rev = s[::-1]
    cnt = 0
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                if i+1 < n and rev[i] == 'v' and rev[i+1] == 'v' and \
                   rev[j] == 'o' and \
                   k+1 < n and rev[k] == 'v' and rev[k+1] == 'v':
                    cnt += 1
    out = run(x).strip()
    ans = int(out)
    assert ans == cnt

def test_upper_bound(run, x):
    s = x.strip()
    n = len(s)
    pairs = 0
    for i in range(n-1):
        if s[i] == 'v' and s[i+1] == 'v':
            pairs += 1
    out = run(x).strip()
    ans = int(out)
    assert ans <= n * pairs * pairs

def test_single_o_product(run, x):
    s = x.strip()
    if s.count('o') == 1:
        n = len(s)
        idx = s.find('o')
        left_pairs = 0
        for i in range(idx - 1):
            if s[i] == 'v' and s[i+1] == 'v':
                left_pairs += 1
        right_pairs = 0
        for i in range(idx + 1, n - 1):
            if s[i] == 'v' and s[i+1] == 'v':
                right_pairs += 1
        out = run(x).strip()
        ans = int(out)
        assert ans == left_pairs * right_pairs

def test_alternative_sum(run, x):
    s = x.strip()
    n = len(s)
    if n > 10000:
        return
    total = 0
    pair_starts = [i for i in range(n-1) if s[i] == 'v' and s[i+1] == 'v']
    o_indices = [i for i in range(n) if s[i] == 'o']
    for i in pair_starts:
        for j in o_indices:
            if j > i+1:
                right = sum(1 for k in pair_starts if k > j)
                total += right
    out = run(x).strip()
    ans = int(out)
    assert ans == total

def test_bounds(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0].strip())
    out = run(x).strip()
    ans = int(out)
    assert 1 <= ans <= n

def test_ge_max_freq(run, x):
    lines = x.strip().splitlines()
    b = list(map(int, lines[1].split()))
    from collections import Counter
    freq = max(Counter(b).values())
    out = run(x).strip()
    ans = int(out)
    assert ans >= freq

