def test_brute_force(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0].strip())
    b = list(map(int, lines[1].split()))
    # Guard: brute force only for n ≤ 10 (safe for fixed inputs)
    if n > 10:
        return
    max_len = 0
    for mask in range(1, 1 << n):
        seq = [b[i] for i in range(n) if (mask >> i) & 1]
        k = len(seq)
        if k <= 2:
            max_len = max(max_len, k)
        else:
            first = seq[0]
            second = seq[1]
            ok = True
            for idx, val in enumerate(seq):
                if idx % 2 == 0:
                    if val != first:
                        ok = False
                        break
                else:
                    if val != second:
                        ok = False
                        break
            if ok:
                max_len = max(max_len, k)
    out = run(x).strip()
    ans = int(out)
    assert ans == max_len

