      "name": "test_forbidden_le_total",
      "source": "def test_forbidden_le_total(run, x):
    import collections
    data = x.strip().split()
    it = iter(data)
    n = int(next(it))
    x_idx = int(next(it))
    y_idx = int(next(it))
    adj = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        a = int(next(it))
        b = int(next(it))
        adj[a].append(b)
        adj[b].append(a)
    # connectivity check
    visited = set()
    stack = [1]
    while stack:
        cur = stack.pop()
        if cur in visited:
            continue
        visited.add(cur)
        for nb in adj[cur]:
            if nb not in visited:
                stack.append(nb)
    if len(visited) != n:
        return
    # find path from x to y
    parent = {x_idx: None}
    q = collections.deque([x_idx])
    while q:
        cur = q.popleft()
        if cur == y_idx:
            break
        for nb in adj[cur]:
            if nb not in parent:
                parent[nb] = cur
                q.append(nb)
    path = []
    cur = y_idx
    while cur is not None:
        path.append(cur)
        cur = parent[cur]
    path.reverse()
    x_next = path[1]
    y_prev = path[-2]
    def dfs_size(start, forbidden_edge):
        visited = set()
        stack = [start]
        while stack:
            cur = stack.pop()
            if cur in visited:
                continue
            visited.add(cur)
            for nb in adj[cur]:
                if (cur == forbidden_edge[0] and nb == forbidden_edge[1]) or (cur == forbidden_edge[1] and nb == forbidden_edge[0]):
                    continue
                if nb not in visited:
                    stack.append(nb)
        return len(visited)
    size_x = dfs_size(x_idx, (x_idx, x_next))
    size_y = dfs_size(y_idx, (y_idx, y_prev))
    forbidden = size_x * size_y
    total = n * (n - 1)
    assert forbidden <= total"
