      "name": "test_brute_force_dfs",
      "source": "def test_brute_force_dfs(run, x):
    data = x.strip().split()
    it = iter(data)
    n = int(next(it))
    x_idx = int(next(it))
    y_idx = int(next(it))
    adj = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        a = int(next(it))
        b = int(next(it))
        adj[a].append(b)
        adj[b].append(a)
    # connectivity check
    visited = set()
    stack = [1]
    while stack:
        cur = stack.pop()
        if cur in visited:
            continue
        visited.add(cur)
        for nb in adj[cur]:
            if nb not in visited:
                stack.append(nb)
    if len(visited) != n:
        return
    allowed = 0
    for u in range(1, n + 1):
        for v in range(1, n + 1):
            if u == v:
                continue
            stack = [(u, [u])]
            visited = {u}
            found_path = None
            while stack:
                cur, path = stack.pop()
                if cur == v:
                    found_path = path
                    break
                for nb in adj[cur]:
                    if nb not in visited:
                        visited.add(nb)
                        stack.append((nb, path + [nb]))
            ix = found_path.index(x_idx) if x_idx in found_path else -1
            iy = found_path.index(y_idx) if y_idx in found_path else -1
            if not (ix != -1 and iy != -1 and ix < iy):
                allowed += 1
    output = run(x).strip()
    assert int(output) == allowed"
