def test_odd_length_zero(run, x):
    tokens = x.strip().split()
    if len(tokens) < 2:
        return
    n = int(tokens[0])
    m = int(tokens[1])
    if len(tokens) < 2 + n:
        return
    arr = list(map(int, tokens[2:2+n]))
    if len(tokens) < 2 + n + 2*m:
        return
    queries = []
    pos = 2 + n
    for i in range(m):
        l = int(tokens[pos]); r = int(tokens[pos+1])
        queries.append((l, r))
        pos += 2
    out = run(x).split()
    if len(out) != m:
        return
    for i, (l, r) in enumerate(queries):
        if not (1 <= l <= r <= n):
            continue
        length = r - l + 1
        if length % 2 == 1:
            assert out[i] == '0'

def test_one_implies_even(run, x):
    tokens = x.strip().split()
    if len(tokens) < 2:
        return
    n = int(tokens[0])
    m = int(tokens[1])
    if len(tokens) < 2 + n:
        return
    arr = list(map(int, tokens[2:2+n]))
    if len(tokens) < 2 + n + 2*m:
        return
    queries = []
    pos = 2 + n
    for i in range(m):
        l = int(tokens[pos]); r = int(tokens[pos+1])
        queries.append((l, r))
        pos += 2
    out = run(x).split()
    if len(out) != m:
        return
    for i, (l, r) in enumerate(queries):
        if not (1 <= l <= r <= n):
            continue
        if out[i] == '1':
            length = r - l + 1
            assert length % 2 == 0

def test_one_implies_sum_zero(run, x):
    tokens = x.strip().split()
    if len(tokens) < 2:
        return
    n = int(tokens[0])
    m = int(tokens[1])
