def test_dijkstra_oracle(run, x):
    import heapq
    a,b,x_val,y_val = map(int, x.strip().split())
    start = (0, a)
    target = (1, b)
    dist = {}
    pq = [(0, start)]
    dist[start] = 0
    while pq:
        d, (building, floor) = heapq.heappop(pq)
        if d != dist.get((building, floor)):
            continue
        if (building, floor) == target:
            break
        if floor > 1:
            new = (building, floor-1)
            nd = d + y_val
            if nd < dist.get(new, float('inf')):
                dist[new] = nd
                heapq.heappush(pq, (nd, new))
        if floor < 100:
            new = (building, floor+1)
            nd = d + y_val
            if nd < dist.get(new, float('inf')):
                dist[new] = nd
                heapq.heappush(pq, (nd, new))
        if building == 0:
            new = (1, floor)
            nd = d + x_val
            if nd < dist.get(new, float('inf')):
                dist[new] = nd
                heapq.heappush(pq, (nd, new))
            if floor >= 2:
                new = (1, floor-1)
                nd = d + x_val
                if nd < dist.get(new, float('inf')):
                    dist[new] = nd
                    heapq.heappush(pq, (nd, new))
        else:
            new = (0, floor)
            nd = d + x_val
            if nd < dist.get(new, float('inf')):
                dist[new] = nd
                heapq.heappush(pq, (nd, new))
            if floor <= 99:
                new = (0, floor+1)
                nd = d + x_val
                if nd < dist.get(new, float('inf')):
                    dist[new] = nd
                    heapq.heappush(pq, (nd, new))
    ans = dist[target]
    out = run(x).strip()
    assert out.isdigit()
    assert int(out) == ans

