    a,b,x_val,y_val = map(int, x.strip().split())
    y_eff = min(y_val, 2*x_val)
    if a > b:
        lower = x_val + (a - b - 1) * y_eff
    else:
        lower = x_val + (b - a) * y_eff
    out = run(x).strip()
    assert out.isdigit()
    assert int(out) >= lower

def test_enumeration_oracle(run, x):
    a,b,x_val,y_val = map(int, x.strip().split())
    y_eff = min(y_val, 2*x_val)
    best = float('inf')
    for i in range(1, 101):
        cost = y_eff * abs(a - i) + x_val + y_eff * abs(b - i)
        best = min(best, cost)
        if i + 1 <= 100:
            cost = y_eff * abs(a - (i+1)) + x_val + y_eff * abs(b - i)
            best = min(best, cost)
    out = run(x).strip()
    assert out.isdigit()
    assert int(out) == best

