tests_src:
def test_correct_via_sorted_diffs(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n_k = list(map(int, lines[0].split()))
    if len(n_k) < 2:
        return
    n, k = n_k[0], n_k[1]
    a = list(map(int, lines[1].split()))
    if len(a) != n:
        a = list(map(int, ' '.join(lines[1:]).split()))
        if len(a) != n:
            return
    if n == 1:
        correct = 0
    else:
        diffs = [a[i+1] - a[i] for i in range(n-1)]
        diffs.sort()
        need = n - k
        correct = sum(diffs[:need])
    out = run(x).strip()
    if out == '':
        assert False, 'empty output'
    ans = int(out)
    assert ans == correct, f'Expected {correct}, got {ans}'

def test_correct_via_total_span_minus_largest(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    if len(a) != n:
        a = list(map(int, ' '.join(lines[1:]).split()))
        if len(a) != n:
            return
    total_span = a[-1] - a[0]
    if k == 1:
        correct = total_span
    else:
        diffs = [a[i+1] - a[i] for i in range(n-1)]
        diffs.sort(reverse=True)
        sum_largest = sum(diffs[:k-1])
        correct = total_span - sum_largest
    out = run(x).strip()
    ans = int(out)
    assert ans == correct, f'Expected {correct}, got {ans}'

