def test_output_integer(run, x):
    out = run(x).strip()
    try:
        int(out)
        is_int = True
    except ValueError:
        is_int = False
    assert is_int, "Output must be an integer"


def test_output_nonnegative(run, x):
    out = run(x).strip()
    try:
        val = int(out)
    except ValueError:
        assert False, "Output must be an integer"
    assert val >= 0, "Output must be non-negative"


def test_output_zero_for_small_n(run, x):
    out = run(x).strip()
    lines = x.strip().splitlines()
    n = int(lines[0])
    if n <= 2:
        assert out == "0", f"For n={n}, output must be 0"


def test_output_upper_bound(run, x):
    out = run(x).strip()
    lines = x.strip().splitlines()
    n = int(lines[0])
    if n >= 3:
        val = int(out)
        assert val <= n-2, f"Output {val} exceeds maximum possible {n-2}"


def test_output_zero_all_equal(run, x):
    out = run(x).strip()
    lines = x.strip().splitlines()
    a = list(map(int, lines[1].split()))
    if len(set(a)) == 1:
        assert out == "0", f"For constant array, output must be 0"


def test_output_zero_strictly_monotonic(run, x):
    out = run(x).strip()
    lines = x.strip().splitlines()
    a = list(map(int, lines[1].split()))
    n = len(a)
    if n >= 2:
        increasing = all(a[i] < a[i+1] for i in range(n-1))
        decreasing = all(a[i] > a[i+1] for i in range(n-1))
        if increasing or decreasing:
            assert out == "0", f"For strictly monotonic array, output must be 0"


def test_oracle_direct(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    cnt = 0
    for i in range(1, n-1):
        if (a[i] > a[i-1] and a[i] > a[i+1]) or (a[i] < a[i-1] and a[i] < a[i+1]):
            cnt += 1
    out = run(x).strip()
    assert out == str(cnt), f"Output {out} does not match correct count {cnt}"


def test_example_from_statement(run, x):
    out = run(x).strip()
    lines = x.strip().splitlines()
    if len(lines) >= 2:
        n = int(lines[0])
        a = list(map(int, lines[1].split()))
        if n == 4 and a == [1, 5, 2, 5]:
            assert out == "2", f"For example input, output must be 2"


def test_minimal_nonzero(run, x):
    # Inputs with exactly one local extremum
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    # Check if this array has exactly one local extremum
    cnt = 0
    for i in range(1, n-1):
        if (a[i] > a[i-1] and a[i] > a[i+1]) or (a[i] < a[i-1] and a[i] < a[i+1]):
            cnt += 1
    if cnt == 1:
        out = run(x).strip()
        assert out == "1", f"Array with exactly one extremum should output 1, got {out}"


def test_alternating_pattern(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    # Check if array alternates between two values (like [1,2,1,2,...])
    # For such patterns with n≥3, every interior element is an extremum
    if n >= 3 and len(set(a)) == 2:
        # Verify alternating pattern
        val1, val2 = sorted(set(a))
        expected_pattern1 = [val1, val2] * (n//2) + ([val1] if n%2 else [])
        expected_pattern2 = [val2, val1] * (n//2) + ([val2] if n%2 else [])
        if a == expected_pattern1 or a == expected_pattern2:
            expected = n-2  # All interior elements are extrema
            out = run(x).strip()
            assert out == str(expected), f"Alternating pattern should yield {expected}, got {out}"

