def test_brute_force_small(run, x):
    lines = x.strip().split('\n')
    if not lines:
        return
    first = lines[0].split()
    if len(first) < 2:
        return
    n = int(first[0])
    m = int(first[1])
    if n + m > 10:
        return
    verticals = []
    for i in range(n):
        verticals.append(int(lines[1 + i].strip()))
    horizontals = []
    for i in range(m):
        parts = lines[1 + n + i].split()
        x1 = int(parts[0])
        x2 = int(parts[1])
        y = int(parts[2])
        horizontals.append((x1, x2, y))
    total = n + m
    best = None
    for mask in range(1 << total):
        removed_vert = [False]*n
        removed_horiz = [False]*m
        for i in range(n):
            if mask & (1 << i):
                removed_vert[i] = True
        for i in range(m):
            if mask & (1 << (n + i)):
                removed_horiz[i] = True
        rem_verts = [vert for i, vert in enumerate(verticals) if not removed_vert[i]]
        rem_verts.sort()
        intervals = []
        left = 1
        for v in rem_verts:
            right = v
            if left <= right:
                intervals.append((left, right))
            left = v + 1
        if left <= 10**9:
            intervals.append((left, 10**9))
        start_interval = None
        for idx, (L,R) in enumerate(intervals):
            if L <= 1 <= R:
                start_interval = idx
                break
        if start_interval is None:
            continue
        row_to_segments = {}
        for i, (x1,x2,y) in enumerate(horizontals):
            if not removed_horiz[i]:
                row_to_segments.setdefault(y, []).append((x1, x2))
        for y in row_to_segments:
            row_to_segments[y].sort()
        rows_set = set([1, 10**9])
        rows_set.update(row_to_segments.keys())
        rows = sorted(rows_set)
        reachable = {start_interval}
        for i in range(len(rows)-1):
            cur_row = rows[i]
            segments = row_to_segments.get(cur_row, [])
            new_reachable = set()
            for idx in reachable:
                L,R = intervals[idx]
                current = L
                covered = False
                for seg in segments:
                    s1, s2 = seg
                    if s2 < L:
                        continue
                    if s1 > R:
                        break
                    if s1 > current:
                        covered = False
                        break
                    current = max(current, s2 + 1)
                    if current > R:
                        covered = True
                        break
                else:
                    if current <= R:
                        covered = False
                if not covered:
                    new_reachable.add(idx)
            reachable = new_reachable
            if not reachable:
                break
        if reachable:
            removals = bin(mask).count('1')
            if best is None or removals < best:
                best = removals
    if best is None:
        best = n + m
    out = run(x)
    ans = int(out.strip())
    assert ans == best, f"For small input, expected {best}, got {ans}"

