def test_exact_bruteforce(run, x):
    lines = x.strip().splitlines()
    if not lines:
        return
    n = int(lines[0].strip())
    if n > 11:
        return
    colors = list(map(int, lines[1].split()))
    edges = []
    for line in lines[2:]:
        if line.strip():
            u, v = map(int, line.split())
            edges.append((u-1, v-1))
    if len(edges) != n-1:
        return
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    start = 0
    for i, c in enumerate(colors):
        if c == 1:
            start |= (1 << i)
    target_all0 = 0
    target_all1 = (1 << n) - 1
    if start == target_all0 or start == target_all1:
        correct = 0
    else:
        from collections import deque
        dist = {start: 0}
        q = deque([start])
        while q:
            state = q.popleft()
            visited = [False]*n
            for v in range(n):
                if not visited[v]:
                    col = (state >> v) & 1
                    comp = []
                    stack = [v]
                    visited[v] = True
                    while stack:
                        u = stack.pop()
                        comp.append(u)
                        for w in adj[u]:
                            if not visited[w] and ((state >> w) & 1) == col:
                                visited[w] = True
                                stack.append(w)
                    new_state = state
                    for u in comp:
                        new_state ^= (1 << u)
                    if new_state not in dist:
                        dist[new_state] = dist[state] + 1
                        if new_state == target_all0 or new_state == target_all1:
                            correct = dist[new_state]
                            break
                        q.append(new_state)
            else:
                continue
            break
    ans = int(run(x).strip())
    assert ans == correct

