def test_format(run, x):
    import re
    out = run(x)
    assert re.fullmatch(r'\d+\n', out), 'Output must be a single integer followed by newline.'

def test_nonnegative(run, x):
    out = run(x)
    ans = int(out.strip())
    assert ans >= 0, 'Noise cannot be negative.'

def test_upper_bound(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    strings = [line.strip() for line in lines[1:1+n]]
    total_s = sum(s.count('s') for s in strings)
    total_h = sum(s.count('h') for s in strings)
    out = run(x)
    ans = int(out.strip())
    assert ans <= total_s * total_h, 'Noise cannot exceed total_s * total_h.'

def test_lower_bound_input_order(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    strings = [line.strip() for line in lines[1:1+n]]
    # compute noise of input order
    cs = 0
    noise = 0
    for s in strings:
        for ch in s:
            if ch == 's':
                cs += 1
            else:
                noise += cs
    out = run(x)
    ans = int(out.strip())
    assert ans >= noise, 'Maximum noise must be at least noise of input order.'

def test_single_string(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    if n != 1:
        return
    s = lines[1].strip()
    # compute noise of single string
    cs = 0
    noise = 0
    for ch in s:
        if ch == 's':
            cs += 1
        else:
            noise += cs
    out = run(x)
    ans = int(out.strip())
    assert ans == noise, 'For a single string, noise is fixed.'

def test_two_strings(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    if n != 2:
        return
    s1 = lines[1].strip()
    s2 = lines[2].strip()
    # noise of two orders
    def noise_order(first, second):
        cs = 0
        ans = 0
        for ch in first:
            if ch == 's':
                cs += 1
            else:
                ans += cs
        for ch in second:
            if ch == 's':
                cs += 1
            else:
                ans += cs
        return ans
    opt = max(noise_order(s1, s2), noise_order(s2, s1))
    out = run(x)
    ans = int(out.strip())
    assert ans == opt, 'For two strings, answer must be max of two orders.'

def test_three_strings(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    if n != 3:
        return
    from itertools import permutations
    strings = [lines[i].strip() for i in range(1, 4)]
    def noise_of_list(lst):
        cs = 0
        ans = 0
        for s in lst:
            for ch in s:
                if ch == 's':
                    cs += 1
                else:
                    ans += cs
        return ans
    best = max(noise_of_list(p) for p in permutations(strings))
    out = run(x)
    ans = int(out.strip())
    assert ans == best, 'For three strings, answer must be max over permutations.'

def test_greedy_optimal(run, x):
    import functools
    lines = x.strip().splitlines()
    n = int(lines[0])
    strings = [line.strip() for line in lines[1:1+n]]
    # comparator: a before b if s_a * h_b > s_b * h_a
    def cmp(a, b):
        s_a = a.count('s')
        h_a = a.count('h')
        s_b = b.count('s')
        h_b = b.count('h')
        if s_a * h_b > s_b * h_a:
            return -1
        elif s_a * h_b < s_b * h_a:
            return 1
        else:
            return 0
    sorted_strings = sorted(strings, key=functools.cmp_to_key(cmp))
    cs = 0
    noise = 0
    for s in sorted_strings:
        for ch in s:
            if ch == 's':
                cs += 1
            else:
                noise += cs
    out = run(x)
    ans = int(out.strip())
    assert ans == noise, 'Greedy order is proven optimal.'

def test_sum_individual_noise(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    strings = [line.strip() for line in lines[1:1+n]]
    indiv_sum = 0
    for s in strings:
        cs = 0
        for ch in s:
            if ch == 's':
                cs += 1
            else:
                indiv_sum += cs
    out = run(x)
    ans = int(out.strip())
    assert ans >= indiv_sum, 'Total noise must be at least sum of individual noises.'

def test_four_strings_small(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    if n != 4:
        return
    strings = [lines[i].strip() for i in range(1, 5)]
    total_len = sum(len(s) for s in strings)
    if total_len > 15:
        return
    from itertools import permutations
    def noise_of_list(lst):
        cs = 0
        ans = 0
        for s in lst:
            for ch in s:
                if ch == 's':
                    cs += 1
                else:
                    ans += cs
        return ans
    best = max(noise_of_list(p) for p in permutations(strings))
    out = run(x)
    ans = int(out.strip())
    assert ans == best, 'For four small strings, answer must be max over permutations.'

