def test_exact_bruteforce(run, x):
    import sys
    lines = x.strip().split('\n')
    n = int(lines[1])
    s = lines[2].strip()
    if n > 11:
        return
    def is_logical(config):
        n = len(config)
        for i in range(n):
            left = (i-1)%n
            right = (i+1)%n
            attacks = 0
            attacker = None
            if config[left] == 'R':
                attacks += 1
                attacker = 'left'
            if config[right] == 'L':
                attacks += 1
                attacker = 'right'
            if attacks == 1:
                if attacker == 'left' and config[i] != 'L':
                    return False
                if attacker == 'right' and config[i] != 'R':
                    return False
        return True
    best = n+1
    for mask in range(1<<n):
        flipped = list(s)
        flips = 0
        for i in range(n):
            if (mask>>i) & 1:
                flips += 1
                flipped[i] = 'L' if s[i]=='R' else 'R'
        config = ''.join(flipped)
        if is_logical(config):
            if flips < best:
                best = flips
    expected = best
    output = int(run(x).strip())
    assert output == expected

def test_bounds(run, x):
    lines = x.strip().split('\n')
    n = int(lines[1])
    out = run(x).strip()
    val = int(out)
    assert 0 <= val <= n

def test_all_same(run, x):
    lines = x.strip().split('\n')
    n = int(lines[1])
    s = lines[2].strip()
    if len(set(s)) == 1:
        out = int(run(x).strip())
        expected = (n+2)//3
        assert out == expected

def test_alternating(run, x):
    lines = x.strip().split('\n')
    n = int(lines[1])
    s = lines[2].strip()
    alt = True
    for i in range(n):
        if s[i] == s[(i+1)%n]:
            alt = False
            break
    if alt:
        out = int(run(x).strip())
        assert out == 0

def test_examples(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 3:
        return
    t = int(lines[0])
    if t != 1:
        return
    n = int(lines[1])
    s = lines[2].strip()
    out = int(run(x).strip())
    if n == 4 and s == 'RLRL':
        assert out == 0
    if n == 6 and s == 'LRRRRL':
        assert out == 1
    if n == 8 and s == 'RLLRRRLL':
        assert out == 1
    if n == 12 and s == 'LLLLRRLRRRLL':
        assert out == 3
    if n == 5 and s == 'RRRRR':
        assert out == 2

