    def is_logical(config):
        n=len(config)
        for i in range(n):
            left = (i-1)%n
            right = (i+1)%n
            attacks = 0
            attacker = None
            if config[left] == 'R':
                attacks += 1
                attacker = 'left'
            if config[right] == 'L':
                attacks += 1
                attacker = 'right'
            if attacks == 1:
                if attacker == 'left' and config[i] != 'L':
                    return False
                if attacker == 'right' and config[i] != 'R':
                    return False
        return True
    best = 4
    for mask in range(1<<3):
