        return
    n = int(parts[0])
    m = int(parts[1])
    if n == 1:
        out = run(x).strip()
        a = int(out)
        assert a == 1

def test_positive(run, x):
    parts = x.strip().split()
    if not parts:
        return
    n = int(parts[0])
    m = int(parts[1])
    if n == 1:
        return
    out = run(x).strip()
    a = int(out)
    def count(a):
        if a == m:
            return 0
        if a < m:
            return (a + m - 1) // 2
        else:
            return n + 1 - (a + m + 2) // 2
    cnt = count(a)
    assert cnt > 0

def test_consistency(run, x):
    parts = x.strip().split()
    if not parts:
        return
    n = int(parts[0])
    m = int(parts[1])
    if n == 1:
        return
    out = run(x).strip()
    a = int(out)
    def count(a):
        if a == m:
            return 0
        if a < m:
            return (a + m - 1) // 2
        else:
            return n + 1 - (a + m + 2) // 2
    if a == m - 1:
        if m < n:
            cnt1 = count(m - 1)
            cnt2 = count(m + 1)
            assert cnt1 >= cnt2
    elif a == m + 1:
        if m > 1:
            cnt1 = count(m - 1)
            cnt2 = count(m + 1)
            assert cnt2 > cnt1
    else:
        assert False, "a must be adjacent to m"

def test_brute_force_small_n(run, x):
    parts = x.strip().split()
    if not parts:
        return
    n = int(parts[0])
    m = int(parts[1])
    if n > 1000:
        return
    out = run(x).strip()
    a_out = int(out)
    best_cnt = -1
    best_a = None
    for a in range(1, n + 1):
        cnt = 0
        for c in range(1, n + 1):
            if abs(c - a) < abs(c - m):
                cnt += 1
        if cnt > best_cnt or (cnt == best_cnt and a < best_a):
            best_cnt = cnt
            best_a = a
    assert a_out == best_a

