def test_balanced(run, x):
    output = run(x)
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n = int(lines[0])
    s = lines[1]
    if s.count('?') % 2 != 0:
        return
    left_sum = 0
    left_q = 0
    right_sum = 0
    right_q = 0
    for i in range(n):
        if i < n//2:
            if s[i] == '?':
                left_q += 1
            else:
                left_sum += int(s[i])
        else:
            if s[i] == '?':
                right_q += 1
            else:
                right_sum += int(s[i])
    if left_q == right_q:
        expected = "Bicarp" if left_sum == right_sum else "Monocarp"
        assert output.strip() == expected

