def test_output_integer(run, x):
    out_str = run(x).strip()
    assert out_str.isdigit()
    out = int(out_str)
    assert out >= 1

def test_output_le_10(run, x):
    out_str = run(x).strip()
    assert out_str.isdigit()
    out = int(out_str)
    assert out <= 10

def test_condition_satisfied(run, x):
    out_str = run(x).strip()
    out = int(out_str)
    k, r = map(int, x.split())
    assert (k * out) % 10 in (0, r)

def test_minimality(run, x):
    out_str = run(x).strip()
    out = int(out_str)
    k, r = map(int, x.split())
    for i in range(1, out):
        assert (k * i) % 10 not in (0, r)

def test_example1(run, x):
    out_str = run(x).strip()
    out = int(out_str)
    if x == "117 3\n":
        assert out == 9

def test_example2(run, x):
    out_str = run(x).strip()
    out = int(out_str)
    if x == "237 7\n":
        assert out == 1

def test_example3(run, x):
    out_str = run(x).strip()
    out = int(out_str)
    if x == "15 2\n":
        assert out == 2

def test_brute_force(run, x):
    out_str = run(x).strip()
    out = int(out_str)
    k, r = map(int, x.split())
    correct = None
    for i in range(1, 11):
        if (k * i) % 10 in (0, r):
            correct = i
            break
    assert out == correct

def test_k_mod10_zero(run, x):
    out_str = run(x).strip()
    out = int(out_str)
    k, r = map(int, x.split())
    if k % 10 == 0:
        assert out == 1

def test_r_equals_k_mod10(run, x):
    out_str = run(x).strip()
    out = int(out_str)
    k, r = map(int, x.split())
    if r == k % 10:
        assert out == 1

