def test_monotonic_left(run, x):
    n_str, m_str = x.strip().split()
    n = int(n_str)
    m = int(m_str)
    out = run(x).strip()
    a = int(out)
    if a <= 1:
        return
    def win(a_val):
        if a_val == m:
            return 0
        if a_val < m:
            return (a_val + m - 1) // 2
        else:
            return n - (a_val + m) // 2
    assert win(a) >= win(a - 1)


