        return
    out = run(x).strip()
    a = int(out)
    def win(a_val):
        if a_val == m:
            return 0
        if a_val < m:
            return (a_val + m - 1) // 2
        else:
            return n - (a_val + m) // 2
    assert win(a) > 0


def test_correct_by_win(run, x):
    n_str, m_str = x.strip().split()
    n = int(n_str)
    m = int(m_str)
    out = run(x).strip()
    a = int(out)
    def win(a_val):
        if a_val == m:
            return 0
        if a_val < m:
            return (a_val + m - 1) // 2
        else:
            return n - (a_val + m) // 2
    candidates = []
    if m - 1 >= 1:
        candidates.append(m - 1)
    if m + 1 <= n:
        candidates.append(m + 1)
    if not candidates:
        assert a == 1 and win(a) == 0
        return
    max_win = max(win(c) for c in candidates)
    assert win(a) == max_win
    if len(candidates) == 2 and win(candidates[0]) == win(candidates[1]):
        assert a == candidates[0]

