def test_small_n_bruteforce(run, x):
    n,k = map(int, x.split())
    if n <= 20:
        from itertools import combinations
        max_r = min(k, n)
        best = 0
        for r in range(1, max_r+1):
            for comb in combinations(range(1, n+1), r):
                xor = 0
                for v in comb:
                    xor ^= v
                if xor > best:
                    best = xor
        out = int(run(x).strip())
        assert out == best

def test_bit5_kge2(run, x):
    n,k = map(int, x.split())
    if n.bit_length() == 5 and k >= 2:
        out = int(run(x).strip())
        assert out == 31

def test_power_of_two_kge2(run, x):
    n,k = map(int, x.split())
    if k >= 2 and (n & (n-1)) == 0:
        out = int(run(x).strip())
        expected = 2*n - 1
        assert out == expected

