    n,k = map(int, x.split())
    if k >= 2:
        out = int(run(x).strip())
        assert out.bit_length() == n.bit_length()

def test_output_odd_for_kge2(run, x):
    n,k = map(int, x.split())
    if k >= 2:
        out = int(run(x).strip())
        assert out % 2 == 1

def test_k2_small_n(run, x):
    n,k = map(int, x.split())
    if k == 2 and n <= 200:
        best = 0
        for i in range(1, n+1):
            for j in range(i+1, n+1):
                val = i ^ j
                if val > best:
                    best = val
        out = int(run(x).strip())
        assert out == best

def test_output_upper_bound(run, x):
    n,k = map(int, x.split())
    out = int(run(x).strip())
    assert out < (1 << n.bit_length())

