    k, r = map(int, x.strip().split())
    out = run(x).strip()
    n = int(out)
    if n == 10:
        for i in range(1, 10):
            assert (k * i) % 10 not in (0, r)

def test_depends_only_on_last_digit(run, x):
    k, r = map(int, x.strip().split())
    d = k % 10
    out = run(x).strip()
    n = int(out)
    ans = None
    for i in range(1, 11):
        if (d * i) % 10 in (0, r):
            ans = i
            break
    assert n == ans

