def test_oracle_small(run, x):
    out = int(run(x).strip())
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 10:
        return
    p = list(map(int, lines[1].split()))
    pos = [0] * n
    for i, val in enumerate(p):
        pos[val - 1] = i
    max_len = 1
    for start in range(n):
        length = 1
        cur = start
        while cur + 1 < n and pos[cur] < pos[cur + 1]:
            length += 1
            cur += 1
        if length > max_len:
            max_len = length
    expected = n - max_len
    assert out == expected, f"Oracle expected {expected}, got {out}"

def test_output_integer(run, x):
    out = run(x).strip()
    try:
        int(out)
    except ValueError:
        assert False, "Output is not an integer"

def test_output_range(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    out = int(run(x).strip())
    assert 0 <= out <= n - 1, f"Output {out} out of range [0, {n-1}]"

def test_sorted_zero(run, x):
    lines = x.strip().split('\n')
    p = list(map(int, lines[1].split()))
    out = int(run(x).strip())
    if p == sorted(p):
        assert out == 0, f"Sorted permutation should give 0, got {out}"

def test_reverse_n_minus_one(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    p = list(map(int, lines[1].split()))
    out = int(run(x).strip())
    if p == list(range(n, 0, -1)):
        assert out == n - 1, f"Reverse sorted should give {n-1}, got {out}"

def test_exists_block(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    p = list(map(int, lines[1].split()))
    out = int(run(x).strip())
    L = n - out
    assert L >= 1, f"L = n - output = {L} should be at least 1"
    pos = [0] * n
    for i, val in enumerate(p):
        pos[val - 1] = i
    found = False
    for start in range(n - L + 1):
        ok = True
        for i in range(L - 1):
            if pos[start + i] >= pos[start + i + 1]:
                ok = False
                break
        if ok:
            found = True
            break
    assert found, f"No contiguous increasing subsequence of length {L} found"

def test_n2_cases(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n != 2:
        return
    p = list(map(int, lines[1].split()))
    out = int(run(x).strip())
    if p == [1, 2]:
        assert out == 0, f"For [1,2] expected 0, got {out}"
    else:
        assert out == 1, f"For [2,1] expected 1, got {out}"

def test_n1_case(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n != 1:
        return
    out = int(run(x).strip())
    assert out == 0, f"For n=1, expected 0, got {out}"

def test_examples(run, x):
    out = int(run(x).strip())
    if x == "5\n4 1 2 5 3\n":
        assert out == 2, f"Example 1 expected 2, got {out}"
    if x == "4\n4 1 3 2\n":
        assert out == 2, f"Example 2 expected 2, got {out}"

def test_bfs_small(run, x):
    out = int(run(x).strip())
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 5:
        return
    p = tuple(map(int, lines[1].split()))
    from collections import deque
    target = tuple(range(1, n + 1))
    if p == target:
        expected = 0
    else:
        visited = {p: 0}
        q = deque([p])
        while q:
            state = q.popleft()
            dist = visited[state]
            lst = list(state)
            for i in range(n):
                val = lst[i]
                new_lst = lst[:i] + lst[i+1:]
                # front
                new_state = tuple([val] + new_lst)
                if new_state not in visited:
                    visited[new_state] = dist + 1
                    if new_state == target:
                        break
                    q.append(new_state)
                # back
                new_state = tuple(new_lst + [val])
                if new_state not in visited:
                    visited[new_state] = dist + 1
                    if new_state == target:
                        break
                    q.append(new_state)
            if target in visited:
                break
        expected = visited[target]
    assert out == expected, f"BFS expected {expected}, got {out}"

