tests_src:
def test_output_is_integer(run, x):
    out = run(x)
    try:
        int(out.strip())
    except ValueError:
        assert False

def test_output_bounds(run, x):
    out = run(x)
    s = int(out.strip())
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    assert 0 <= s <= n * m

def test_1x1_product_gt_x(run, x):
    out = run(x)
    s = int(out.strip())
    lines = x.strip().split('\n')
    if len(lines) < 4:
        return
    n, m = map(int, lines[0].split())
    if n == 1 and m == 1:
        a = int(lines[1].strip())
        b = int(lines[2].strip())
        x_val = int(lines[3].strip())
        if a * b > x_val:
            assert s == 0

def test_1x1_product_le_x(run, x):
    out = run(x)
    s = int(out.strip())
    lines = x.strip().split('\n')
    if len(lines) < 4:
        return
    n, m = map(int, lines[0].split())
    if n == 1 and m == 1:
        a = int(lines[1].strip())
        b = int(lines[2].strip())
        x_val = int(lines[3].strip())
        if a * b <= x_val:
            assert s == 1

def test_total_sum(run, x):
    out = run(x)
    s = int(out.strip())
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    x_val = int(lines[3].strip())
    total = sum(a) * sum(b)
    if x_val >= total:
        assert s == n * m

def test_min_product(run, x):
    out = run(x)
    s = int(out.strip())
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    x_val = int(lines[3].strip())
    min_product = min(a) * min(b)
    if x_val < min_product:
        assert s == 0

def test_achievable(run, x):
    out = run(x)
    s = int(out.strip())
    if s == 0:
        return
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if n > 20 or m > 20:
        return
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    x_val = int(lines[3].strip())
    pref_a = [0]
    for v in a:
        pref_a.append(pref_a[-1] + v)
    pref_b = [0]
    for v in b:
        pref_b.append(pref_b[-1] + v)
    found = False
    for x1 in range(n):
        for x2 in range(x1, n):
            sumA = pref_a[x2 + 1] - pref_a[x1]
            for y1 in range(m):
                for y2 in range(y1, m):
                    sumB = pref_b[y2 + 1] - pref_b[y1]
                    area = (x2 - x1 + 1) * (y2 - y1 + 1)
                    if area == s and sumA * sumB <= x_val:
                        found = True
                        break
                if found:
                    break
            if found:
                break
        if found:
            break
    assert found

def test_reference_solution(run, x):
    out = run(x)
    s = int(out.strip())
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    x_val = int(lines[3].strip())
    min_sum_a = [float('inf')] * (n + 1)
    for i in range(n):
        cur = 0
        for j in range(i, n):
            cur += a[j]
            length = j - i + 1
            if cur < min_sum_a[length]:
                min_sum_a[length] = cur
    min_sum_b = [float('inf')] * (m + 1)
    for i in range(m):
        cur = 0
        for j in range(i, m):
            cur += b[j]
            length = j - i + 1
            if cur < min_sum_b[length]:
                min_sum_b[length] = cur
    best = 0
    for len_a in range(1, n + 1):
        if min_sum_a[len_a] == float('inf'):
            continue
        for len_b in range(1, m + 1):
            if min_sum_b[len_b] == float('inf'):
                continue
            if min_sum_a[len_a] * min_sum_b[len_b] <= x_val:
                area = len_a * len_b
                if area > best:
                    best = area
    assert s == best

def test_brute_force_small(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if n > 8 or m > 8:
        return
    out = run(x)
    s = int(out.strip())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    x_val = int(lines[3].strip())
    pref_a = [0]
    for v in a:
        pref_a.append(pref_a[-1] + v)
    pref_b = [0]
    for v in b:
        pref_b.append(pref_b[-1] + v)
    best = 0
    for x1 in range(n):
        for x2 in range(x1, n):
            sumA = pref_a[x2 + 1] - pref_a[x1]
            for y1 in range(m):
                for y2 in range(y1, m):
                    sumB = pref_b[y2 + 1] - pref_b[y1]
                    if sumA * sumB <= x_val:
                        area = (x2 - x1 + 1) * (y2 - y1 + 1)
                        if area > best:
                            best = area
    assert s == best

def test_output_format(run, x):
    out = run(x)
    lines = out.splitlines()
    assert len(lines) == 1 or (len(lines) == 2 and lines[1] == '')
    assert lines[0].isdigit()

