def test_small_brute_all_sequences(run, x):
    import itertools
    N, K = map(int, x.split())
    if N > 6 or K > 4:
        return
    MOD = 10**9 + 7
    half = (N + 1) // 2
    palindromes = []
    for comb in itertools.product(range(1, K + 1), repeat=half):
        if N % 2 == 0:
            seq = list(comb) + list(reversed(comb))
        else:
            seq = list(comb[:-1]) + [comb[-1]] + list(reversed(comb[:-1]))
        palindromes.append(seq)
    distinct = set()
    for p in palindromes:
        for shift in range(N):
            rot = tuple(p[(i + shift) % N] for i in range(N))
            distinct.add(rot)
    expected = len(distinct) % MOD
    output = int(run(x).strip())
    assert output == expected

def test_small_palindrome_brute(run, x):
    import itertools
    N, K = map(int, x.split())
    if K != 2 or N > 12:
        return
    MOD = 10**9 + 7
    half = (N + 1) // 2
    distinct = set()
    for comb in itertools.product([1, 2], repeat=half):
        if N % 2 == 0:
            seq = list(comb) + list(reversed(comb))
        else:
            seq = list(comb[:-1]) + [comb[-1]] + list(reversed(comb[:-1]))
        for shift in range(N):
            rot = tuple(seq[(i + shift) % N] for i in range(N))
            distinct.add(rot)
    expected = len(distinct) % MOD
    output = int(run(x).strip())
    assert output == expected

def test_K_eq_1(run, x):
    N, K = map(int, x.split())
    if K == 1:
        output = run(x).strip()
        assert output == '1'

def test_N_eq_1(run, x):
    N, K = map(int, x.split())
    if N == 1:
        output = int(run(x).strip())
        assert output == K % (10**9 + 7)

def test_N_eq_2(run, x):
