def test_consistency_formula(run, x):
    MOD = 10**9 + 7
    N, K = map(int, x.split())
    divisors = []
    i = 1
    while i * i <= N:
        if N % i == 0:
            divisors.append(i)
            if i * i != N:
                divisors.append(N // i)
        i += 1
    divisors.sort()
    f = {}
    for d in divisors:
        f[d] = pow(K, (d + 1) // 2, MOD)
    g = {}
    for d in divisors:
        val = f[d]
        for e in divisors:
            if e >= d:
                break
            if d % e == 0:
                val = (val - g[e]) % MOD
        g[d] = val
    ans = 0
    for d in divisors:
        if d % 2 == 1:
            ans = (ans + g[d] * d) % MOD
        else:
            ans = (ans + g[d] * (d // 2)) % MOD
    output = int(run(x).strip())
    assert output == ans

