    if len(n_k) < 2:
        return
    n = int(n_k[0])
    a_vals = list(map(int, lines[1].split()))
    b_vals = [a - n for a in a_vals]
    has_pos = any(b > 0 for b in b_vals)
    has_neg = any(b < 0 for b in b_vals)
    if has_pos and has_neg:
        out = run(x)
        assert out.strip() != '-1', 'When both positive and negative differences exist, a solution exists, so answer cannot be -1'

def test_output_not_zero(run, x):
    out = run(x)
    assert out.strip() != '0', 'Output cannot be zero'

def test_full_bfs_oracle(run, x):
    from collections import deque
    lines = x.strip().splitlines()
    n_k = lines[0].split()
    if len(n_k) < 2:
        return
    n = int(n_k[0])
    a_vals = list(map(int, lines[1].split()))
    b_set = set(a - n for a in a_vals)
    if 0 in b_set:
        expected = 1
    else:
        dist = {0: 0}
        q = deque([0])
        found = None
        while q and found is None:
            u = q.popleft()
            d = dist[u]
            if d >= 2000:          # step limit sufficient for given inputs
                continue
            for b in b_set:
                v = u + b
                if v == 0:
                    found = d + 1
                    break
                if v not in dist:
                    dist[v] = d + 1
                    q.append(v)
        expected = found if found is not None else -1
    out = run(x)
    try:
        val = int(out.strip())
    except ValueError:
        assert False, 'Output must be an integer'
    assert val == expected, f'Expected {expected}, got {val}'

def test_no_ai_eq_n_implies_not_one(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n_k = lines[0].split()
    if len(n_k) < 2:
        return
    n = int(n_k[0])
    a_vals = list(map(int, lines[1].split()))
    if any(a == n for a in a_vals):
        return
    out = run(x).strip()
    assert out != '1', 'When no a_i equals n, answer cannot be 1'

def test_minus_one_implies_all_same_side(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n_k = lines[0].split()
    if len(n_k) < 2:
        return
    n = int(n_k[0])
    a_vals = list(map(int, lines[1].split()))
    out = run(x).strip()
    if out == '-1':
        all_above = all(a > n for a in a_vals)
        all_below = all(a < n for a in a_vals)
        assert all_above or all_below, 'Output -1 requires all a_i > n or all a_i < n'

def test_output_at_most_1999(run, x):
    out = run(x).strip()
    try:
        val = int(out)
    except ValueError:
        return  # test_integer_output will catch non-integer
    if val > 0:
        assert val <= 1999, f'Output {val} exceeds maximum possible minimal liters (1999)'

