    import itertools
    n_str, m_str = x.strip().split()
    n = int(n_str)
    m = int(m_str)
    if n * m > 16:
        return
    total = 0
    cells = n * m
    for mask in range(1 << cells):
        grid = [[0]*m for _ in range(n)]
        for i in range(n):
            for j in range(m):
                idx = i * m + j
                grid[i][j] = (mask >> idx) & 1
        ok = True
        for i in range(n):
            for j in range(m):
                color = grid[i][j]
                same_count = 0
                for di,dj in [(-1,0),(1,0),(0,-1),(0,1)]:
                    ni, nj = i+di, j+dj
                    if 0 <= ni < n and 0 <= nj < m:
                        if grid[ni][nj] == color:
                            same_count += 1
                if same_count > 1:
                    ok = False
                    break
            if not ok:
                break
        if ok:
            total += 1
    expected = total % (10**9+7)
    out = run(x)
    assert int(out.strip()) == expected

