def test_2d_m2(run, x):
    n_str, m_str = x.strip().split()
    n = int(n_str)
    m = int(m_str)
    if m != 2:
        return
    MOD = 10**9+7
    # compute F_{n+1} modulo MOD
    a, b = 0, 1  # F0, F1
    for _ in range(n+1):
        a, b = b, (a + b) % MOD  # after loop, a = F_{n+1}
    expected = (2 * (a + 1)) % MOD
