    out = run(x)
    val = int(out.strip())
    assert 0 <= val < MOD

def test_fast_doubling(run, x):
    MOD = 10**9+7
    n_str, m_str = x.strip().split()
    n = int(n_str)
    m = int(m_str)
    def fib(k):
        if k == 0:
            return (0, 1)
        else:
            a, b = fib(k // 2)
            c = (a * ((2 * b - a) % MOD)) % MOD
            d = (a * a + b * b) % MOD
            if k % 2 == 0:
                return (c, d)
            else:
                return (d, (c + d) % MOD)
    fn = fib(n+1)[0]
    fm = fib(m+1)[0]
    expected = (2 * (fn + fm - 1)) % MOD
    out = run(x)
    assert int(out.strip()) == expected

def test_example(run, x):
    if x != "2 3\n":
        return
    out = run(x)
    assert out.strip() == "8"

def test_output_format(run, x):
    out = run(x)
    s = out.strip()
    int(s)  # must be integer
    assert out == s + "\n" or out == s

