def test_integer(run, x):
    out = run(x)
    s = out.strip()
    assert s.isdigit()

def test_non_negative(run, x):
    out = run(x)
    val = int(out.strip())
    assert val >= 0

def test_example_n1(run, x):
    n = int(x.strip())
    if n != 1:
        return
    val = int(run(x).strip())
    assert val == 0

def test_example_n2(run, x):
    n = int(x.strip())
    if n != 2:
        return
    val = int(run(x).strip())
    assert val == 0

def test_example_n10(run, x):
    n = int(x.strip())
    if n != 10:
        return
    val = int(run(x).strip())
    assert val == 4

def test_small_n_bruteforce(run, x):
    n = int(x.strip())
    if n > 10:
        return
    if n == 1:
        expected = 0
    else:
        edges = []
        for i in range(1, n + 1):
            for j in range(i + 1, n + 1):
                w = (i + j) % (n + 1)
                edges.append((w, i, j))
        edges.sort()
        parent = list(range(n + 1))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        def union(a, b):
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[rb] = ra
                return True
            return False
        total = 0
        cnt = 0
        for w, i, j in edges:
            if union(i, j):
                total += w
                cnt += 1
                if cnt == n - 1:
                    break
        expected = total
    val = int(run(x).strip())
    assert val == expected

def test_medium_n_bruteforce(run, x):
    n = int(x.strip())
    if n > 50:
        return
    if n == 1:
        expected = 0
    else:
        edges = []
        for i in range(1, n + 1):
            for j in range(i + 1, n + 1):
                w = (i + j) % (n + 1)
                edges.append((w, i, j))
        edges.sort()
        parent = list(range(n + 1))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        def union(a, b):
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[rb] = ra
                return True
            return False
        total = 0
        cnt = 0
        for w, i, j in edges:
            if union(i, j):
                total += w
                cnt += 1
                if cnt == n - 1:
                    break
        expected = total
    val = int(run(x).strip())
    assert val == expected

def test_large_n_prim(run, x):
    n = int(x.strip())
    if n > 500:
        return
    import sys
    INF = 10**18
    visited = [False] * (n + 1)
    min_edge = [INF] * (n + 1)
    min_edge[1] = 0
    total = 0
    for _ in range(n):
        v = -1
        for i in range(1, n + 1):
            if not visited[i] and (v == -1 or min_edge[i] < min_edge[v]):
                v = i
        visited[v] = True
        total += min_edge[v]
        for to in range(1, n + 1):
            if not visited[to]:
                w = (v + to) % (n + 1)
                if w < min_edge[to]:
                    min_edge[to] = w
    val = int(run(x).strip())
    assert val == total

def test_trivial_upper_bound(run, x):
    n = int(x.strip())
    val = int(run(x).strip())
    assert val <= n * (n - 1)

def test_star_upper_bound(run, x):
    n = int(x.strip())
    total = 0
    mod = n + 1
    for i in range(2, n + 1):
        total += (1 + i) % mod
    val = int(run(x).strip())
    assert val <= total

