def test_bruteforce_small(run, x):
    lines = x.strip().split('\n')
    N = int(lines[0])
    if N > 8:
        return
    first_row = list(map(int, lines[1].split()))
    first_col = [int(lines[i]) for i in range(2, 2+N-1)]
    mex = [[1,2,1],[2,0,0],[1,0,0]]
    a = [[0]*N for _ in range(N)]
    for j in range(N):
        a[0][j] = first_row[j]
    for i in range(1,N):
        a[i][0] = first_col[i-1]
    for i in range(1,N):
        for j in range(1,N):
            a[i][j] = mex[a[i-1][j]][a[i][j-1]]
    counts = [0,0,0]
    for i in range(N):
        for j in range(N):
            counts[a[i][j]] += 1
    expected = f"{counts[0]} {counts[1]} {counts[2]}"
    assert run(x).strip() == expected

def test_sum_invariant(run, x):
    lines = x.strip().split('\n')
    N = int(lines[0])
    out = run(x).strip()
    parts = out.split()
    assert len(parts) == 3
    c0, c1, c2 = map(int, parts)
    assert c0 + c1 + c2 == N * N

def test_nonnegative_counts(run, x):
    out = run(x).strip()
    parts = out.split()
    assert len(parts) == 3
    c0, c1, c2 = map(int, parts)
    assert c0 >= 0 and c1 >= 0 and c2 >= 0

def test_output_format(run, x):
    out = run(x).strip()
    parts = out.split()
    assert len(parts) == 3
    for p in parts:
        assert p.isdigit()

def test_sample(run, x):
    if x == "4\n1 2 0 2\n0\n0\n0\n":
        assert run(x).strip() == "7 4 5"

def test_N1_zero(run, x):
    if x == "1\n0\n":
        assert run(x).strip() == "1 0 0"

def test_N2_case(run, x):
    if x == "2\n1 2\n0\n":
        expected = "1 2 1"
        assert run(x).strip() == expected

