def test_mod_range(run, x):
    out = run(x).strip()
    val = int(out)
    MOD = 10**9+7
    assert 0 <= val < MOD

def test_brute_small(run, x):
    n, m = map(int, x.split())
    if n * m > 20:
        return
    MOD = 10**9+7
    total = 0
    cells = n * m
    for mask in range(1 << cells):
        grid = [[0] * m for _ in range(n)]
        for i in range(n):
            for j in range(m):
                idx = i * m + j
                grid[i][j] = (mask >> idx) & 1
        ok = True
        for i in range(n):
            for j in range(m):
                color = grid[i][j]
                same = 0
                for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
                    ni, nj = i + di, j + dj
                    if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == color:
                        same += 1
                if same > 1:
                    ok = False
                    break
            if not ok:
                break
        if ok:
            total += 1
    expected = total % MOD
    out = run(x).strip()
    assert int(out) == expected

