def test_formula_general(run, x):
    n, m = map(int, x.split())
    MOD = 10**9+7
    k = max(n, m)
    G = [0] * (k + 1)
    if k >= 1:
        G[1] = 1
    if k >= 2:
        G[2] = 2
    for i in range(3, k + 1):
        G[i] = (G[i-1] + G[i-2]) % MOD
    expected = (2 * (G[n] + G[m] - 1)) % MOD
    out = run(x).strip()
    assert int(out) == expected

def test_small_n_dp(run, x):
    lines = x.strip().split('\n')
    first = lines[0].split()
    n = int(first[0])
    if n > 8:
        return
    A = int(first[1])
    B = int(first[2])
    S = lines[1].strip()
    def min_cost(n, A, B, S):
        dp = [float('inf')]*(n+1)
        dp[0] = 0
        for i in range(1, n+1):
            for j in range(i):
                t = S[j:i]
                l = i-j
                text = S[:j]
                is_sub = t in text
                if l == 1:
                    if is_sub:
                        cost = min(A, B)
                    else:
                        cost = A
                else:
                    if is_sub:
                        cost = B
                    else:
                        continue
                dp[i] = min(dp[i], dp[j] + cost)
        return dp[n]
    correct = min_cost(n, A, B, S)
    out = run(x)
    ans = int(out.strip())
    assert ans == correct


