def test_format(run, x):
    MOD = 998244353
    K, N = map(int, x.strip().split())
    if not (1 <= K <= 2000 and 2 <= N <= 2000):
        return
    output = run(x)
    lines = output.strip().splitlines()
    assert len(lines) == 2 * K - 1, f"Expected {2*K-1} lines, got {len(lines)}"
    for line in lines:
        val = int(line.strip())
        assert 0 <= val < MOD, f"Value {val} out of range [0, {MOD})"

