def test_f2(run, x):
    import math
    MOD = 998244353
    def comb_mod(n, k):
        if k < 0 or k > n:
            return 0
        return math.comb(n, k) % MOD
    K, N = map(int, x.strip().split())
    if not (1 <= K <= 2000 and 2 <= N <= 2000):
        return
    c1 = comb_mod(N + K - 2, N)
    c2 = comb_mod(N + K - 3, N - 1)
    expected = (c1 + c2) % MOD
    output = run(x)
    lines = output.strip().splitlines()
    first = int(lines[0]) if lines else None
    assert first == expected, f"f(2) expected {expected}, got {first}"

