    dom_id = {ch: i for i, ch in enumerate(letters)}
    # position -> domino id
    cell_to_id = {}
    for ch, lst in pos.items():
        for (r, c) in lst:
            cell_to_id[(r, c)] = dom_id[ch]
    # build adjacency set
    adj = set()
    for r in (0, 1):
        for c in range(N):
            u = cell_to_id[(r, c)]
            if c + 1 < N:
                v = cell_to_id.get((r, c + 1))
                if v is not None and u != v:
                    adj.add((min(u, v), max(u, v)))
            if r == 0:
                v = cell_to_id.get((1, c))
                if v is not None and u != v:
                    adj.add((min(u, v), max(u, v)))
    M = len(letters)  # should equal N
    total = 0
    for mask in range(3 ** M):
        colors = []
        tmp = mask
        for _ in range(M):
            colors.append(tmp % 3)
            tmp //= 3
        ok = True
        for u, v in adj:
            if colors[u] == colors[v]:
                ok = False
                break
        if ok:
            total += 1
    expected = total % MOD
    out = run(x).strip()
    got = int(out) % MOD
    assert got == expected

def test_output_format(run, x):
