def test_exact_formula(run, x):
    tokens = x.strip().split()
    if not tokens:
        return
    n = int(tokens[0])
    if len(tokens) < n + 1:
        return
    h = list(map(int, tokens[1:1+n]))
    prev = 0
    ans = 0
    for val in h:
        if val > prev:
            ans += val - prev
        prev = val
    output = run(x).strip()
    assert output == str(ans)

def test_n1_case(run, x):
    tokens = x.strip().split()
    if not tokens:
        return
    n = int(tokens[0])
    if n != 1:
        return
    if len(tokens) < 2:
        return
    h_val = int(tokens[1])
    output = run(x).strip()
    assert output == str(h_val)

def test_all_zero(run, x):
    tokens = x.strip().split()
    if not tokens:
        return
    n = int(tokens[0])
    if len(tokens) < n + 1:
        return
    h = list(map(int, tokens[1:1+n]))
    if all(v == 0 for v in h):
        output = run(x).strip()
        assert output == "0"

def test_non_decreasing(run, x):
    tokens = x.strip().split()
    if not tokens:
        return
    n = int(tokens[0])
    if len(tokens) < n + 1:
        return
    h = list(map(int, tokens[1:1+n]))
    for i in range(n - 1):
        if h[i] > h[i + 1]:
            return
    expected = h[-1] if n > 0 else 0
    output = run(x).strip()
    assert output == str(expected)

def test_non_increasing(run, x):
    tokens = x.strip().split()
    if not tokens:
        return
    n = int(tokens[0])
    if len(tokens) < n + 1:
        return
    h = list(map(int, tokens[1:1+n]))
    for i in range(n - 1):
        if h[i] < h[i + 1]:
            return
    expected = h[0] if n > 0 else 0
    output = run(x).strip()
    assert output == str(expected)

def test_output_integer_nonnegative(run, x):
    output = run(x).strip()
    val = int(output)
    assert val >= 0

def test_output_leq_sum(run, x):
    tokens = x.strip().split()
    if not tokens:
        return
    n = int(tokens[0])
    if len(tokens) < n + 1:
        return
    h = list(map(int, tokens[1:1+n]))
    total = sum(h)
    output = run(x).strip()
    val = int(output)
    assert val <= total

def test_output_geq_max(run, x):
    tokens = x.strip().split()
    if not tokens:
        return
    n = int(tokens[0])
    if len(tokens) < n + 1:
        return
    h = list(map(int, tokens[1:1+n]))
    if n == 0:
        return
    mx = max(h)
    output = run(x).strip()
    val = int(output)
    assert val >= mx

def test_greedy_simulation(run, x):
    tokens = x.strip().split()
    if not tokens:
        return
    n = int(tokens[0])
    if len(tokens) < n + 1:
        return
    h = list(map(int, tokens[1:1+n]))
    arr = h[:]
    ops = 0
    while any(v > 0 for v in arr):
        i = 0
        while i < n:
            if arr[i] == 0:
                i += 1
            else:
                ops += 1
                j = i
                while j < n and arr[j] > 0:
                    j += 1
                for k in range(i, j):
                    arr[k] -= 1
                i = j
    output = run(x).strip()
    assert output == str(ops)

def test_formula_n2(run, x):
    tokens = x.strip().split()
    if not tokens:
        return
    n = int(tokens[0])
    if n != 2:
        return
    if len(tokens) < 3:
        return
    h = list(map(int, tokens[1:3]))
    expected = h[0] + max(0, h[1] - h[0])
    output = run(x).strip()
    assert output == str(expected)

def test_output_integer(run, x):
    out = run(x)
    s = out.strip()
    try:
        int(s)
    except ValueError:
        assert False


def test_output_range(run, x):
    parts = x.strip().split()
    if len(parts) < 4:
        return
    A, B, C, K = map(int, parts[:4])
    if not (A >= 0 and B >= 0 and C >= 0 and 1 <= K <= A + B + C):
        return
    out = run(x)
    val = int(out.strip())
    assert -K <= val <= K


def test_output_upper_bound(run, x):
    parts = x.strip().split()
    if len(parts) < 4:
        return
    A, B, C, K = map(int, parts[:4])
    if not (A >= 0 and B >= 0 and C >= 0 and 1 <= K <= A + B + C):
        return
    out = run(x)
    val = int(out.strip())
    assert val <= min(K, A)


def test_output_lower_bound(run, x):
    parts = x.strip().split()
    if len(parts) < 4:
        return
    A, B, C, K = map(int, parts[:4])
    if not (A >= 0 and B >= 0 and C >= 0 and 1 <= K <= A + B + C):
        return
    out = run(x)
    val = int(out.strip())
    assert val >= -min(K, C)


def test_K_le_A(run, x):
    parts = x.strip().split()
    if len(parts) < 4:
        return
    A, B, C, K = map(int, parts[:4])
    if not (A >= 0 and B >= 0 and C >= 0 and 1 <= K <= A + B + C):
        return
    if K <= A:
        out = run(x)
        val = int(out.strip())
        assert val == K


def test_K_between_A_and_A_plus_B(run, x):
    parts = x.strip().split()
    if len(parts) < 4:
        return
    A, B, C, K = map(int, parts[:4])
    if not (A >= 0 and B >= 0 and C >= 0 and 1 <= K <= A + B + C):
        return
    if A < K <= A + B:
        out = run(x)
        val = int(out.strip())
        assert val == A


def test_K_gt_A_plus_B(run, x):
    parts = x.strip().split()
    if len(parts) < 4:
        return
    A, B, C, K = map(int, parts[:4])
    if not (A >= 0 and B >= 0 and C >= 0 and 1 <= K <= A + B + C):
        return
    if K > A + B:
        out = run(x)
        val = int(out.strip())
        expected = A - (K - A - B)
        assert val == expected


def test_min_max_formula(run, x):
    parts = x.strip().split()
    if len(parts) < 4:
        return
    A, B, C, K = map(int, parts[:4])
    if not (A >= 0 and B >= 0 and C >= 0 and 1 <= K <= A + B + C):
        return
    out = run(x)
    val = int(out.strip())
    correct = min(K, A) - max(0, K - A - B)
    assert val == correct


def test_bruteforce_small(run, x):
    parts = x.strip().split()
    if len(parts) < 4:
        return
    A, B, C, K = map(int, parts[:4])
    if not (A >= 0 and B >= 0 and C >= 0 and 1 <= K <= A + B + C):
        return
    total = A + B + C
    if total > 20:
        return
    out = run(x)
    val = int(out.strip())
    best = -10**18
    for a in range(0, min(A, K) + 1):
        max_b = min(B, K - a)
        for b in range(0, max_b + 1):
            c = K - a - b
            if c <= C:
                s = a - c
                if s > best:
                    best = s
    assert val == best


def test_achievable(run, x):
    parts = x.strip().split()
    if len(parts) < 4:
        return
    A, B, C, K = map(int, parts[:4])
    if not (A >= 0 and B >= 0 and C >= 0 and 1 <= K <= A + B + C):
        return
    out = run(x)
    S = int(out.strip())
    a_low = max(S, 0)
    a_high = min(A, K, S + C)
    left = K + S - B
    right = K + S
    a_min = max(a_low, (left + 1) // 2 if left % 2 else left // 2)
    a_max = min(a_high, right // 2)
    assert a_min <= a_max

