def test_greedy_reduction(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    rows = lines[1:1+n]
    r = n
    while r % 2 == 0:
        half = r // 2
        ok = True
        for i in range(half):
            if rows[i] != rows[r-1-i]:
                ok = False
                break
        if not ok:
            break
        rows = rows[:half]
        r = half
    expected = r
    output = run(x).strip()
    assert output == str(expected)

def test_build_and_compare(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    original = lines[1:1+n]
    out = run(x).strip()
    r = int(out)
    if not (1 <= r <= n):
        assert False
    if n % r != 0:
        assert False
    k = n // r
    if k & (k-1) != 0:
        assert False
    base = original[:r]
    current = base
    size = r
