def test_formula(run, x):
    A, B, C, K = map(int, x.strip().split())
    if not (0 <= A and 0 <= B and 0 <= C and 1 <= K <= A + B + C):
        return
    if K <= A + B:
        expected = min(A, K)
    else:
        expected = A - (K - A - B)
    output = int(run(x).strip())
    assert output == expected

def test_range(run, x):
    A, B, C, K = map(int, x.strip().split())
    if not (0 <= A and 0 <= B and 0 <= C and 1 <= K <= A + B + C):
        return
    output = int(run(x).strip())
    assert -K <= output <= K

def test_K_le_A(run, x):
    A, B, C, K = map(int, x.strip().split())
    if not (0 <= A and 0 <= B and 0 <= C and 1 <= K <= A + B + C):
        return
    if K <= A:
        output = int(run(x).strip())
        assert output == K

def test_A_lt_K_le_AplusB(run, x):
    A, B, C, K = map(int, x.strip().split())
    if not (0 <= A and 0 <= B and 0 <= C and 1 <= K <= A + B + C):
        return
    if A < K <= A + B:
        output = int(run(x).strip())
        assert output == A

def test_K_gt_AplusB(run, x):
    A, B, C, K = map(int, x.strip().split())
    if not (0 <= A and 0 <= B and 0 <= C and 1 <= K <= A + B + C):
        return
    if K > A + B:
        output = int(run(x).strip())
        expected = A - (K - A - B)
        assert output == expected

def test_achievable(run, x):
    A, B, C, K = map(int, x.strip().split())
    if not (0 <= A and 0 <= B and 0 <= C and 1 <= K <= A + B + C):
        return
    S = int(run(x).strip())
    lower = max(0, (K - S - B + 1) // 2, -S)
    upper = min(C, A - S, (K - S) // 2)
    assert lower <= upper

def test_C_zero(run, x):
    A, B, C, K = map(int, x.strip().split())
    if not (0 <= A and 0 <= B and 0 <= C and 1 <= K <= A + B + C):
        return
    if C == 0:
        output = int(run(x).strip())
        assert output == min(A, K)

def test_A_zero(run, x):
    A, B, C, K = map(int, x.strip().split())
    if not (0 <= A and 0 <= B and 0 <= C and 1 <= K <= A + B + C):
        return
    if A == 0:
        output = int(run(x).strip())
        expected = -max(0, K - B)
        assert output == expected

def test_B_zero(run, x):
    A, B, C, K = map(int, x.strip().split())
    if not (0 <= A and 0 <= B and 0 <= C and 1 <= K <= A + B + C):
        return
    if B == 0:
        output = int(run(x).strip())
        expected = min(A, K) - max(0, K - A)
        assert output == expected

def test_special_case_C_ge1_K_eq_AplusBplus1(run, x):
    A, B, C, K = map(int, x.strip().split())
    if not (0 <= A and 0 <= B and 0 <= C and 1 <= K <= A + B + C):
        return
    if C >= 1 and K == A + B + 1:
        output = int(run(x).strip())
        assert output == A - 1

def test_integer(run, x):
    out = run(x).strip()
    try:
        int(out)
    except ValueError:
        assert False

def test_nonnegative(run, x):
    out = run(x).strip()
    n = int(out)
    assert n >= 0

def test_le_total(run, x):
    lines = x.strip().split()
    H, W, h, w = map(int, lines)
    out = run(x).strip()
    n = int(out)
    assert n <= H * W

def test_zero_all_rows(run, x):
    lines = x.strip().split()
    H, W, h, w = map(int, lines)
    out = run(x).strip()
    n = int(out)
    if h == H:
        assert n == 0

def test_zero_all_columns(run, x):
    lines = x.strip().split()
    H, W, h, w = map(int, lines)
    out = run(x).strip()
    n = int(out)
    if w == W:
        assert n == 0

def test_simulation(run, x):
    lines = x.strip().split()
    H, W, h, w = map(int, lines)
    out = run(x).strip()
    n = int(out)
    expected = 0
    for i in range(h, H):
        for j in range(w, W):
            expected += 1
    assert n == expected

def test_exhaustive_small(run, x):
    lines = x.strip().split()
    H, W, h, w = map(int, lines)
    out = run(x).strip()
    n = int(out)
    if H > 8 or W > 8:
        return
    from itertools import combinations
    rows_comb = list(combinations(range(H), h))
    cols_comb = list(combinations(range(W), w))
    first_val = None
    for R in rows_comb:
        R_set = set(R)
        for C in cols_comb:
            C_set = set(C)
            white = 0
            for i in range(H):
                if i in R_set:
                    continue
                for j in range(W):
                    if j not in C_set:
                        white += 1
            if first_val is None:
                first_val = white
            else:
                if white != first_val:
                    assert False
    assert n == first_val

def test_upper_bounds(run, x):
    lines = x.strip().split()
    H, W, h, w = map(int, lines)
    out = run(x).strip()
    n = int(out)
    assert n <= (H - h) * W
    assert n <= (W - w) * H

def test_sample(run, x):
    out = run(x).strip()
    lines = x.strip().splitlines()
    if len(lines) >= 2:
        first = list(map(int, lines[0].split()))
        second = list(map(int, lines[1].split()))
        if len(first) == 2 and len(second) == 2:
            H, W = first[0], first[1]
            h, w = second[0], second[1]
            if H == 3 and W == 2 and h == 2 and w == 1:
                assert int(out) == 1

def test_special_cases(run, x):
    out = run(x).strip()
    lines = x.strip().split()
    if len(lines) != 4:
        return
    H, W, h, w = map(int, lines)
    special = {
        (1, 1, 1, 1): 0,
        (1, 20, 1, 1): 0,
        (20, 1, 1, 1): 0,
        (20, 20, 20, 20): 0,
        (20, 20, 1, 1): 361,
        (2, 2, 1, 1): 1,
        (3, 5, 2, 3): 2,
        (10, 10, 5, 5): 25,
        (10, 10, 10, 5): 0,
        (10, 10, 5, 10): 0,
        (20, 19, 10, 9): 100,
        (19, 20, 9, 10): 100,
    }
    key = (H, W, h, w)
    if key in special:
        assert int(out) == special[key]

