def test_output_is_either_integer_or_TLE(run, x):
    out = run(x).rstrip()
    if out == "TLE":
        return
    try:
        int(out)
    except ValueError:
        assert False, "Output must be either integer or 'TLE'"


def test_if_no_valid_route_then_TLE(run, x):
    lines = x.strip().splitlines()
    N, T = map(int, lines[0].split())
    valid_exists = False
    for i in range(1, N+1):
        c, t = map(int, lines[i].split())
        if t <= T:
            valid_exists = True
            break
    if not valid_exists:
        out = run(x).rstrip()
        assert out == "TLE", "When no route satisfies t_i <= T, must output 'TLE'"


def test_if_valid_route_then_integer(run, x):
    lines = x.strip().splitlines()
    N, T = map(int, lines[0].split())
    valid_exists = False
    for i in range(1, N+1):
        c, t = map(int, lines[i].split())
        if t <= T:
            valid_exists = True
            break
    if valid_exists:
        out = run(x).rstrip()
        try:
            int(out)
        except ValueError:
            assert False, "When there is a valid route, output must be an integer"


def test_output_integer_is_valid_cost(run, x):
    out = run(x).rstrip()
    if out == "TLE":
        return
    out_int = int(out)
    lines = x.strip().splitlines()
    N, T = map(int, lines[0].split())
    found = False
    for i in range(1, N+1):
        c, t = map(int, lines[i].split())
        if t <= T and c == out_int:
            found = True
            break
    assert found, f"Output cost {out_int} is not from any valid route"


def test_output_integer_is_leq_all_valid_costs(run, x):
    out = run(x).rstrip()
    if out == "TLE":
        return
    out_int = int(out)
    lines = x.strip().splitlines()
    N, T = map(int, lines[0].split())
    for i in range(1, N+1):
        c, t = map(int, lines[i].split())
        if t <= T:
            assert out_int <= c, f"Output cost {out_int} is greater than valid cost {c}"


def test_output_format_single_line(run, x):
    out = run(x)
    lines = out.rstrip().splitlines()
    assert len(lines) == 1, "Output must be exactly one line"


def test_output_integer_range(run, x):
    out = run(x).rstrip()
    if out == "TLE":
        return
    out_int = int(out)
    assert 1 <= out_int <= 1000, f"Output integer {out_int} not in [1,1000]"


def test_TLE_string_exact(run, x):
    out = run(x).rstrip()
    if out == "TLE":
        lines = x.strip().splitlines()
        N, T = map(int, lines[0].split())
        valid_exists = False
        for i in range(1, N+1):
            c, t = map(int, lines[i].split())
            if t <= T:
                valid_exists = True
                break
        assert not valid_exists, "Output is 'TLE' but there exists a valid route"


def test_correct_answer(run, x):
    lines = x.strip().splitlines()
    N, T = map(int, lines[0].split())
    valid_costs = []
    for i in range(1, N+1):
        c, t = map(int, lines[i].split())
        if t <= T:
            valid_costs.append(c)
    if valid_costs:
        expected = str(min(valid_costs))
    else:
        expected = "TLE"
    out = run(x).rstrip()
    assert out == expected, f"Expected {expected}, got {out}"


def test_sample_input(run, x):
    if x == "3 70\n7 60\n1 80\n4 50\n":
        out = run(x).rstrip()
        assert out == "4", f"For sample input, expected 4, got {out}"

