def test_output_is_integer(run, x):
    output = run(x)
    try:
        int(output.strip())
    except ValueError:
        assert False, "Output must be an integer"

def test_output_nonnegative(run, x):
    output = run(x)
    ans = int(output.strip())
    assert ans >= 0, "Number of pies cannot be negative"

def test_pies_bound_by_pieces(run, x):
    a, p = map(int, x.split())
    total = 3 * a + p
    output = run(x)
    ans = int(output.strip())
    assert 2 * ans <= total, "Pies cannot use more pieces than available"

def test_no_more_pies(run, x):
    a, p = map(int, x.split())
    total = 3 * a + p
    output = run(x)
    ans = int(output.strip())
    assert total < 2 * (ans + 1), "Could make at least one more pie if pieces allowed"

def test_sample(run, x):
    if x == "1 3\n":
        output = run(x)
        assert output.strip() == "3", "Sample input must produce sample output"

def test_zero_case(run, x):
    if x == "0 0\n":
        output = run(x)
        assert output.strip() == "0", "Zero apples and pieces must yield zero pies"

def test_max_case(run, x):
    if x == "100 100\n":
        output = run(x)
        assert output.strip() == "200", "Maximum input (100,100) must yield 200 pies"

def test_simulation_oracle(run, x):
    a, p = map(int, x.split())
    apples = a
    pieces = p
    pies = 0
    while True:
        if pieces >= 2:
            pies += 1
            pieces -= 2
        elif apples >= 1:
            apples -= 1
            pieces += 3
        else:
            break
    output = run(x)
    ans = int(output.strip())
    assert ans == pies, "Output does not match simulation of the process"

def test_parity(run, x):
    a, p = map(int, x.split())
    total = 3 * a + p
    output = run(x)
    ans = int(output.strip())
    remainder = total - 2 * ans
    assert 0 <= remainder <= 1, "After making pies, leftover pieces must be 0 or 1"

def test_specific_0_2(run, x):
    if x == "0 2\n":
        output = run(x)
        assert output.strip() == "1", "Input (0,2) must yield 1 pie"

