def test_direct_oracle(run, x):
    lines = x.strip().splitlines()
    S = lines[0].strip()
    T = lines[1].strip()
    expected = "Yes" if T[:-1] == S else "No"
    assert run(x).strip() == expected

def test_output_valid(run, x):
    output = run(x).strip()
    assert output in {"Yes", "No"}

def test_yes_prefix(run, x):
    lines = x.strip().splitlines()
    S = lines[0].strip()
    T = lines[1].strip()
    output = run(x).strip()
    if output == "Yes":
        assert T.startswith(S)

def test_no_not_prefix(run, x):
    lines = x.strip().splitlines()
    S = lines[0].strip()
    T = lines[1].strip()
    output = run(x).strip()
    if output == "No":
        assert not T.startswith(S)

def test_yes_suffix(run, x):
    lines = x.strip().splitlines()
    S = lines[0].strip()
    T = lines[1].strip()
    output = run(x).strip()
    if output == "Yes":
        assert T[:-1] == S

def test_no_not_suffix(run, x):
    lines = x.strip().splitlines()
    S = lines[0].strip()
    T = lines[1].strip()
    output = run(x).strip()
    if output == "No":
        assert T[:-1] != S

def test_output_exact(run, x):
    output = run(x)
    assert output in {"Yes\n", "No\n"}

def test_brute_force_set(run, x):
    import string
    lines = x.strip().splitlines()
    S = lines[0].strip()
    T = lines[1].strip()
    output = run(x).strip()
    candidates = {S + c for c in string.ascii_lowercase}
    assert (output == "Yes") == (T in candidates)

def test_single_line(run, x):
    output = run(x)
    lines = output.strip().splitlines()
    assert len(lines) == 1

def test_no_trailing_whitespace(run, x):
    output = run(x)
    # Remove exactly one newline at the end if present
    if output.endswith('\n'):
        output_content = output[:-1]
    else:
        output_content = output
