tests_src:
def test_integer(run, x):
    out = run(x)
    try:
        int(out.strip())
    except ValueError:
        assert False, "Output is not an integer"

def test_range(run, x):
    N, i = map(int, x.strip().split())
    out = run(x)
    j = int(out.strip())
    assert 1 <= j <= N, f"j={j} not in [1, {N}]"

def test_sum(run, x):
    N, i = map(int, x.strip().split())
    out = run(x)
    j = int(out.strip())
    assert i + j == N + 1, f"i+j={i+j} != N+1={N+1}"

def test_front(run, x):
    N, i = map(int, x.strip().split())
    out = run(x)
    j = int(out.strip())
    if i == 1:
        assert j == N, f"When i=1, expected j={N}, got {j}"

def test_back(run, x):
    N, i = map(int, x.strip().split())
    out = run(x)
    j = int(out.strip())
    if i == N:
        assert j == 1, f"When i=N, expected j=1, got {j}"

def test_enumeration(run, x):
    N, i = map(int, x.strip().split())
    cars = list(range(1, N+1))
    target = cars[i-1]
    j_correct = None
    for j_back, car in enumerate(reversed(cars), start=1):
        if car == target:
            j_correct = j_back
            break
    out = run(x)
    j = int(out.strip())
    assert j == j_correct, f"Expected j={j_correct}, got {j}"

def test_sample(run, x):
    out = run(x)
    if x == "4 2\n":
        assert out.strip() == "3", f"For sample input, expected 3, got {out.strip()}"

def test_middle(run, x):
    N, i = map(int, x.strip().split())
    out = run(x)
    j = int(out.strip())
    if N % 2 == 1 and i == (N+1)//2:
        assert j == i, f"For middle car, expected j={i}, got {j}"

def test_minimal(run, x):
    N, i = map(int, x.strip().split())
    out = run(x)
    if N == 1 and i == 1:
        j = int(out.strip())
        assert j == 1, f"For N=1,i=1, expected 1, got {j}"

def test_output_numeric(run, x):
    out = run(x)
    s = out.strip()
    assert s.isdigit(), f"Output must be digits only, got '{s}'"

def test_brute_force_oracle(run, x):
    S = x.strip()
    if not (4 <= len(S) <= 10 and all(c in '123456789' for c in S)):
        return
    best = 10**9
    for i in range(len(S)-2):
        val = int(S[i:i+3])
        diff = abs(val - 753)
        if diff < best:
            best = diff
    output = run(x).strip()
    out_int = int(output)
    assert out_int == best

def test_output_nonnegative(run, x):
    S = x.strip()
    if not (4 <= len(S) <= 10 and all(c in '123456789' for c in S)):
        return
    output = run(x).strip()
    out_int = int(output)
    assert out_int >= 0

def test_output_at_most_642(run, x):
    S = x.strip()
    if not (4 <= len(S) <= 10 and all(c in '123456789' for c in S)):
        return
    output = run(x).strip()
    out_int = int(output)
    assert out_int <= 642

def test_contains_753_gives_zero(run, x):
    S = x.strip()
    if not (4 <= len(S) <= 10 and all(c in '123456789' for c in S)):
        return
    if "753" in S:
        output = run(x).strip()
        out_int = int(output)
        assert out_int == 0

def test_output_is_achievable(run, x):
    S = x.strip()
    if not (4 <= len(S) <= 10 and all(c in '123456789' for c in S)):
        return
    output = run(x).strip()
    out_int = int(output)
    achievable = False
    for i in range(len(S)-2):
        val = int(S[i:i+3])
        if abs(val - 753) == out_int:
            achievable = True
            break
    assert achievable

def test_output_is_lower_bound(run, x):
    S = x.strip()
    if not (4 <= len(S) <= 10 and all(c in '123456789' for c in S)):
        return
    output = run(x).strip()
    out_int = int(output)
    for i in range(len(S)-2):
        val = int(S[i:i+3])
        assert abs(val - 753) >= out_int

def test_output_format_correct(run, x):
    S = x.strip()
    if not (4 <= len(S) <= 10 and all(c in '123456789' for c in S)):
        return
    output = run(x)
    stripped = output.strip()
    assert len(stripped) > 0
    assert stripped.isdigit()
    assert str(int(stripped)) == stripped

def test_length_4_case(run, x):
    S = x.strip()
    if len(S) != 4:
        return
    if not all(c in '123456789' for c in S):
        return
    d1 = abs(int(S[0:3]) - 753)
    d2 = abs(int(S[1:4]) - 753)
    expected = min(d1, d2)
    output = run(x).strip()
    out_int = int(output)
    assert out_int == expected

def test_all_same_digits(run, x):
    S = x.strip()
    if not (4 <= len(S) <= 10 and all(c in '123456789' for c in S)):
        return
    if len(set(S)) == 1:
        d = int(S[0] * 3)
        expected = abs(d - 753)
        output = run(x).strip()
        out_int = int(output)
        assert out_int == expected

def test_zero_implies_753(run, x):
    S = x.strip()
    if not (4 <= len(S) <= 10 and all(c in '123456789' for c in S)):
        return
    output = run(x).strip()
    out_int = int(output)
    if out_int == 0:
        assert "753" in S

