    import math
    a,b,c = map(int, x.strip().split())
    output = run(x).strip()
    if math.gcd(a, b) == 1:
        assert output == 'YES'

def test_b_one_always_yes(run, x):
    a,b,c = map(int, x.strip().split())
    output = run(x).strip()
    if b == 1:
        assert output == 'YES'

def test_a_multiple_b(run, x):
    a,b,c = map(int, x.strip().split())
    output = run(x).strip()
    if a % b == 0:
        expected = 'YES' if c == 0 else 'NO'
        assert output == expected

