    output = run(x).strip()
    assert output in ('YES', 'NO')

def test_necessary_condition(run, x):
    import math
    a,b,c = map(int, x.strip().split())
    output = run(x).strip()
    if output == 'YES':
        d = math.gcd(a, b)
        assert c % d == 0

def test_sufficient_condition(run, x):
