    a,b,c = map(int, x.strip().split())
    d = math.gcd(a, b)
    output = run(x).strip()
    if c % d == 0:
        assert output == 'YES'

def test_a_one_always_yes(run, x):
    a,b,c = map(int, x.strip().split())
    output = run(x).strip()
    if a == 1:
        assert output == 'YES'

