def test_direct_gcd_oracle(run, x):
    import math
    A,B,C = map(int, x.split())
    g = math.gcd(A,B)
    correct = 'YES' if C % g == 0 else 'NO'
    output = run(x).strip()
    assert output == correct

def test_brute_force_oracle(run, x):
    A,B,C = map(int, x.split())
    possible = False
    for S in range(1, B+1):
        if (A * S) % B == C:
            possible = True
            break
    correct = 'YES' if possible else 'NO'
    output = run(x).strip()
    assert output == correct

def test_yes_implies_gcd_divides(run, x):
    import math
    A,B,C = map(int, x.split())
    output = run(x).strip()
    if output == 'YES':
        g = math.gcd(A,B)
        assert C % g == 0

def test_no_implies_gcd_not_divides(run, x):
    import math
    A,B,C = map(int, x.split())
    output = run(x).strip()
    if output == 'NO':
        g = math.gcd(A,B)
        assert C % g != 0

def test_output_format(run, x):
    output = run(x)
    stripped = output.strip()
    assert stripped == 'YES' or stripped == 'NO'

def test_A_divides_C_sufficient(run, x):
    A,B,C = map(int, x.split())
    output = run(x).strip()
    if C % A == 0:
        assert output == 'YES'

def test_B_divides_A_case(run, x):
    A,B,C = map(int, x.split())
    output = run(x).strip()
    if A % B == 0:
        if C == 0:
            assert output == 'YES'
        else:
            assert output == 'NO'

def test_gcd_1_always_yes(run, x):
    import math
    A,B,C = map(int, x.split())
    output = run(x).strip()
    if math.gcd(A,B) == 1:
        assert output == 'YES'

def test_C_zero_always_yes(run, x):
    A,B,C = map(int, x.split())
    output = run(x).strip()
    if C == 0:
        assert output == 'YES'

def test_even_even_implies_even(run, x):
    A,B,C = map(int, x.split())
    output = run(x).strip()
    if A % 2 == 0 and B % 2 == 0:
        if output == 'YES':
            assert C % 2 == 0

