def test_brute_force(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    angles = list(map(int, lines[1:1+n]))
    found = False
    for mask in range(1 << n):
        total = 0
        for i in range(n):
            if mask & (1 << i):
                total += angles[i]
            else:
                total -= angles[i]
        if total % 360 == 0:
            found = True
            break
    expected = 'YES' if found else 'NO'
    output = run(x).strip().upper()
    assert output == expected, f'Expected {expected}, got {output}'

def test_examples(run, x):
    output = run(x).strip().upper()
    examples = {
        '3\n10\n20\n30\n': 'YES',
        '3\n10\n10\n10\n': 'NO',
        '3\n120\n120\n120\n': 'YES',
    }
    if x in examples:
        assert output == examples[x], f'Example mismatch: expected {examples[x]}, got {output}'

def test_output_format(run, x):
    output = run(x).strip().upper()
    assert output in ('YES', 'NO'), f'Invalid output: {output}'

def test_all_180(run, x):
    output = run(x).strip().upper()
    lines = x.strip().splitlines()
    n = int(lines[0])
    angles = list(map(int, lines[1:1+n]))
    if all(a == 180 for a in angles):
        expected = 'YES' if n % 2 == 0 else 'NO'
        assert output == expected, f'All 180 case: expected {expected}, got {output}'

def test_sum_divisible_by_360_implies_yes(run, x):
    output = run(x).strip().upper()
    lines = x.strip().splitlines()
    n = int(lines[0])
    angles = list(map(int, lines[1:1+n]))
    if sum(angles) % 360 == 0:
        assert output == 'YES', f'Sum divisible by 360 but output is {output}'

def test_odd_count_odd_implies_no(run, x):
    output = run(x).strip().upper()
    lines = x.strip().splitlines()
    n = int(lines[0])
    angles = list(map(int, lines[1:1+n]))
    odd_count = sum(1 for a in angles if a % 2 == 1)
    if odd_count % 2 == 1:
        assert output == 'NO', f'Odd number of odd angles but output is {output}'

def test_n1_always_no(run, x):
    output = run(x).strip().upper()
    lines = x.strip().splitlines()
    n = int(lines[0])
    if n == 1:
        assert output == 'NO', f'n=1 must output NO, got {output}'

def test_n2_equal_angles_always_yes(run, x):
    output = run(x).strip().upper()
    lines = x.strip().splitlines()
    n = int(lines[0])
    angles = list(map(int, lines[1:1+n]))
    if n == 2 and angles[0] == angles[1]:
        assert output == 'YES', f'n=2 equal angles must output YES, got {output}'

def test_sum_odd_implies_no(run, x):
    output = run(x).strip().upper()
    lines = x.strip().splitlines()
    n = int(lines[0])
    angles = list(map(int, lines[1:1+n]))
    if sum(angles) % 2 == 1:
        assert output == 'NO', f'Sum odd must output NO, got {output}'

def test_yes_implies_sum_even(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    angles = list(map(int, lines[1:1+n]))
    output = run(x).strip().upper()
    if output == 'YES':
        assert sum(angles) % 2 == 0, f'Output YES but sum is odd'

