        i = 0
        for ch in b:
            if i < len(a) and a[i] == ch:
                i += 1
        return i == len(a)
    if all(cnt_s[c] >= cnt_t[c] for c in cnt_t) and sorted(s) != sorted(t) and not is_subseq(t, s):
