def test_oracle(run, x):
    s, t = x.splitlines()
    # Guard: only run oracle on small instances
    if len(s) > 8 or len(t) > 8:
        return
    from collections import Counter
    def is_subseq(a, b):
        i = 0
        for ch in b:
            if i < len(a) and a[i] == ch:
                i += 1
        return i == len(a)
    cnt_s = Counter(s)
    cnt_t = Counter(t)
    if Counter(s) == Counter(t):
