def test_output_format(run, x):
    a,b,c = map(int, x.strip().split())
    out_str = run(x).strip()
    out = int(out_str)
    assert out == -1 or out >= 1

def test_output_bound(run, x):
    a,b,c = map(int, x.strip().split())
    out = int(run(x).strip())
    if out != -1:
        assert out <= 2*b

def test_digit_at_output(run, x):
    a,b,c = map(int, x.strip().split())
    out = int(run(x).strip())
    if out > 0:
        remainder = a
        for pos in range(1, out+1):
            digit = (10 * remainder) // b
            if pos == out:
                assert digit == c
                break
            remainder = (10 * remainder) % b

def test_no_earlier_digit(run, x):
    a,b,c = map(int, x.strip().split())
    out = int(run(x).strip())
    if out > 1:
        remainder = a
        for pos in range(1, out):
            digit = (10 * remainder) // b
            assert digit != c
            remainder = (10 * remainder) % b

def test_first_digit_not_c_if_minus1(run, x):
    a,b,c = map(int, x.strip().split())
    out = int(run(x).strip())
    if out == -1:
        digit = (10 * a) // b
        assert digit != c

def test_second_digit_not_c_if_minus1(run, x):
    a,b,c = map(int, x.strip().split())
    out = int(run(x).strip())
    if out == -1:
        remainder = (10 * a) % b
        digit = (10 * remainder) // b
        assert digit != c

def test_no_c_in_first_min_b_1000_if_minus1(run, x):
    a,b,c = map(int, x.strip().split())
    out = int(run(x).strip())
    if out == -1:
        remainder = a
        limit = min(b, 1000)
        for pos in range(1, limit+1):
            if remainder == 0:
                digit = 0
            else:
                digit = (10 * remainder) // b
                remainder = (10 * remainder) % b
            if digit == c:
                assert False

def test_terminating_c_zero(run, x):
    a,b,c = map(int, x.strip().split())
    out = int(run(x).strip())
    b_orig = b
    while b % 2 == 0:
        b //= 2
    while b % 5 == 0:
        b //= 5
    if b == 1 and c == 0:
        b_temp = b_orig
        v2 = 0
        while b_temp % 2 == 0:
            v2 += 1
            b_temp //= 2
        v5 = 0
        b_temp = b_orig
        while b_temp % 5 == 0:
            v5 += 1
            b_temp //= 5
        k = max(v2, v5)
        remainder = a
        first_zero_pos = None
        for pos in range(1, k+1):
            digit = (10 * remainder) // b_orig
            if digit == 0 and first_zero_pos is None:
                first_zero_pos = pos
            remainder = (10 * remainder) % b_orig
        if first_zero_pos is not None:
            assert out == first_zero_pos
        else:
            assert out == k + 1

def test_pure_repeating_output_bound(run, x):
    import math
    a,b,c = map(int, x.strip().split())
