      "source": "def test_small_correct_bruteforce(run, x):
    n = int(x.strip())
    if n > 28:
        return
    MOD = 10**9 + 7
    max_len = 2 * n
    valid = [[False] * (n + 1) for _ in range(max_len + 1)]
    valid[max_len][0] = True
    for i in range(max_len - 1, -1, -1):
        for b in range(n + 1):
            if b + 1 <= n and valid[i + 1][b + 1]:
                valid[i][b] = True
            if b - 1 >= 0 and valid[i + 1][b - 1]:
                valid[i][b] = True
    node_index = {}
    nodes = []
    for i in range(max_len + 1):
        for b in range(n + 1):
            if valid[i][b]:
                node_index[(i, b)] = len(nodes)
                nodes.append((i, b))
    adj = [[] for _ in range(len(nodes))]
    root_idx = node_index[(0, 0)]
    from collections import deque
    q = deque([root_idx])
    visited = [False] * len(nodes)
    visited[root_idx] = True
    while q:
        u = q.popleft()
        i, b = nodes[u]
        if i == max_len:
            continue
        for delta in (1, -1):
            new_b = b + delta
            if 0 <= new_b <= n and valid[i + 1][new_b]:
                v = node_index[(i + 1, new_b)]
                adj[u].append(v)
                if not visited[v]:
                    visited[v] = True
                    q.append(v)
    dp0 = [0] * len(nodes)
    dp1 = [0] * len(nodes)
    stack = [(root_idx, -1, 0)]
    while stack:
        u, p, st = stack.pop()
        if st == 0:
            stack.append((u, p, 1))
            for v in adj[u]:
                if v != p:
                    stack.append((v, u, 0))
        else:
            sum_a = 0
            sum_b = 0
            for v in adj[u]:
                if v == p:
                    continue
                sum_a += max(dp0[v], dp1[v])
                sum_b += dp0[v]
            dp0[u] = sum_a
            dp1[u] = sum_b
    expected = dp0[root_idx] % MOD
