def test_format(run, x):
    output = run(x)
    lines = output.rstrip('\n').split('\n')
    non_empty = [line for line in lines if line.strip() != '']
    assert len(non_empty) == 1, 'Output should be a single line'
    s = non_empty[0].strip()
    assert s.isdigit(), 'Output must be a non‑negative integer'
    if s != '0':
        assert not s.startswith('0'), 'No leading zeros'
    ans = int(s)
    MOD = 10**9 + 7
    assert 0 <= ans < MOD, f'Output {ans} out of modulo range [0, {MOD})'

