tests_src:
def test_oracle_correct(run, x):
    tokens = x.strip().split()
    if len(tokens) != 2:
        return
    a_str, b_str = tokens
    try:
        a = int(a_str)
        b = int(b_str)
    except ValueError:
        return
    if not (1 <= a <= b):
        return
    out = run(x).strip()
    out_int = int(out)
    if a == b:
        expected = a
    else:
        expected = 1
    assert out_int == expected, f'Expected {expected}, got {out_int}'

def test_output_digits_only(run, x):
    tokens = x.strip().split()
    if len(tokens) != 2:
        return
    a_str, b_str = tokens
    try:
        a = int(a_str)
        b = int(b_str)
    except ValueError:
        return
    if not (1 <= a <= b):
        return
    out = run(x).strip()
    assert out.isdigit(), 'Output must consist only of digits'

def test_no_leading_zeros(run, x):
    tokens = x.strip().split()
    if len(tokens) != 2:
        return
    a_str, b_str = tokens
    try:
        a = int(a_str)
        b = int(b_str)
    except ValueError:
        return
    if not (1 <= a <= b):
        return
    out = run(x).strip()
    assert out, 'Output is empty'
    if out == '0':
        return
    assert out[0] != '0', 'Output has leading zero'

def test_divides_a(run, x):
    tokens = x.strip().split()
    if len(tokens) != 2:
        return
    a_str, b_str = tokens
    try:
        a = int(a_str)
        b = int(b_str)
    except ValueError:
        return
    if not (1 <= a <= b):
        return
    out = run(x).strip()
    d = int(out)
    assert d > 0, 'Output must be positive'
    assert a % d == 0, f'Output {d} does not divide a={a}'

def test_divides_b(run, x):
    tokens = x.strip().split()
    if len(tokens) != 2:
        return
    a_str, b_str = tokens
    try:
        a = int(a_str)
        b = int(b_str)
    except ValueError:
        return
    if not (1 <= a <= b):
        return
    out = run(x).strip()
    d = int(out)
    assert d > 0, 'Output must be positive'
    assert b % d == 0, f'Output {d} does not divide b={b}'

def test_output_ge_1(run, x):
    tokens = x.strip().split()
    if len(tokens) != 2:
        return
    a_str, b_str = tokens
    try:
        a = int(a_str)
        b = int(b_str)
    except ValueError:
        return
    if not (1 <= a <= b):
        return
    out = run(x).strip()
    d = int(out)
    assert d >= 1, 'Output must be at least 1'

def test_eq_case(run, x):
    tokens = x.strip().split()
    if len(tokens) != 2:
        return
    a_str, b_str = tokens
    try:
        a = int(a_str)
        b = int(b_str)
    except ValueError:
        return
    if not (1 <= a <= b):
        return
    if a != b:
        return
    out = run(x).strip()
    d = int(out)
    assert d == a, f'When a=b={a}, output should be {a}, got {d}'

def test_neq_case(run, x):
    tokens = x.strip().split()
    if len(tokens) != 2:
        return
    a_str, b_str = tokens
    try:
        a = int(a_str)
        b = int(b_str)
    except ValueError:
        return
    if not (1 <= a <= b):
        return
    if a >= b:
        return
    out = run(x).strip()
    d = int(out)
    assert d == 1, f'When a<b, output should be 1, got {d}'

def test_divides_gcd_ab(run, x):
    import math
    tokens = x.strip().split()
    if len(tokens) != 2:
        return
    a_str, b_str = tokens
    try:
        a = int(a_str)
        b = int(b_str)
    except ValueError:
        return
    if not (1 <= a <= b):
        return
    out = run(x).strip()
    d = int(out)
    g = math.gcd(a, b)
    assert g % d == 0, f'Output {d} does not divide gcd(a,b)={g}'

def test_divides_diff(run, x):
    tokens = x.strip().split()
    if len(tokens) != 2:
        return
    a_str, b_str = tokens
    try:
        a = int(a_str)
        b = int(b_str)
    except ValueError:
        return
    if not (1 <= a <= b):
        return
    out = run(x).strip()
    d = int(out)
    diff = b - a
    if diff != 0:
        assert diff % d == 0, f'Output {d} does not divide b-a={diff}'

