tests_src:
def test_brute_force(run, x):
    output = run(x).strip()
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n = int(lines[0])
    s = lines[1].strip()
    if len(set(s)) < 2:
        return  # invalid input, skip assertion
    cnt = 0
    for l in range(n):
        for r in range(l, n):
            rem = s[:l] + s[r+1:]
            if len(set(rem)) <= 1:
                cnt += 1
    expected = cnt % 998244353
    assert int(output) == expected

def test_examples(run, x):
    output = run(x).strip()
    examples = {
        "2\naz\n": 3,
        "4\nabaa\n": 6,
        "7\naacdeee\n": 6,
    }
    if x in examples:
        assert int(output) == examples[x]

def test_n2_case(run, x):
    output = run(x).strip()
    lines = x.strip().split('\n')
    if len(lines) >= 2:
        n = int(lines[0])
        s = lines[1].strip()
        if n == 2 and len(set(s)) == 2:
            assert int(output) == 3

def test_positive(run, x):
    output = run(x).strip()
    val = int(output)
    assert val >= 1

def test_upper_bound(run, x):
    output = run(x).strip()
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n = int(lines[0])
    s = lines[1].strip()
    if len(set(s)) < 2:
        return  # invalid input, skip assertion
    total_substrings = n * (n+1) // 2
    assert int(output) <= total_substrings

def test_lower_bound_diff(run, x):
    output = run(x).strip()
    lines = x.strip().split('\n')
    if len(lines) >= 2:
        s = lines[1].strip()
        if s[0] != s[-1]:
            assert int(output) >= 3

def test_lower_bound_general(run, x):
    output = run(x).strip()
    lines = x.strip().split('\n')
    if len(lines) >= 2:
        n = int(lines[0])
        s = lines[1].strip()
        L = 0
        while L < n and s[L] == s[0]:
            L += 1
        R = 0
        while R < n and s[n-1-R] == s[-1]:
            R += 1
        assert int(output) >= 1 + L + R

def test_mod_less(run, x):
    output = run(x).strip()
    val = int(output)
    assert val < 998244353

def test_format(run, x):
    output = run(x).strip()
    assert output == str(int(output))

def test_single_char_removal(run, x):
    output = run(x).strip()
    lines = x.strip().split('\n')
    if len(lines) >= 2:
        n = int(lines[0])
        s = lines[1].strip()
        cnt = 0
        for i in range(n):
            rem = s[:i] + s[i+1:]
            if len(set(rem)) <= 1:
                cnt += 1
        assert int(output) >= cnt

def test_direct_formula(run, x):
    n,k = map(int, x.strip().split())
    D = [1,0,1,2,9]
    ans = 0
    for j in range(k+1):
        if j == 0:
            c = 1
        elif j == 1:
            c = n
        elif j == 2:
            c = n*(n-1)//2
        elif j == 3:
            c = n*(n-1)*(n-2)//6
        elif j == 4:
            c = n*(n-1)*(n-2)*(n-3)//24
        else:
            c = 0
        ans += c * D[j]
    out = run(x).strip()
    assert out.isdigit()
    assert int(out) == ans

def test_brute_force_small_n(run, x):
    n,k = map(int, x.strip().split())
    if n > 9:
        return
    import itertools
    count = 0
    for perm in itertools.permutations(range(1, n+1)):
        fixed = sum(1 for i in range(1, n+1) if perm[i-1] == i)
        if fixed >= n - k:
            count += 1
    out = run(x).strip()
    assert out.isdigit()
    assert int(out) == count

def test_positive(run, x):
    out = run(x).strip()
    assert out.isdigit()
    val = int(out)
    assert val > 0

def test_upper_bound_small_n(run, x):
    n,k = map(int, x.strip().split())
    if n > 12:
        return
    import math
    fact = math.factorial(n)
    out = run(x).strip()
    assert out.isdigit()
    val = int(out)
    assert val <= fact

def test_k1(run, x):
    n,k = map(int, x.strip().split())
    if k != 1:
        return
    out = run(x).strip()
    assert out == '1'

def test_k2(run, x):
    n,k = map(int, x.strip().split())
    if k != 2:
        return
    expected = 1 + n*(n-1)//2
    out = run(x).strip()
    assert out.isdigit()
    assert int(out) == expected

def test_k3(run, x):
    n,k = map(int, x.strip().split())
    if k != 3:
        return
    expected = 1 + n*(n-1)//2 + n*(n-1)*(n-2)//3
    out = run(x).strip()
    assert out.isdigit()
    assert int(out) == expected

def test_k4(run, x):
    n,k = map(int, x.strip().split())
    if k != 4:
        return
    expected = 1 + n*(n-1)//2 + 2 * n*(n-1)*(n-2)//6 + 9 * n*(n-1)*(n-2)*(n-3)//24
    out = run(x).strip()
    assert out.isdigit()
    assert int(out) == expected

def test_format(run, x):
    out = run(x)
    lines = out.splitlines()
    assert len(lines) == 1
    line = lines[0]
    stripped = line.strip()
    assert stripped.isdigit()
    assert stripped == ''.join(line.split())

def test_large_n_1000(run, x):
    n,k = map(int, x.strip().split())
    if n != 1000:
        return
    D = [1,0,1,2,9]
    ans = 0
    for j in range(k+1):
        if j == 0:
            c = 1
        elif j == 1:
            c = n
        elif j == 2:
            c = n*(n-1)//2
        elif j == 3:
            c = n*(n-1)*(n-2)//6
        elif j == 4:
            c = n*(n-1)*(n-2)*(n-3)//24
        else:
            c = 0
        ans += c * D[j]
    out = run(x).strip()
    assert out.isdigit()
    assert int(out) == ans

