def test_encoding_match(run, x):
    output = run(x).rstrip('\n')
    def is_valid(x):
        x = x.rstrip()
        lines = x.splitlines()
        if len(lines) != 2:
            return None
        try:
            n = int(lines[0])
        except:
            return None
        s = lines[1]
        if len(s) != n:
            return None
        return n, s
    parsed = is_valid(x)
    if parsed is None:
        return
    n, s = parsed
    def encode(word):
        w = list(word)
        res = []
        while w:
