def test_parse(run, x):
    out = run(x)
    s = out.strip()
    try:
        float(s)
    except ValueError:
        assert False

def test_positive(run, x):
    h, l = map(int, x.strip().split())
    d = float(run(x).strip())
    assert d > 0

def test_upper_bound(run, x):
    h, l = map(int, x.strip().split())
    d = float(run(x).strip())
    upper = l * l / (2 * h)
    assert d <= upper * (1 + 1e-9) + 1e-9

def test_direct_comparison(run, x):
    h, l = map(int, x.strip().split())
    d_true = (l * l - h * h) / (2 * h)
    d = float(run(x).strip())
    if abs(d - d_true) > 1e-6 * max(1, abs(d_true)):
        assert False

def test_format(run, x):
    out = run(x)
    lines = out.strip().splitlines()
    assert len(lines) == 1
    s = lines[0].strip()
    try:
        float(s)
    except ValueError:
        assert False
    if any(c.isspace() for c in s):
        assert False
    assert s != ''

def test_not_too_large(run, x):
    d = float(run(x).strip())
    assert d < 1e13

def test_example_small(run, x):
    out = run(x)
    if x.strip() == "1 2":
        d = float(out.strip())
        expected = 1.5
        if abs(d - expected) > 1e-6 * max(1, expected):
            assert False

def test_small_rational_check(run, x):
    h, l = map(int, x.strip().split())
    out = run(x)
    if h > 100 or l > 1000:
        return
    from fractions import Fraction
    d_exact = Fraction(l*l - h*h, 2*h)
    d_float = float(d_exact)
    d = float(out.strip())
    if abs(d - d_float) > 1e-6 * max(1, d_float):
        assert False

def test_equation_safe(run, x):
    h, l = map(int, x.strip().split())
    out = run(x)
    d = float(out.strip())
    residual = 2*h*d + h*h - l*l
    eps = 1e-6
    tol = 2 * h * eps * max(1, d) * (1 + eps)
    if abs(residual) > tol:
        assert False

def test_close_pair_large(run, x):
    h, l = map(int, x.strip().split())
    out = run(x)
    if l != h + 1:
        return
    d_true = 1 + 1/(2*h)
    d = float(out.strip())
    if abs(d - d_true) > 1e-6 * max(1, d_true):
        assert False

