def test_full_oracle(run, x):
    a,b = map(int, x.split())
    if a+b == 0:
        correct = "NO"
    else:
        n = a+b
        evens1 = n//2
        odds1 = (n+1)//2
        evens2 = (n+1)//2
        odds2 = n//2
        if (a == evens1 and b == odds1) or (a == evens2 and b == odds2):
            correct = "YES"
        else:
            correct = "NO"
    out = run(x).strip()
    assert out == correct

def test_zero_zero(run, x):
    a,b = map(int, x.split())
    if a == 0 and b == 0:
        out = run(x).strip()
        assert out == "NO"

def test_equal_positive(run, x):
    a,b = map(int, x.split())
    if a == b and a > 0:
        out = run(x).strip()
        assert out == "YES"

def test_a_eq_b_plus_one(run, x):
    a,b = map(int, x.split())
    if a == b+1 and a > 0:
        out = run(x).strip()
        assert out == "YES"

def test_b_eq_a_plus_one(run, x):
    a,b = map(int, x.split())
    if b == a+1 and b > 0:
        out = run(x).strip()
        assert out == "YES"

def test_diff_gt_one(run, x):
    a,b = map(int, x.split())
    if abs(a-b) > 1:
        out = run(x).strip()
        assert out == "NO"

def test_0_1(run, x):
    a,b = map(int, x.split())
    if a == 0 and b == 1:
        out = run(x).strip()
        assert out == "YES"

def test_1_0(run, x):
