    if a == 0 and b == 2:
        out = run(x).strip()
        assert out == "NO"

def test_2_0(run, x):
    a,b = map(int, x.split())
    if a == 2 and b == 0:
        out = run(x).strip()
        assert out == "NO"

def test_output_integer(run, x):
