    n = int(n_s[0])
    s = int(n_s[1])
    passengers = [tuple(map(int, lines[i].split())) for i in range(1, n+1)]
    max_t = max(t for f, t in passengers)
    upper = max_t + s
    assert out <= upper, f'Answer {out} must be at most max(t)+s={upper}'

def test_formula(run, x):
