    n_s = lines[0].split()
    n = int(n_s[0])
    s = int(n_s[1])
    passengers = [tuple(map(int, lines[i].split())) for i in range(1, n+1)]
    max_tf = max(t + f for f, t in passengers)
    expected = max(s, max_tf)
    assert out == expected, f'Answer {out} should equal max(s, max(t+f))={expected}'

def test_greedy_simulation(run, x):
    out_str = run(x).strip()
    try:
        out = int(out_str)
    except ValueError:
        assert False, f'Output "{out_str}" is not an integer'
    lines = x.strip().splitlines()
    n_s = lines[0].split()
    n = int(n_s[0])
    s = int(n_s[1])
    passengers = [tuple(map(int, lines[i].split())) for i in range(1, n+1)]
    floor_dict = {}
    for f, t in passengers:
        if f not in floor_dict:
            floor_dict[f] = t
        else:
            floor_dict[f] = max(floor_dict[f], t)
    floors = sorted(floor_dict.keys(), reverse=True)
    current_time = 0
    current_floor = s
    for f in floors:
        current_time += current_floor - f
        current_time = max(current_time, floor_dict[f])
        current_floor = f
    current_time += current_floor
    expected = current_time
    assert out == expected, f'Answer {out} should equal greedy simulation result {expected}'

