    passengers = [tuple(map(int, lines[i].split())) for i in range(1, n+1)]
    if all(f == s for f, _ in passengers):
        max_t = max(t for _, t in passengers)
        expected = max_t + s
        assert out == expected, f'All passengers on top floor, answer {out} should be {expected}'

def test_examples(run, x):
    out_str = run(x).strip()
    try:
        out = int(out_str)
    except ValueError:
        assert False, f'Output "{out_str}" is not an integer'
    if x == '3 7\n2 1\n3 8\n5 2\n':
        assert out == 11, f'For first example, answer should be 11, got {out}'
    elif x == '5 10\n2 77\n3 33\n8 21\n9 12\n10 64\n':
        assert out == 79, f'For second example, answer should be 79, got {out}'

