def test_bruteforce_small_n(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0].strip())
    a = list(map(int, lines[1].split()))
    if n > 11:
        return
    from functools import lru_cache
    @lru_cache(None)
    def dfs(arr):
        if len(arr) == 1:
            return arr[0]
        best = 0
        m = len(arr)
        for i in range(m):
            left = (i-1) % m
            right = (i+1) % m
            new_val = arr[left] + arr[right]
            new_list = []
            for j in range(m):
                if j == left or j == right:
                    continue
                if j == i:
                    new_list.append(new_val)
                else:
                    new_list.append(arr[j])
            best = max(best, dfs(tuple(new_list)))
        return best
    expected = dfs(tuple(a))
    output = run(x).strip()
    assert int(output) == expected

def test_n1_single_element(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0].strip())
    if n != 1:
        return
    a = list(map(int, lines[1].split()))
    output = run(x).strip()
    assert int(output) == a[0]

def test_n3_sum_minus_min(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0].strip())
    if n != 3:
        return
    a = list(map(int, lines[1].split()))
    expected = sum(a) - min(a)
    output = run(x).strip()
    assert int(output) == expected

def test_all_zero(run, x):
    a = list(map(int, x.strip().splitlines()[1].split()))
    if all(v == 0 for v in a):
        output = run(x).strip()
        assert int(output) == 0

def test_output_format_integer(run, x):
    output = run(x).strip()
    assert output.isdigit()

def test_answer_nonnegative(run, x):
    output = run(x).strip()
    val = int(output)
    assert val >= 0

def test_answer_le_total_sum(run, x):
    lines = x.strip().splitlines()
    a = list(map(int, lines[1].split()))
    total = sum(a)
    output = run(x).strip()
    val = int(output)
    assert val <= total

def test_example_from_statement_1(run, x):
    if x == "3\n7 10 2\n":
        output = run(x).strip()
        assert output == "17"

def test_example_from_statement_2(run, x):
    if x == "1\n4\n":
        output = run(x).strip()
        assert output == "4"

def test_n5_min_nonadjacent_pair(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0].strip())
    if n != 5:
        return
    a = list(map(int, lines[1].split()))
    total = sum(a)
    min_sum = float('inf')
    for i in range(5):
        for j in range(i+1,5):
            if (i+1)%5 == j or (j+1)%5 == i:
                continue
            s = a[i] + a[j]
            if s < min_sum:
                min_sum = s
    expected = total - min_sum
    output = run(x).strip()
    assert int(output) == expected

