    def correct_res(s):
        has_odd = {chr(ord('a')+i): False for i in range(26)}
        i = 0
        n = len(s)
        while i < n:
            j = i
            while j < n and s[j] == s[i]:
                j += 1
            if (j - i) % 2 == 1:
                has_odd[s[i]] = True
            i = j
        return ''.join(c for c in sorted(has_odd.keys()) if has_odd[c])
    out_lines = run(x).strip().splitlines()
    in_lines = x.strip().splitlines()
    if not in_lines:
        assert out_lines == []
        return
    t = int(in_lines[0])
    inputs = [line.strip() for line in in_lines[1:1+t]]
    assert len(out_lines) == t
    for i in range(t):
        expected = correct_res(inputs[i])
        assert out_lines[i] == expected

