def test_brute_force_comparison(run, x):
    lines = x.strip().split('\n')
    bills = list(map(int, lines[1].split()))
    n = len(bills)
    if n > 10:   # guard: brute force too slow for larger n
        return
    from functools import lru_cache
    @lru_cache(None)
    def dfs(i, c25, c50):
        if i == n:
            return True
        b = bills[i]
        if b == 25:
            if dfs(i+1, c25+1, c50):
                return True
        elif b == 50:
            if c25 >= 1 and dfs(i+1, c25-1, c50+1):
                return True
        else:
            if c50 >= 1 and c25 >= 1 and dfs(i+1, c25-1, c50-1):
                return True
            if c25 >= 3 and dfs(i+1, c25-3, c50):
                return True
        return False
    correct = dfs(0, 0, 0)
    output = run(x)
    output_bool = (output.strip() == "YES")
    assert output_bool == correct, f"Brute force says {correct}, output says {output.strip()}"

