        n = len(bills)
        @lru_cache(None)
        def dfs(i, a, b):
            if i == n:
                return True
            x = bills[i]
            if x == 25:
                return dfs(i+1, a+1, b)
            elif x == 50:
                if a > 0:
                    return dfs(i+1, a-1, b+1)
                else:
                    return False
            else:
