tests_src:
def test_line_count(run, x):
    n, m = map(int, x.strip().split())
    lines = run(x).splitlines()
    assert len(lines) == n

def test_line_length(run, x):
    n, m = map(int, x.strip().split())
    lines = run(x).splitlines()
    for line in lines:
        assert len(line) == m

def test_characters(run, x):
    lines = run(x).splitlines()
    for line in lines:
        for ch in line:
            assert ch in ('.', '#')

def test_odd_rows_full(run, x):
    lines = run(x).splitlines()
    for i, line in enumerate(lines):
        if i % 2 == 0:
            assert line == '#' * len(line)

def test_even_rows_single_hash(run, x):
    lines = run(x).splitlines()
    for i, line in enumerate(lines):
        if i % 2 == 1:
            assert line.count('#') == 1

def test_even_rows_right(run, x):
    lines = run(x).splitlines()
    for i, line in enumerate(lines):
        if i % 4 == 1:
            assert line.endswith('#')

def test_even_rows_left(run, x):
    lines = run(x).splitlines()
    for i, line in enumerate(lines):
        if i % 4 == 3:
            assert line.startswith('#')

def test_hash_count(run, x):
    n, m = map(int, x.strip().split())
    lines = run(x).splitlines()
    total = sum(line.count('#') for line in lines)
    expected = ((n + 1) // 2) * m + (n - 1) // 2
    assert total == expected

def test_first_last_full(run, x):
    lines = run(x).splitlines()
    if lines:
        assert lines[0] == '#' * len(lines[0])
        assert lines[-1] == '#' * len(lines[-1])

def test_full_oracle(run, x):
    n, m = map(int, x.strip().split())
    grid = []
    for i in range(n):
        if i % 2 == 0:
            grid.append('#' * m)
        else:
            if (i // 2) % 2 == 0:
                grid.append('.' * (m - 1) + '#')
            else:
                grid.append('#' + '.' * (m - 1))
    expected = '\n'.join(grid)
    output = run(x).rstrip('\n')
    assert output == expected

