def test_number_of_lexemes(run, x):
    def parse(s):
        lexemes = []
        i = 0
        n = len(s)
        while i < n:
            if s[i] == ' ':
                i += 1
                continue
            if s[i] == '"':
                j = i + 1
                while j < n and s[j] != '"':
                    j += 1
                lexemes.append(s[i+1:j])
                i = j + 1
            else:
                j = i
                while j < n and s[j] != ' ':
                    j += 1
                lexemes.append(s[i:j])
                i = j
        return lexemes
    expected = parse(x)
    output = run(x)
    lines = output.splitlines()
    assert len(lines) == len(expected), f"expected {len(expected)} lexemes, got {len(lines)}"

def test_each_line_format(run, x):
    output = run(x)
    lines = output.splitlines()
    for line in lines:
        assert line.startswith('<') and line.endswith('>'), f"line '{line}' does not start with '<' and end with '>'"
        assert line.count('<') == 1 and line.count('>') == 1, f"line '{line}' has extra angle brackets"

def test_lexeme_contents_match(run, x):
    def parse(s):
        lexemes = []
        i = 0
        n = len(s)
        while i < n:
            if s[i] == ' ':
                i += 1
                continue
            if s[i] == '"':
                j = i + 1
                while j < n and s[j] != '"':
                    j += 1
                lexemes.append(s[i+1:j])
                i = j + 1
            else:
                j = i
                while j < n and s[j] != ' ':
                    j += 1
                lexemes.append(s[i:j])
                i = j
        return lexemes
    expected = parse(x)
    output = run(x)
    lines = output.splitlines()
    assert len(lines) == len(expected), "number of lines mismatch"
    for idx, (line, exp) in enumerate(zip(lines, expected)):
        assert line[0] == '<' and line[-1] == '>', f"line {idx} missing brackets"
        content = line[1:-1]
        assert content == exp, f"line {idx}: expected '{exp}', got '{content}'"

def test_quoted_lexemes_no_quotes(run, x):
    def parse_with_info(s):
        lexemes = []
        is_quoted = []
        i = 0
        n = len(s)
        while i < n:
            if s[i] == ' ':
                i += 1
                continue
            if s[i] == '"':
                j = i + 1
                while j < n and s[j] != '"':
                    j += 1
                lexemes.append(s[i+1:j])
                is_quoted.append(True)
                i = j + 1
            else:
                j = i
                while j < n and s[j] != ' ':
                    j += 1
                lexemes.append(s[i:j])
                is_quoted.append(False)
                i = j
        return lexemes, is_quoted
    expected, quoted = parse_with_info(x)
    output = run(x)
    lines = output.splitlines()
    if len(lines) != len(expected):
        return
    for line, is_q in zip(lines, quoted):
        if is_q:
            content = line[1:-1]
            assert '\"' not in content, f"quoted lexeme contains quote: {content}"

def test_nonquoted_lexemes_no_spaces(run, x):
    def parse_with_info(s):
        lexemes = []
        is_quoted = []
        i = 0
        n = len(s)
        while i < n:
            if s[i] == ' ':
                i += 1
                continue
            if s[i] == '"':
                j = i + 1
                while j < n and s[j] != '"':
                    j += 1
                lexemes.append(s[i+1:j])
                is_quoted.append(True)
                i = j + 1
            else:
                j = i
                while j < n and s[j] != ' ':
                    j += 1
                lexemes.append(s[i:j])
                is_quoted.append(False)
                i = j
        return lexemes, is_quoted
    expected, quoted = parse_with_info(x)
    output = run(x)
    lines = output.splitlines()
    if len(lines) != len(expected):
        return
    for line, exp, is_q in zip(lines, expected, quoted):
        if not is_q:
            content = line[1:-1]
            assert ' ' not in content, f"non-quoted lexeme contains space: {content}"

def test_empty_lexeme(run, x):
    def parse(s):
        lexemes = []
        i = 0
