        if exp == '':
            assert line == '<>', f"empty lexeme should be '<>', got '{line}'"

def test_no_double_quotes_in_output(run, x):
    output = run(x)
    assert '\"' not in output, "output contains double quotes"

def test_output_ends_with_newline(run, x):
    output = run(x)
    assert output.endswith('\n'), "output does not end with newline"

def test_output_starts_with_angle_bracket(run, x):
    output = run(x)
    assert output and output[0] == '<', "output does not start with '<'"

def test_output_characters_allowed(run, x):
    allowed = set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789.,?! <>\n")
    output = run(x)
    for ch in output:
        assert ch in allowed, f"output contains disallowed character: {repr(ch)}"

