def test_bruteforce_small(run, x):
    w, h = map(int, x.split())
    output = run(x).strip()
    if w * h > 9:
        return
    # orientation: 0=TL black,1=TR black,2=BL black,3=BR black
    top = [1,1,0,0]
    left = [1,0,1,0]
    bottom = [0,0,1,1]
    right = [0,1,0,1]
    grid = [0] * (w * h)
    count = 0
    def backtrack(idx):
        nonlocal count
        i = idx // w
        j = idx % w
        for o in range(4):
            if j > 0:
                left_o = grid[idx-1]
                if right[left_o] == left[o]:
                    continue
            if i > 0:
                top_o = grid[idx - w]
                if bottom[top_o] == top[o]:
                    continue
            grid[idx] = o
            if idx + 1 == w * h:
                count += 1
            else:
                backtrack(idx+1)
    backtrack(0)
    expected_mod = count % 998244353
    assert int(output) == expected_mod

