    out = run(x)
    lines = x.strip().split('\n')
    parts = lines[0].split()
    if len(parts) < 3:
        return
    n, k, x_col = map(int, parts[:3])
    c = list(map(int, lines[1].split()))
    if n > 6:
        return
    def max_destroyed(n, k, x, c):
        best = 0
        for pos in range(n + 1):
            row = c[:pos] + [x] + c[pos:]
            total_removed = 0
            while True:
                new_row = []
                i = 0
                while i < len(row):
