                    else:
                        new_row.extend(row[i:j])
                    i = j
                if new_row == row:
                    break
                row = new_row
            destroyed_original = total_removed - 1 if total_removed > 0 else 0
            if destroyed_original > best:
                best = destroyed_original
        return best
    expected = max_destroyed(n, k, x_col, c)
