def test_dominant_bid(run, x):
    out = run(x)
    lines = x.strip().splitlines()
    n = int(lines[0].strip())
    ranges = []
    for i in range(1, n + 1):
        L, R = map(int, lines[i].split())
        ranges.append((L, R))
    found = False
    for i in range(n):
        Li, Ri = ranges[i]
        others = [ranges[j] for j in range(n) if j != i]
        if not others:
            continue
        max_other_R = max(R for L, R in others)
        if Li > max_other_R:
            found = True
            total = 0.0
            for v in range(1, 10001):
                prob_all_lt = 1.0
                for L, R in others:
                    size = R - L + 1
                    if v <= L:
                        prob_all_lt = 0.0
                        break
                    elif v > R:
                        continue
                    else:
                        prob_lt = (v - L) / size
                        prob_all_lt *= prob_lt
                total += 1.0 - prob_all_lt
            expected = total
            try:
                ans = float(out)
            except:
                assert False, "Output not a valid float"
            if not (abs(ans - expected) <= 1e-9 + 1e-9 * abs(expected)):
                assert False, f"Dominant bid case expected {expected}, got {ans}"
            break


