tests_src:
def test_exact_simulation(run, x):
    events = list(map(int, x.strip().split()[1:]))
    s = 0
    u = 0
    for a in events:
        if a == -1:
            if s > 0:
                s -= 1
            else:
                u += 1
        else:
            s += a
    expected = u
    output = run(x).strip()
    assert output == str(expected)

def test_nonnegative(run, x):
    output = run(x).strip()
    assert int(output) >= 0

def test_le_crimes(run, x):
    events = list(map(int, x.strip().split()[1:]))
    crime_count = sum(1 for a in events if a == -1)
    output = run(x).strip()
    assert int(output) <= crime_count

def test_format(run, x):
    output = run(x)
    lines = output.splitlines()
    assert len(lines) == 1
    line = lines[0]
    assert line.strip() == line
    assert line.isdigit()

def test_no_crimes_zero(run, x):
    events = list(map(int, x.strip().split()[1:]))
    if any(a == -1 for a in events):
        return
    output = run(x).strip()
    assert output == "0"

def test_no_recruits_all_crimes(run, x):
    events = list(map(int, x.strip().split()[1:]))
    if any(a > 0 for a in events):
        return
    crime_count = sum(1 for a in events if a == -1)
    output = run(x).strip()
    assert output == str(crime_count)

def test_ge_deficit(run, x):
    events = list(map(int, x.strip().split()[1:]))
    total_crimes = sum(1 for a in events if a == -1)
    total_recruits = sum(a for a in events if a > 0)
    lower = max(0, total_crimes - total_recruits)
    output = run(x).strip()
    assert int(output) >= lower

def test_single_crime(run, x):
    parts = list(map(int, x.strip().split()))
    if len(parts) != 2:
        return
    n = parts[0]
    if n != 1:
        return
    event = parts[1]
    if event != -1:
        return
    output = run(x).strip()
    assert output == "1"

def test_single_recruit(run, x):
    parts = list(map(int, x.strip().split()))
    if len(parts) != 2:
        return
    n = parts[0]
    if n != 1:
        return
    event = parts[1]
    if event <= 0:
        return
    output = run(x).strip()
    assert output == "0"

def test_always_sufficient(run, x):
    events = list(map(int, x.strip().split()[1:]))
    crimes_so_far = 0
    recruits_so_far = 0
    for a in events:
        if a == -1:
            crimes_so_far += 1
        else:
            recruits_so_far += a
        if crimes_so_far > recruits_so_far:
            return
    output = run(x).strip()
    assert output == "0"

