    import itertools
    from collections import deque
    def solve_one(n, k, a):
        M = max(a)
        if n > 4 or M > 5:
            return None
        candidates = []
        for comb in itertools.combinations_with_replacement(range(M+1), n):
            if all(comb[j] <= a[j] for j in range(n)):
                if len(set(comb)) <= k:
                    candidates.append(comb)
        if not candidates:
            return -1
        start = tuple(0 for _ in range(n))
        target = tuple(a)
        if start == target:
            return 0
        visited = {start}
        q = deque([(start, 0)])
        while q:
            state, dist = q.popleft()
            for cand in candidates:
                new_state = tuple(state[i] + cand[i] for i in range(n))
                if any(new_state[i] > target[i] for i in range(n)):
                    continue
                if new_state == target:
                    return dist + 1
                if new_state not in visited:
                    visited.add(new_state)
                    q.append((new_state, dist+1))
        return -1
    data = x.strip().split()
    if not data:
        return
