def test_starts_with_yes_or_no(run, x):
    output = run(x)
    lines = output.splitlines()
    assert lines, "output empty"
    assert lines[0] in ('YES', 'NO'), f"first line must be YES or NO, got {lines[0]}"


def test_line_count(run, x):
    in_lines = x.strip().splitlines()
    n = int(in_lines[0])
    output = run(x)
    out_lines = output.splitlines()
    if out_lines[0] == 'NO':
        assert len(out_lines) == 1, "NO output should have exactly one line"
    else:
        assert out_lines[0] == 'YES'
        assert len(out_lines) == 2 * n, f"YES output should have {2*n} lines, got {len(out_lines)}"


def test_board_lines_length(run, x):
    in_lines = x.strip().splitlines()
    n = int(in_lines[0])
    output = run(x)
    out_lines = output.splitlines()
    if out_lines[0] != 'YES':
        return
    for idx, line in enumerate(out_lines[1:]):
        assert len(line) == 2*n - 1, f"board line {idx+1} has length {len(line)}, expected {2*n-1}"


def test_board_chars(run, x):
    output = run(x)
    out_lines = output.splitlines()
    if out_lines[0] != 'YES':
        return
    for line in out_lines[1:]:
        for ch in line:
            assert ch in 'ox.', f"invalid character '{ch}' in board"


def test_center_o(run, x):
    in_lines = x.strip().splitlines()
    n = int(in_lines[0])
    output = run(x)
    out_lines = output.splitlines()
    if out_lines[0] != 'YES':
        return
    center_line = out_lines[n]
    assert center_line[n-1] == 'o', f"center should be 'o', got {center_line[n-1]}"


def test_no_self_move(run, x):
    output = run(x)
    out_lines = output.splitlines()
    if out_lines[0] != 'YES':
        return
    o_count = sum(line.count('o') for line in out_lines[1:])
    assert o_count == 1, f"expected exactly one 'o' in board, found {o_count}"


def test_attack_x_cells(run, x):
    in_lines = x.strip().splitlines()
    n = int(in_lines[0])
    board = in_lines[1:]
    output = run(x)
    out_lines = output.splitlines()
    if out_lines[0] != 'YES':
        return
    moves = set()
    board_lines = out_lines[1:]
    for r_idx, line in enumerate(board_lines):
        for c_idx, ch in enumerate(line):
            if ch == 'x':
                dx = c_idx - (n-1)
                dy = r_idx - (n-1)
                moves.add((dx, dy))
    pieces = [(i, j) for i in range(n) for j in range(n) if board[i][j] == 'o']
    for i in range(n):
        for j in range(n):
            if board[i][j] == 'x':
                attacked = False
                for pi, pj in pieces:
                    dx = j - pj
                    dy = i - pi
                    if (dx, dy) in moves:
                        attacked = True
                        break
                assert attacked, f"cell ({i},{j}) marked 'x' is not attacked"


def test_no_attack_dot_cells(run, x):
    in_lines = x.strip().splitlines()
    n = int(in_lines[0])
    board = in_lines[1:]
    output = run(x)
    out_lines = output.splitlines()
    if out_lines[0] != 'YES':
        return
    moves = set()
    board_lines = out_lines[1:]
    for r_idx, line in enumerate(board_lines):
        for c_idx, ch in enumerate(line):
            if ch == 'x':
                dx = c_idx - (n-1)
                dy = r_idx - (n-1)
                moves.add((dx, dy))
    pieces = [(i, j) for i in range(n) for j in range(n) if board[i][j] == 'o']
    for i in range(n):
        for j in range(n):
            if board[i][j] == '.':
                for pi, pj in pieces:
                    dx = j - pj
                    dy = i - pi
                    assert (dx, dy) not in moves, f"cell ({i},{j}) attacked by piece at ({pi},{pj})"


def test_small_n_decision_correct(run, x):
    in_lines = x.strip().splitlines()
    if not in_lines:
        return
    n = int(in_lines[0])
    if n > 2:
        return
    board = in_lines[1:]
    pieces = [(i, j) for i in range(n) for j in range(n) if board[i][j] == 'o']
    x_cells = [(i, j) for i in range(n) for j in range(n) if board[i][j] == 'x']
    dot_cells = [(i, j) for i in range(n) for j in range(n) if board[i][j] == '.']
    shifts = []
    for dx in range(-(n-1), n):
        for dy in range(-(n-1), n):
            if dx == 0 and dy == 0:
                continue
            shifts.append((dx, dy))
    forbidden = set()
    for pi, pj in pieces:
        for di, dj in dot_cells:
            forbidden.add((dj - pj, di - pi))
    x_reqs = []
    for xi, xj in x_cells:
        req = set()
        for pi, pj in pieces:
            req.add((xj - pj, xi - pi))
        x_reqs.append(req)
    m = len(shifts)
    found = False
    for mask in range(1 << m):
        chosen = set()
        for k in range(m):
            if mask & (1 << k):
                chosen.add(shifts[k])
        if chosen & forbidden:
            continue
        ok = True
        for req in x_reqs:
            if not (chosen & req):
                ok = False
                break
        if ok:
            found = True
            break
    output = run(x)
    out_lines = output.splitlines()
    assert out_lines, "output empty"
    first = out_lines[0]
    if found:
        assert first == 'YES', f"Expected YES because a valid set exists, got {first}"
    else:
        assert first == 'NO', f"Expected NO because no valid set exists, got {first}"


def test_no_spaces(run, x):
    output = run(x)
    lines = output.splitlines()
    for line in lines:
        assert ' ' not in line, "output contains space character"

