def test_output_format(run, x):
    out = run(x)
    lines = out.strip().split()
    if not x.strip():
        return
    t = int(x.strip().split()[0])
    assert len(lines) == t, f"Expected {t} output lines, got {len(lines)}"
    for line in lines:
        int(line)

def test_k1_correct(run, x):
