        idx += 2
        a = list(map(int, data[idx:idx+n]))
        idx += n
        if k == 1:
            U = len(set(a))
            expected = -1 if U > 1 else 1
            assert int(out_lines[case]) == expected, f"For test case {case+1}: k=1, U={U}, expected {expected}, got {out_lines[case]}"

