            else:
                lb = (U - 1 + (k - 1) - 1) // (k - 1)  # ceil((U-1)/(k-1))
            m_out = int(out_lines[case])
            assert m_out >= lb, f"For test case {case+1}: U={U}, k={k}, lower bound={lb}, but output m={m_out}"

def test_answer_bounds(run, x):
    data = x.strip().split()
    if not data:
        return
    t = int(data[0])
    idx = 1
    out_lines = run(x).strip().split()
    for case in range(t):
