def test_specific_counterexample(run, x):
    if x == "1\n4 2\n0 1 2 3\n":
        out = run(x).strip()
        assert out == "3", f"For input #5, expected 3, got {out}"

def test_distinct_values_consistency(run, x):
    data = x.strip().split()
    if not data:
        return
    t = int(data[0])
    idx = 1
    out_lines = run(x).strip().split()
    groups = {}
    for case in range(t):
        n = int(data[idx]); k = int(data[idx+1])
        idx += 2
        a = list(map(int, data[idx:idx+n]))
        idx += n
        key = (k, frozenset(a))
        if key in groups:
            prev_case, prev_out = groups[key]
            assert out_lines[case] == prev_out, f"Test cases {prev_case+1} and {case+1} have same k and distinct values but different outputs: {prev_out} vs {out_lines[case]}"
        else:
            groups[key] = (case, out_lines[case])

def test_examples_from_statement(run, x):
    example_input = "6\n4 1\n0 0 0 1\n3 1\n3 3 3\n11 3\n0 1 2 2 3 3 3 4 4 4 4\n5 3\n1 2 3 4 5\n9 4\n2 2 3 5 7 11 13 13 17\n10 7\n0 1 1 2 3 3 4 5 5 6\n"
    if x == example_input:
        expected_output = "-1\n1\n2\n2\n2\n1\n"
        out = run(x)
        assert out.strip() == expected_output.strip(), f"Example input mismatch. Expected:\n{expected_output}\nGot:\n{out}"

def test_small_brute_force(run, x):
    out = run(x).strip().split()
    data = x.strip().split()
    if not data:
        return
    t = int(data[0])
    idx = 1
    for case in range(t):
        n = int(data[idx]); k = int(data[idx+1])
        idx += 2
        a = list(map(int, data[idx:idx+n]))
        idx += n
        if n > 4 or max(a) > 3:
            continue
        U = len(set(a))
        if k == 1:
            expected = -1 if U > 1 else 1
        else:
            import itertools
            candidates = []
            def dfs(pos, prev, current):
                if pos == n:
                    candidates.append(tuple(current))
                    return
                for val in range(prev, a[pos]+1):
                    current.append(val)
                    dfs(pos+1, val, current)
                    current.pop()
            dfs(0, 0, [])
            found = False
            for m in range(1, a[-1]+1):
                for combo in itertools.product(candidates, repeat=m):
                    sum_arr = [0]*n
                    for b in combo:
                        for j in range(n):
                            sum_arr[j] += b[j]
                    if sum_arr == a:
                        ok = True
                        for b in combo:
                            if len(set(b)) > k:
                                ok = False
                                break
                        if ok:
                            expected = m
                            found = True
                            break
                if found:
                    break
            if not found:
                expected = -1
        out_val = out[case]
        if out_val == '-1':
            assert expected == -1, f"Case {case+1}: expected {expected}, got -1"
        else:
            assert int(out_val) == expected, f"Case {case+1}: expected {expected}, got {out_val}"

def test_U_le_k_output_one(run, x):
    out = run(x).strip().split()
    data = x.strip().split()
    if not data:
        return
    t = int(data[0])
    idx = 1
    for case in range(t):
        n = int(data[idx]); k = int(data[idx+1])
        idx += 2
        a = list(map(int, data[idx:idx+n]))
        idx += n
        if k > 1:
            U = len(set(a))
            if U <= k:
                assert out[case] == '1', f"Case {case+1}: U={U}, k={k}, expected 1, got {out[case]}"

