def test_decision(run, x):
    lines = x.strip().splitlines()
    if not lines:
        return
    n = int(lines[0])
    board = lines[1:1+n]
    if len(board) < n:
        return
    pieces = []
    dots = []
    x_cells = []
    for i in range(n):
        row = board[i]
        if len(row) < n:
            row = row.ljust(n, '.')
        for j in range(n):
            c = row[j]
            if c == 'o':
                pieces.append((i,j))
            elif c == '.':
                dots.append((i,j))
            elif c == 'x':
                x_cells.append((i,j))
    if not pieces:
        expected_yes = len(x_cells) == 0
    else:
        size = 2*n - 1
        offset = n - 1
        allowed = [[True]*size for _ in range(size)]
        for pi, pj in pieces:
            for di, dj in dots:
                dx = di - pi
                dy = dj - pj
                idx = dx + offset
                idy = dy + offset
                if 0 <= idx < size and 0 <= idy < size:
                    allowed[idx][idy] = False
        expected_yes = True
        for xi, xj in x_cells:
            attacked = False
            for pi, pj in pieces:
                dx = xi - pi
                dy = xj - pj
                idx = dx + offset
                idy = dy + offset
                if 0 <= idx < size and 0 <= idy < size and allowed[idx][idy]:
                    attacked = True
                    break
            if not attacked:
                expected_yes = False
                break
    output = run(x)
    out_lines = output.strip().splitlines()
    if not out_lines:
        assert False, "Empty output"
    first = out_lines[0].strip()
    if expected_yes:
        assert first == 'YES', f'Expected YES, got {first}'
    else:
        assert first == 'NO', f'Expected NO, got {first}'

