def test_format(run, x):
    out = run(x)
    assert out in ("Yes\n", "No\n"), f"Invalid output: {repr(out)}"

def test_all_zero_no(run, x):
    out = run(x)
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n = int(lines[0])
    grid = lines[1:]
    if all(c == '0' for row in grid for c in row):
        assert out == "No\n", f"All-zero grid should output No, got {repr(out)}"

def test_all_four_yes(run, x):
    out = run(x)
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n = int(lines[0])
    grid = lines[1:]
    if all(c == '4' for row in grid for c in row):
        assert out == "Yes\n", f"All-four grid should output Yes, got {repr(out)}"

def test_yes_requires_four(run, x):
    out = run(x)
    if out == "Yes\n":
        lines = x.strip().splitlines()
        if len(lines) < 2:
            return
        grid = lines[1:]
        if not any('4' in row for row in grid):
            assert False, "Output Yes but grid contains no '4'"

def test_yes_4_rectangle(run, x):
    out = run(x)
    if out == "Yes\n":
        lines = x.strip().splitlines()
        if len(lines) < 2:
            return
        n = int(lines[0])
        grid = [list(row) for row in lines[1:]]
        xs = []
        ys = []
        for y in range(n):
            for x in range(n):
                if grid[y][x] == '4':
                    xs.append(x)
                    ys.append(y)
        if not xs:
            assert False, "Yes but no 4's"
        xmin, xmax = min(xs), max(xs)
        ymin, ymax = min(ys), max(ys)
        for y in range(ymin, ymax+1):
            for x in range(xmin, xmax+1):
                if grid[y][x] != '4':
                    assert False, f"Yes but cell ({x},{y}) in 4 bounding box is not 4"

