    m = int(next(it))
    polyB = [tuple(map(float, next(it).split())) for _ in range(m)]
    def sub(u, v):
        return (u[0]-v[0], u[1]-v[1], u[2]-v[2])
    def cross(u, v):
        return (u[1]*v[2]-u[2]*v[1], u[2]*v[0]-u[0]*v[2], u[0]*v[1]-u[1]*v[0])
    def dot(u, v):
        return u[0]*v[0] + u[1]*v[1] + u[2]*v[2]
    def normalize(v):
        nrm = math.sqrt(v[0]*v[0] + v[1]*v[1] + v[2]*v[2])
        if nrm < 1e-12:
            return v
        return (v[0]/nrm, v[1]/nrm, v[2]/nrm)
    def polygon_plane(poly):
        a, b, c = poly[0], poly[1], poly[2]
        n = cross(sub(b, a), sub(c, b))
        return n, a
    def point_in_polygon_2d(pt, poly):
        x, y = pt
        inside = False
        for i in range(len(poly)):
            x1, y1 = poly[i]
            x2, y2 = poly[(i+1)%len(poly)]
            if ((y1 > y) != (y2 > y)) and (x < (x2-x1)*(y-y1)/(y2-y1) + x1):
                inside = not inside
        return inside
    def count_crossings(P, Q_norm, Q_pt, Q_vertices):
        nrm = Q_norm
        if abs(nrm[0]) > abs(nrm[1]) and abs(nrm[0]) > abs(nrm[2]):
            u = (0,1,0)
        else:
            u = (1,0,0)
        u = cross(nrm, u)
        if dot(u, u) < 1e-12:
            u = cross(nrm, (0,0,1))
        u = normalize(u)
        v = cross(nrm, u)
        v = normalize(v)
        def proj(p):
            return (dot(p, u), dot(p, v))
        Q2d = [proj(q) for q in Q_vertices]
        up_down = 0
        down_up = 0
        for i in range(len(P)):
            a = P[i]
            b = P[(i+1)%len(P)]
            da = dot(sub(a, Q_pt), nrm)
            db = dot(sub(b, Q_pt), nrm)
            if da*db > 0:
                continue
            if abs(da) < 1e-9 or abs(db) < 1e-9:
                continue
            t = -da / (db - da)
            inter = (a[0]+t*(b[0]-a[0]), a[1]+t*(b[1]-a[1]), a[2]+t*(b[2]-a[2]))
            inter2d = proj(inter)
            if not point_in_polygon_2d(inter2d, Q2d):
                continue
            if da > 0 and db < 0:
                up_down += 1
            elif da < 0 and db > 0:
                down_up += 1
        return up_down, down_up
    nA, ptA = polygon_plane(polyA)
    nB, ptB = polygon_plane(polyB)
    upA, downA = count_crossings(polyB, nA, ptA, polyA)
    upB, downB = count_crossings(polyA, nB, ptB, polyB)
    correct = (upA != downA) or (upB != downB)
    expected = 'YES' if correct else 'NO'
    output = run(x).strip()
    assert output == expected, f'Expected {expected}, got {output}'

def test_output_is_yes_or_no(run, x):
    out = run(x).strip()
    assert out in ('YES', 'NO'), f'Output must be YES or NO, got {out}'

def test_all_z_zero_implies_no(run, x):
    lines = x.strip().split('\n')
    it = iter(lines)
    n = int(next(it))
    polyA = [tuple(map(float, next(it).split())) for _ in range(n)]
    m = int(next(it))
    polyB = [tuple(map(float, next(it).split())) for _ in range(m)]
    if all(abs(p[2]) < 1e-9 for p in polyA) and all(abs(p[2]) < 1e-9 for p in polyB):
        out = run(x).strip()
        assert out == 'NO', f'Both polygons in z=0 plane, expected NO, got {out}'

def test_no_extra_whitespace(run, x):
    out = run(x)
    out_no_trailing_nl = out.rstrip('\n')
    assert out_no_trailing_nl.strip() == out_no_trailing_nl, 'Extra whitespace besides newline'
    assert '\t' not in out and '\r' not in out

def test_output_length(run, x):
    out = run(x).strip()
    assert len(out) in (2, 3), f'Output length unexpected: {out}'

def test_output_uppercase(run, x):
    out = run(x).strip()
    assert out.isupper(), f'Output not uppercase: {out}'

def test_output_no_digits(run, x):
    out = run(x)
    assert not any(c.isdigit() for c in out), f'Output contains digits: {out}'

def test_single_line(run, x):
    out = run(x)
    lines = [ln for ln in out.split('\n') if ln.strip() != '']
    assert len(lines) == 1, f'Multiple non‑empty lines in output: {out}'

def test_output_not_empty(run, x):
    out = run(x)
    assert out.strip() != '', 'Output is empty or only whitespace'

def test_output_no_lowercase(run, x):
    out = run(x)
    assert out.upper() == out, f'Output contains lowercase letters: {out}'

