tests_src:
def test_format(run, x):
    out = run(x)
    lines = out.rstrip('\n').split('\n')
    assert len(lines) == 1, "Output should be exactly one line"
    ans = lines[0]
    if ans == '-':
        return
    assert ans.isalpha() and ans.islower(), "Output should be lowercase letters or '-'"

def test_subsequence_of_a(run, x):
    a, b = x.split('\n')[:2]
    out = run(x)
    ans = out.rstrip('\n')
    if ans == '-':
        return
    i = 0
    for ch in ans:
        while i < len(a) and a[i] != ch:
            i += 1
        if i == len(a):
            assert False, f"Output '{ans}' is not a subsequence of a='{a}'"
        i += 1

def test_subsequence_of_b(run, x):
    a, b = x.split('\n')[:2]
    out = run(x)
    ans = out.rstrip('\n')
    if ans == '-':
        return
    i = 0
    for ch in ans:
        while i < len(b) and b[i] != ch:
            i += 1
        if i == len(b):
            assert False, f"Output '{ans}' is not a subsequence of b='{b}'"
        i += 1

def test_consecutive_deletion(run, x):
    a, b = x.split('\n')[:2]
    out = run(x)
    ans = out.rstrip('\n')
    if ans == '-':
        return
    n = len(b)
    found = False
    for l in range(n + 1):
        for r in range(l, n + 1):
            if b[:l] + b[r:] == ans:
                found = True
                break
        if found:
            break
    assert found, f"Output '{ans}' cannot be obtained from b='{b}' by deleting a consecutive block"

def test_optimal_set(run, x):
    a, b = x.split('\n')[:2]
    out = run(x)
    ans = out.rstrip('\n')
    if len(a) * len(b) > 200:
        return
    n = len(b)
    optimal_strings = set()
    max_len = 0
    for l in range(n + 1):
        for r in range(l, n + 1):
            cand = b[:l] + b[r:]
            i = 0
            ok = True
            for ch in cand:
                while i < len(a) and a[i] != ch:
                    i += 1
                if i == len(a):
                    ok = False
                    break
                i += 1
            if ok:
                if len(cand) > max_len:
                    max_len = len(cand)
                    optimal_strings = {cand}
                elif len(cand) == max_len:
                    optimal_strings.add(cand)
    if max_len == 0:
        assert ans == '-', f"Maximum length is 0, but output is '{ans}'"
    else:
        assert ans != '-', f"Maximum length is {max_len}, but output is empty"
        assert ans in optimal_strings, f"Output '{ans}' is not among the optimal strings {optimal_strings}"

def test_empty_if_no_common(run, x):
    a, b = x.split('\n')[:2]
    out = run(x)
    ans = out.rstrip('\n')
    if not set(a) & set(b):
        assert ans == '-', f"No common characters, but output is '{ans}'"

def test_full_b_if_b_subsequence_of_a(run, x):
    a, b = x.split('\n')[:2]
    out = run(x)
    ans = out.rstrip('\n')
    i = 0
    for ch in b:
        while i < len(a) and a[i] != ch:
            i += 1
        if i == len(a):
            return
        i += 1
    assert ans == b, f"b='{b}' is a subsequence of a, but output is '{ans}'"

def test_output_length_bounds(run, x):
    a, b = x.split('\n')[:2]
    out = run(x)
    ans = out.rstrip('\n')
    if ans == '-':
        return
    assert len(ans) <= len(a), f"Output length {len(ans)} exceeds length of a ({len(a)})"
    assert len(ans) <= len(b), f"Output length {len(ans)} exceeds length of b ({len(b)})"

def test_examples(run, x):
    out = run(x)
    ans = out.rstrip('\n')
    examples = {
        "hi\nbob\n": "-",
        "abca\naccepted\n": "ac",
        "abacaba\nabcdcba\n": "abcba"
    }
    if x in examples:
        assert ans == examples[x], f"For example input, expected '{examples[x]}', got '{ans}'"

def test_output_chars_in_a(run, x):
    a, b = x.split('\n')[:2]
    out = run(x)
    ans = out.rstrip('\n')
    if ans == '-':
        return
    set_a = set(a)
    for ch in ans:
        assert ch in set_a, f"Character '{ch}' in output not in a"

