    pairs = []
    for i in range(1, k+1):
        s, t = map(int, lines[i].split())
        pairs.append((s, t))
    for i in range(1, len(pairs)):
        assert pairs[i][0] > pairs[i-1][0] or (pairs[i][0] == pairs[i-1][0] and pairs[i][1] > pairs[i-1][1]), "pairs not sorted correctly"


