tests_src:
def test_formula(run, x):
    parts = x.strip().split()
    if not parts:
        return
    n = int(parts[0])
    a = list(map(int, parts[1:]))
    from collections import Counter
    freq = Counter(a)
    maxf = max(freq.values())
    expected = n - maxf
    out = int(run(x).strip())
    assert out == expected

def test_brute_small(run, x):
    parts = x.strip().split()
    if not parts:
        return
    n = int(parts[0])
    if n > 8:
        return
    a = list(map(int, parts[1:]))
    import itertools
    perms = set(itertools.permutations(a))
    best = 0
    for perm in perms:
        happy = sum(1 for i in range(n-1) if perm[i] < perm[i+1])
        if happy > best:
            best = happy
    out = int(run(x).strip())
    assert out == best

def test_bounds(run, x):
    parts = x.strip().split()
    if not parts:
        return
    n = int(parts[0])
    out = int(run(x).strip())
    assert 0 <= out <= n-1

def test_all_equal(run, x):
    parts = x.strip().split()
    if not parts:
        return
    n = int(parts[0])
    a = list(map(int, parts[1:]))
    if len(set(a)) == 1:
        out = int(run(x).strip())
        assert out == 0

def test_all_distinct(run, x):
    parts = x.strip().split()
    if not parts:
        return
    n = int(parts[0])
    a = list(map(int, parts[1:]))
    if len(set(a)) == n:
        out = int(run(x).strip())
        assert out == n-1

def test_examples(run, x):
    examples = {
        "5\n20 30 10 50 40\n": 4,
        "4\n200 100 100 200\n": 2,
    }
    if x in examples:
        out = int(run(x).strip())
        assert out == examples[x]

def test_tricky(run, x):
    tricky = {
        "3\n1 2 2\n": 1,
        "5\n1000 1 1 1 1\n": 1,
        "3\n5 5 6\n": 1,
        "6\n1 2 2 2 2 2\n": 1,
        "2\n5 5\n": 0,
        "2\n10 20\n": 1,
        "1\n5\n": 0,
        "4\n1 2 2 3\n": 2,
        "3\n7 7 7\n": 0,
        "5\n1 2 3 4 5\n": 4,
    }
    if x in tricky:
        out = int(run(x).strip())
        assert out == tricky[x]

def test_n1(run, x):
    parts = x.strip().split()
    if not parts:
        return
    n = int(parts[0])
    if n == 1:
        out = int(run(x).strip())
        assert out == 0

def test_two_equal(run, x):
    parts = x.strip().split()
    if not parts:
        return
    n = int(parts[0])
    if n == 2:
        a = list(map(int, parts[1:]))
        if a[0] == a[1]:
            out = int(run(x).strip())
            assert out == 0

def test_two_distinct(run, x):
    parts = x.strip().split()
    if not parts:
        return
    n = int(parts[0])
    if n == 2:
        a = list(map(int, parts[1:]))
        if a[0] != a[1]:
            out = int(run(x).strip())
            assert out == 1

