def test_exact_bfs_small(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    first = lines[0].split()
    if len(first) != 4:
        return
    try:
        x0, y0, x1, y1 = map(int, first)
    except:
        return
    if x0 == x1 and y0 == y1:
        return
    try:
        n = int(lines[1])
    except:
        return
    if len(lines) < 2 + n:
        return
    segments = []
    total_cells = 0
    row_intervals = {}
    for i in range(n):
        parts = lines[2+i].split()
        if len(parts) != 3:
            return
        r, a, b = map(int, parts)
        if a > b:
            return
        segments.append((r, a, b))
        total_cells += b - a + 1
        row_intervals.setdefault(r, []).append((a, b))
    def cell_allowed(r, c):
        if r not in row_intervals:
            return False
        for a, b in row_intervals[r]:
            if a <= c <= b:
                return True
        return False
    if not cell_allowed(x0, y0) or not cell_allowed(x1, y1):
        return
    if total_cells > 100000:
        return
    allowed = set()
    for r, a, b in segments:
        for col in range(a, b+1):
            allowed.add((r, col))
    from collections import deque
    dist = {}
    start = (x0, y0)
    end = (x1, y1)
    q = deque()
    dist[start] = 0
    q.append(start)
    dx = [-1,0,1,-1,1,-1,0,1]
    dy = [0,-1,0,-1,-1,1,1,1]
    while q:
        cx, cy = q.popleft()
        d = dist[(cx, cy)]
        if (cx, cy) == end:
            break
        for k in range(8):
            nx, ny = cx + dx[k], cy + dy[k]
            if (nx, ny) in allowed and (nx, ny) not in dist:
                dist[(nx, ny)] = d + 1
                q.append((nx, ny))
    correct = dist.get(end, -1)
    out = run(x)
    out_val = out.strip()
    if out_val == '':
        assert False, "empty output"
    try:
        out_int = int(out_val)
    except:
        assert False, "output not integer"
    assert out_int == correct, f"expected {correct}, got {out_int}"

