def test_same_row_continuous(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    first = lines[0].split()
    if len(first) != 4:
        return
    try:
        x0, y0, x1, y1 = map(int, first)
    except:
        return
    if x0 != x1:
        return
    if y0 == y1:
        return
    ymin = min(y0, y1)
    ymax = max(y0, y1)
    try:
        n = int(lines[1])
    except:
        return
    if len(lines) < 2 + n:
        return
    intervals = []
    row_intervals = {}
    for i in range(n):
        parts = lines[2+i].split()
        if len(parts) != 3:
            return
        r, a, b = map(int, parts)
        if a > b:
            return
        row_intervals.setdefault(r, []).append((a, b))
        if r == x0:
            intervals.append((a, b))
    def cell_allowed(r, c):
        if r not in row_intervals:
            return False
        for a, b in row_intervals[r]:
            if a <= c <= b:
                return True
        return False
    if not cell_allowed(x0, y0) or not cell_allowed(x1, y1):
        return
    if not intervals:
        return
    intervals.sort()
    merged = []
    cur_a, cur_b = intervals[0]
    for a, b in intervals[1:]:
        if a <= cur_b + 1:
            cur_b = max(cur_b, b)
        else:
            merged.append((cur_a, cur_b))
            cur_a, cur_b = a, b
    merged.append((cur_a, cur_b))
    covered = False
    for a, b in merged:
        if a <= ymin and b >= ymax:
            covered = True
            break
    if covered:
        out = run(x)
        s = out.strip()
        try:
            out_int = int(s)
        except:
            assert False, "output not integer"
        expected = abs(y1 - y0)
        assert out_int == expected, f"continuous row path should give {expected}, got {out_int}"

