    except:
        return
    if y0 != y1:
        return
    if x0 == x1:
        return
    r1 = min(x0, x1)
    r2 = max(x0, x1)
    try:
        n = int(lines[1])
    except:
        return
    if len(lines) < 2 + n:
        return
    rows_set = set()
    row_intervals = {}
    for i in range(n):
        parts = lines[2+i].split()
        if len(parts) != 3:
            return
        r, a, b = map(int, parts)
        if a > b:
            return
        row_intervals.setdefault(r, []).append((a, b))
        if a <= y0 <= b:
            rows_set.add(r)
    def cell_allowed(r, c):
        if r not in row_intervals:
            return False
        for a, b in row_intervals[r]:
            if a <= c <= b:
                return True
        return False
