    except:
        return
    if not (1 <= n <= 100000 and 1 <= c <= 10**9):
        return
    second = lines[1].split()
    if len(second) != n:
        return
    try:
        t = list(map(int, second))
    except:
        return
    if not (1 <= t[0] and all(t[i-1] < t[i] for i in range(1, n)) and t[-1] <= 10**9):
        return
    cnt = 1
    for i in range(1, n):
        if t[i] - t[i-1] > c:
            cnt = 1
        else:
            cnt += 1
    assert ans == cnt, f"Direct oracle: expected {cnt}, got {ans}"


