tests_src:
def test_bruteforce_small(run, x):
    a, k = x.strip().split()
    k = int(k)
    n = len(a)
    total = n * k
    if total > 12:
        return
    s = a * k
    MOD = 10**9 + 7
    count = 0
    for mask in range(1, 1 << total):
        max_idx = -1
        for i in range(total):
            if mask & (1 << i):
                max_idx = i
        if s[max_idx] in '05':
            count += 1
    count %= MOD
    out = run(x).strip()
    assert int(out) == count

def test_no_eligible_digit(run, x):
    a, k = x.strip().split()
    if not any(c in '05' for c in a):
        out = run(x).strip()
        assert out == '0'

def test_all_eligible_digit(run, x):
    a, k = x.strip().split()
    k = int(k)
    n = len(a)
    if all(c in '05' for c in a):
        MOD = 10**9 + 7
        expected = (pow(2, n * k, MOD) - 1) % MOD
        out = run(x).strip()
        assert int(out) == expected

def test_k1(run, x):
    a, k = x.strip().split()
    k = int(k)
    if k == 1:
        MOD = 10**9 + 7
        n = len(a)
        s = 0
        for i, c in enumerate(a):
            if c in '05':
                s = (s + pow(2, i, MOD)) % MOD
        out = run(x).strip()
        assert int(out) == s

def test_k2(run, x):
    a, k = x.strip().split()
    k = int(k)
    if k == 2:
        MOD = 10**9 + 7
        n = len(a)
        s = 0
        for i, c in enumerate(a):
            if c in '05':
                s = (s + pow(2, i, MOD)) % MOD
        expected = (1 + pow(2, n, MOD)) * s % MOD
        out = run(x).strip()
        assert int(out) == expected

def test_k3(run, x):
    a, k = x.strip().split()
    k = int(k)
    if k == 3:
        MOD = 10**9 + 7
        n = len(a)
        s = 0
        for i, c in enumerate(a):
            if c in '05':
                s = (s + pow(2, i, MOD)) % MOD
        expected = (1 + pow(2, n, MOD) + pow(2, 2 * n, MOD)) * s % MOD
        out = run(x).strip()
        assert int(out) == expected

def test_output_format(run, x):
    out = run(x).strip()
    val = int(out)
    MOD = 10**9 + 7
    assert 0 <= val < MOD

def test_examples(run, x):
    if x == "1256\n1\n":
        expected = "4"
    elif x == "13990\n2\n":
        expected = "528"
    elif x == "555\n2\n":
        expected = "63"
    else:
        return
    out = run(x).strip()
    assert out == expected

def test_single_digit_0(run, x):
    a, k = x.strip().split()
    k = int(k)
    if a == "0":
        MOD = 10**9 + 7
        expected = (pow(2, k, MOD) - 1) % MOD
        out = run(x).strip()
        assert int(out) == expected

def test_single_digit_5(run, x):
    a, k = x.strip().split()
    k = int(k)
    if a == "5":
        MOD = 10**9 + 7
        expected = (pow(2, k, MOD) - 1) % MOD
        out = run(x).strip()
        assert int(out) == expected

def test_output_range(run, x):
    out = run(x).strip()
    ans = int(out)
    assert 0 <= ans < 512

def test_lower_bound(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    L = 0
    for ai in a:
        and_all = (1 << 9) - 1
        for bj in b:
            and_all &= (ai & bj)
        L |= and_all
    ans = int(run(x).strip())
    assert ans >= L

def test_upper_bound_min_j(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    best = None
    for bj in b:
        cur = 0
        for ai in a:
            cur |= (ai & bj)
        if best is None or cur < best:
            best = cur
    ans = int(run(x).strip())
    assert ans <= best

def test_upper_bound_min_per_i(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    U = 0
    for ai in a:
        min_val = min(ai & bj for bj in b)
        U |= min_val
    ans = int(run(x).strip())
    assert ans <= U

def test_upper_bound_and_of_or(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    or_a = 0
    for ai in a:
        or_a |= ai
    or_b = 0
    for bj in b:
        or_b |= bj
    U = or_a & or_b
    ans = int(run(x).strip())
    assert ans <= U

def test_feasibility(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    ans = int(run(x).strip())
    for ai in a:
        ok = False
        for bj in b:
            if ((ai & bj) & ~ans) == 0:
                ok = True
                break
        assert ok, f"No feasible choice for a={ai}"

def test_minimal_bit_removal(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    ans = int(run(x).strip())
    def feasible(cand):
        for ai in a:
            ok = False
            for bj in b:
                if ((ai & bj) & ~cand) == 0:
                    ok = True
                    break
            if not ok:
                return False
        return True
    for k in range(9):
        if ans & (1 << k):
            cand = ans ^ (1 << k)
            assert not feasible(cand), f"Bit {k} removable"

def test_minimal_all_smaller(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    ans = int(run(x).strip())
    def feasible(cand):
        for ai in a:
            ok = False
            for bj in b:
                if ((ai & bj) & ~cand) == 0:
                    ok = True
                    break
            if not ok:
                return False
        return True
    for k in range(ans):
        assert not feasible(k), f"Smaller candidate {k} feasible"

def test_brute_force(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    from itertools import product
    min_or = None
    for choice in product(range(m), repeat=n):
        cur = 0
        for i in range(n):
            cur |= (a[i] & b[choice[i]])
        if min_or is None or cur < min_or:
            min_or = cur
    ans = int(run(x).strip())
    assert ans == min_or

def test_zero_feasibility(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    zero_feasible = True
    for ai in a:
        ok = False
        for bj in b:
            if (ai & bj) == 0:
                ok = True
                break
        if not ok:
            zero_feasible = False
            break
    ans = int(run(x).strip())
    if zero_feasible:
        assert ans == 0, "Zero feasible so answer must be 0"

