def test_small_brute_force(run, x):
    N, M = map(int, x.strip().split())
    if N <= 20 and M <= 20:
        counts = [[0]*M for _ in range(N)]
        for i in range(N):
            for j in range(M):
                for di in (-1,0,1):
                    for dj in (-1,0,1):
                        ni, nj = i+di, j+dj
                        if 0 <= ni < N and 0 <= nj < M:
                            counts[ni][nj] += 1
        odd = sum(1 for i in range(N) for j in range(M) if counts[i][j] % 2 == 1)
        ans = int(run(x).strip())
        assert ans == odd, f"Brute force says {odd}, got {ans}"

def test_non_negative(run, x):
    ans = int(run(x).strip())
    assert ans >= 0, f"Negative answer {ans}"

def test_general_formula(run, x):
    N, M = map(int, x.strip().split())
    if N >= 2 and M >= 2:
        expected = (N-2)*(M-2)
        ans = int(run(x).strip())
        assert ans == expected, f"For N,M>=2 expected {expected}, got {ans}"

def test_N1_M_gt1(run, x):
    N, M = map(int, x.strip().split())
    if N == 1 and M > 1:
        expected = M - 2
        ans = int(run(x).strip())
        assert ans == expected, f"For N=1, M>1 expected {expected}, got {ans}"

def test_M1_N_gt1(run, x):
    N, M = map(int, x.strip().split())
    if M == 1 and N > 1:
        expected = N - 2
        ans = int(run(x).strip())
        assert ans == expected, f"For M=1, N>1 expected {expected}, got {ans}"

def test_N1_M1(run, x):
    N, M = map(int, x.strip().split())
    if N == 1 and M == 1:
        ans = int(run(x).strip())
        assert ans == 1, f"For 1x1 expected 1, got {ans}"

def test_N2_M_ge2(run, x):
    N, M = map(int, x.strip().split())
    if N == 2 and M >= 2:
        ans = int(run(x).strip())
        assert ans == 0, f"For N=2, M>=2 expected 0, got {ans}"

def test_M2_N_ge2(run, x):
    N, M = map(int, x.strip().split())
    if M == 2 and N >= 2:
        ans = int(run(x).strip())
        assert ans == 0, f"For M=2, N>=2 expected 0, got {ans}"

def test_N3_M3(run, x):
    N, M = map(int, x.strip().split())
    if N == 3 and M == 3:
        ans = int(run(x).strip())
        assert ans == 1, f"For 3x3 expected 1, got {ans}"

def test_upper_bound(run, x):
    N, M = map(int, x.strip().split())
    ans = int(run(x).strip())
    assert ans <= N * M, f"Answer {ans} exceeds total cards {N*M}"

