def test_bruteforce_small(run, x):
    N, M = map(int, x.strip().split())
    if N <= 10 and M <= 10:
        grid = [[0]*M for _ in range(N)]
        for i in range(N):
            for j in range(M):
                for di in (-1,0,1):
                    for dj in (-1,0,1):
                        ni, nj = i+di, j+dj
                        if 0 <= ni < N and 0 <= nj < M:
                            grid[ni][nj] ^= 1
        expected = sum(sum(row) for row in grid)
        out = run(x).strip()
        ans = int(out)
        assert ans == expected

def test_nonnegative(run, x):
    out = run(x).strip()
    ans = int(out)
    assert ans >= 0

def test_upper_bound(run, x):
    N, M = map(int, x.strip().split())
    out = run(x).strip()
    ans = int(out)
    assert ans <= N * M

def test_parity(run, x):
    N, M = map(int, x.strip().split())
    if N == 1:
        if M == 1:
            exp_par = 1
        else:
            exp_par = (M - 2) & 1
    elif M == 1:
        if N == 1:
            exp_par = 1
        else:
            exp_par = (N - 2) & 1
    elif N == 2 or M == 2:
        exp_par = 0
    else:
        exp_par = ((N-2)*(M-2)) & 1
    out = run(x).strip()
    ans = int(out)
    assert (ans & 1) == exp_par

def test_N_eq_1(run, x):
    N, M = map(int, x.strip().split())
    if N == 1:
        out = run(x).strip()
        ans = int(out)
        if M == 1:
            assert ans == 1
        else:
            assert ans == max(0, M-2)

def test_M_eq_1(run, x):
    N, M = map(int, x.strip().split())
    if M == 1:
        out = run(x).strip()
        ans = int(out)
        if N == 1:
            assert ans == 1
        else:
            assert ans == max(0, N-2)

def test_N_eq_2(run, x):
    N, M = map(int, x.strip().split())
    if N == 2:
        out = run(x).strip()
        ans = int(out)
        assert ans == 0

def test_M_eq_2(run, x):
    N, M = map(int, x.strip().split())
    if M == 2:
        out = run(x).strip()
        ans = int(out)
        assert ans == 0

def test_both_large(run, x):
    N, M = map(int, x.strip().split())
    if N >= 3 and M >= 3:
        out = run(x).strip()
        ans = int(out)
        expected = (N-2)*(M-2)
        assert ans == expected

def test_output_format(run, x):
    out_raw = run(x)
    assert out_raw.endswith('\n'), 'Output must end with newline'
    out = out_raw.rstrip('\n')
    assert out.strip() == out, 'Output contains extra whitespace'
    ans = int(out)
    assert out == str(ans), 'Output format mismatch'

