tests_src:
def test_format(run, x):
    output = run(x)
    stripped = output.rstrip('\n')
    assert stripped in ["Happy Alex", "Poor Alex"], f"Unexpected output: {repr(output)}"
    assert output == stripped + '\n', f"Extra characters after newline or missing newline: {repr(output)}"


def test_brute_force(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    pairs = [tuple(map(int, line.split())) for line in lines[1:1+n]]
    has_inv = False
    for i in range(n):
        for j in range(n):
            if i != j:
                if pairs[i][0] < pairs[j][0] and pairs[i][1] > pairs[j][1]:
                    has_inv = True
                    break
        if has_inv:
            break
    expected = "Happy Alex" if has_inv else "Poor Alex"
    output = run(x).strip()
    assert output == expected, f"Expected {expected}, got {output}"


def test_n1_poor_alex(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    if n == 1:
        output = run(x).strip()
        assert output == "Poor Alex", f"For n=1, expected Poor Alex, got {output}"


def test_happy_implies_inversion(run, x):
    output = run(x).strip()
    if output == "Happy Alex":
        lines = x.strip().splitlines()
        n = int(lines[0])
        pairs = [tuple(map(int, line.split())) for line in lines[1:1+n]]
        has_inv = False
        for i in range(n):
            for j in range(n):
                if i != j:
                    if pairs[i][0] < pairs[j][0] and pairs[i][1] > pairs[j][1]:
                        has_inv = True
                        break
            if has_inv:
                break
        assert has_inv, f"Output is Happy Alex but no inversion found"


def test_poor_implies_no_inversion(run, x):
    output = run(x).strip()
    if output == "Poor Alex":
        lines = x.strip().splitlines()
        n = int(lines[0])
        pairs = [tuple(map(int, line.split())) for line in lines[1:1+n]]
        has_inv = False
        for i in range(n):
            for j in range(n):
                if i != j:
                    if pairs[i][0] < pairs[j][0] and pairs[i][1] > pairs[j][1]:
                        has_inv = True
                        break
            if has_inv:
                break
        assert not has_inv, f"Output is Poor Alex but an inversion exists"


def test_adjacent_inversion_implies_happy(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    pairs = [tuple(map(int, line.split())) for line in lines[1:1+n]]
    sorted_pairs = sorted(pairs, key=lambda p: p[0])
    has_adj_inv = any(sorted_pairs[i][1] > sorted_pairs[i+1][1] for i in range(n-1))
    if has_adj_inv:
        output = run(x).strip()
        assert output == "Happy Alex", f"Adjacent inversion exists, expected Happy Alex, got {output}"


def test_no_adjacent_inversion_implies_poor(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    pairs = [tuple(map(int, line.split())) for line in lines[1:1+n]]
    sorted_pairs = sorted(pairs, key=lambda p: p[0])
    strictly_increasing = all(sorted_pairs[i][1] < sorted_pairs[i+1][1] for i in range(n-1))
    if strictly_increasing:
        output = run(x).strip()
        assert output == "Poor Alex", f"No adjacent inversion (strictly increasing qualities), expected Poor Alex, got {output}"


def test_n2_correct(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    if n == 2:
        pairs = [tuple(map(int, line.split())) for line in lines[1:1+n]]
        (a1,b1), (a2,b2) = pairs
        has_inv = (a1 < a2 and b1 > b2) or (a2 < a1 and b2 > b1)
        expected = "Happy Alex" if has_inv else "Poor Alex"
        output = run(x).strip()
        assert output == expected, f"For n=2, expected {expected}, got {output}"


def test_single_newline(run, x):
    output = run(x)
    assert output.endswith('\n'), "Output does not end with newline"
    assert output.count('\n') == 1, "Output contains more than one newline"


def test_sorted_inversion(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    pairs = [tuple(map(int, line.split())) for line in lines[1:1+n]]
    sorted_pairs = sorted(pairs, key=lambda p: p[0])
    qualities = [b for (a,b) in sorted_pairs]
    strictly_increasing = all(qualities[i] < qualities[i+1] for i in range(n-1))
    expected = "Happy Alex" if not strictly_increasing else "Poor Alex"
    output = run(x).strip()
    assert output == expected, f"Expected {expected}, got {output}"

