def test_bounds(run, x):
    out = run(x)
    ans = int(out.strip())
    lines = x.strip().split('\n')
    n = int(lines[0].split()[0])
    assert 1 <= ans <= n

def test_output_format(run, x):
    out = run(x)
    assert out.endswith('\n'), 'output must end with newline'
    s = out.strip()
    assert s.isdigit() or (s[0] == '-' and s[1:].isdigit()), 'output must be an integer'

def test_example(run, x):
    if x == "4 3\n1 4 2 3\n4 1 2 3\n1 2 4 3\n":
        out = run(x)
        ans = int(out.strip())
        assert ans == 3, 'example from statement must give 3'

def test_identical(run, x):
    lines = x.strip().split('\n')
    nk = list(map(int, lines[0].split()))
    n, k = nk[0], nk[1]
    perms = [list(map(int, lines[i+1].split())) for i in range(k)]
    if all(perms[i] == perms[0] for i in range(1, k)):
        out = run(x)
        ans = int(out.strip())
        assert ans == n, 'all permutations identical => LCS = n'

def test_reverse_pair(run, x):
    lines = x.strip().split('\n')
    nk = list(map(int, lines[0].split()))
    n, k = nk[0], nk[1]
    if k == 2:
        perm1 = list(map(int, lines[1].split()))
        perm2 = list(map(int, lines[2].split()))
        if perm2 == perm1[::-1]:
            out = run(x)
            ans = int(out.strip())
            assert ans == 1, 'two reverse permutations => LCS = 1'

def test_pairwise_upper_bound(run, x):
    import bisect
    def lis_of_perm(p1, p2):
        pos = {v: i for i, v in enumerate(p2)}
        seq = [pos[v] for v in p1]
        tails = []
        for num in seq:
            idx = bisect.bisect_left(tails, num)
            if idx == len(tails):
                tails.append(num)
            else:
                tails[idx] = num
        return len(tails)
    lines = x.strip().split('\n')
    nk = list(map(int, lines[0].split()))
    n, k = nk[0], nk[1]
    perms = [list(map(int, lines[i+1].split())) for i in range(k)]
    # validate each permutation to avoid errors on malformed input
    for perm in perms:
        if len(perm) != n:
            return
        if set(perm) != set(range(1, n+1)):
            return
    min_pair_lcs = n
    for i in range(k):
        for j in range(i+1, k):
            lcs_ij = lis_of_perm(perms[i], perms[j])
            if lcs_ij < min_pair_lcs:
                min_pair_lcs = lcs_ij
    out = run(x)
    ans = int(out.strip())
    assert ans <= min_pair_lcs, 'LCS of all permutations cannot exceed LCS of any pair'

def test_small_brute(run, x):
    lines = x.strip().split('\n')
    nk = list(map(int, lines[0].split()))
    n, k = nk[0], nk[1]
    if n > 8:
        return
    perms = [list(map(int, lines[i+1].split())) for i in range(k)]
    best = 0
    for mask in range(1, 1 << n):
        subseqs = []
        for perm in perms:
            sub = [v for v in perm if (mask >> (v-1)) & 1]
            subseqs.append(tuple(sub))
        if all(subseqs[0] == s for s in subseqs[1:]):
            best = max(best, len(subseqs[0]))
    out = run(x)
    ans = int(out.strip())
    assert ans == best, f'brute force for n={n} gives {best}'

def test_partial_order_correct(run, x):
    lines = x.strip().split('\n')
    nk = list(map(int, lines[0].split()))
    n, k = nk[0], nk[1]
    perms = [list(map(int, lines[i+1].split())) for i in range(k)]
    pos = []
    for perm in perms:
        p = [0]*n
        for idx, val in enumerate(perm):
            p[val-1] = idx
        pos.append(p)
    succ = [[] for _ in range(n)]
    indeg = [0]*n
    for i in range(n):
        for j in range(n):
            if i == j:
                continue
            if all(pos[p][i] < pos[p][j] for p in range(k)):
                succ[i].append(j)
                indeg[j] += 1
    from collections import deque
    q = deque([i for i in range(n) if indeg[i] == 0])
    topo = []
    while q:
        u = q.popleft()
        topo.append(u)
        for v in succ[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                q.append(v)
    dp = [1]*n
    for u in reversed(topo):
        for v in succ[u]:
            if dp[u] < dp[v] + 1:
                dp[u] = dp[v] + 1
    correct = max(dp) if n>0 else 0
    out = run(x)
    ans = int(out.strip())
    assert ans == correct, f'partial order method gives {correct}'

def test_two_permutations_exact(run, x):
    import bisect
    lines = x.strip().split('\n')
    nk = list(map(int, lines[0].split()))
    n, k = nk[0], nk[1]
    if k != 2:
        return
    perms = [list(map(int, lines[i+1].split())) for i in range(k)]
    if len(perms[0]) != n or len(perms[1]) != n:
        return
    pos = {v: i for i, v in enumerate(perms[1])}
    seq = [pos[v] for v in perms[0]]
    tails = []
    for num in seq:
        idx = bisect.bisect_left(tails, num)
        if idx == len(tails):
            tails.append(num)
        else:
            tails[idx] = num
    expected = len(tails)
    out = run(x)
    ans = int(out.strip())
    assert ans == expected, f'for k=2, LCS must equal LIS of positions, expected {expected}'

def test_lower_bound_greedy(run, x):
    lines = x.strip().split('\n')
    nk = list(map(int, lines[0].split()))
    n, k = nk[0], nk[1]
    perms = [list(map(int, lines[i+1].split())) for i in range(k)]
    pos = []
    for perm in perms:
        p = [0]*n
        for idx, val in enumerate(perm):
            p[val-1] = idx
        pos.append(p)
    last_pos = [-1]*k
    length = 0
    for val in perms[0]:
        v = val-1
        if all(pos[p][v] > last_pos[p] for p in range(k)):
            length += 1
            for p in range(k):
                last_pos[p] = pos[p][v]
    out = run(x)
    ans = int(out.strip())
    assert ans >= length, f'greedy common subsequence of length {length} exists'

