def test_small_n_oracle(run, x):
    out = run(x).strip()
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    first = lines[0].split()
    if len(first) < 2:
        return
    try:
        n = int(first[0])
        m = int(first[1])
    except ValueError:
        return
    if n > 10:
        return
    if len(lines) < 2 + m:
        return
    s = lines[1].strip()
    adj = [[] for _ in range(n+1)]
    for i in range(m):
        uv = lines[2+i].split()
        if len(uv) < 2:
            return
        u = int(uv[0])
        v = int(uv[1])
        adj[u].append(v)
    import sys
    sys.setrecursionlimit(1000000)
    visited = [0] * (n+1)
    has_cycle = False
    def dfs_cycle(u):
        nonlocal has_cycle
        if has_cycle:
            return
        visited[u] = 1
        for v in adj[u]:
            if visited[v] == 0:
                dfs_cycle(v)
            elif visited[v] == 1:
                has_cycle = True
                return
        visited[u] = 2
    for i in range(1, n+1):
        if visited[i] == 0:
            dfs_cycle(i)
        if has_cycle:
            break
    if has_cycle:
        correct = -1
    else:
        rev_adj = [[] for _ in range(n+1)]
        for u in range(1, n+1):
            for v in adj[u]:
                rev_adj[v].append(u)
        indeg = [0] * (n+1)
        for u in range(1, n+1):
            for v in adj[u]:
                indeg[v] += 1
        from collections import deque
        q = deque([i for i in range(1, n+1) if indeg[i] == 0])
        topo = []
        while q:
            u = q.popleft()
            topo.append(u)
            for v in adj[u]:
                indeg[v] -= 1
                if indeg[v] == 0:
                    q.append(v)
        dp = [{} for _ in range(n+1)]
        ans = 0
        for u in topo:
            best = {}
            for v in rev_adj[u]:
                for letter, cnt in dp[v].items():
                    if cnt > best.get(letter, 0):
                        best[letter] = cnt
            letter = s[u-1]
            best[letter] = best.get(letter, 0) + 1
            dp[u] = best
            ans = max(ans, max(best.values()))
        correct = ans
    assert out == str(correct), f"Oracle computed answer {correct}, got {out}"

