def test_correct_small_n(run, x):
    lines = x.strip().split('\n')
    n_k = list(map(int, lines[0].split()))
    n, k = n_k[0], n_k[1]
    if n > 10:
        return
    perms = [list(map(int, line.split())) for line in lines[1:1+k]]
    pos = [ {val: idx for idx, val in enumerate(perm)} for perm in perms ]
    n = len(perms[0])
    rel = [[False]*n for _ in range(n)]
    for a in range(n):
        for b in range(n):
            if a == b:
                continue
            ok = True
            for p in pos:
                if p[a+1] >= p[b+1]:
                    ok = False
                    break
            if ok:
                rel[a][b] = True
    best = 0
    for mask in range(1, 1<<n):
        subset = [i for i in range(n) if mask & (1<<i)]
        ok = True
        for i in subset:
            for j in subset:
                if i != j and not (rel[i][j] or rel[j][i]):
                    ok = False
                    break
            if not ok:
                break
        if ok:
            best = max(best, len(subset))
    correct = best
    out = run(x).strip()
    assert out.isdigit()
    ans = int(out)
    assert ans == correct, f"Expected {correct}, got {ans}"

def test_output_range(run, x):
    lines = x.strip().split('\n')
    n_k = list(map(int, lines[0].split()))
    n, k = n_k[0], n_k[1]
    out = run(x).strip()
    assert out.isdigit()
    ans = int(out)
    assert 1 <= ans <= n

def test_identical_perms(run, x):
    lines = x.strip().split('\n')
    n_k = list(map(int, lines[0].split()))
    n, k = n_k[0], n_k[1]
    perms = [list(map(int, line.split())) for line in lines[1:1+k]]
    if all(perms[0] == p for p in perms[1:]):
        out = run(x).strip()
        assert out.isdigit()
        ans = int(out)
        assert ans == n

def test_single_element(run, x):
    lines = x.strip().split('\n')
    n_k = list(map(int, lines[0].split()))
    n, k = n_k[0], n_k[1]
    if n == 1:
        out = run(x).strip()
        assert out.isdigit()
        ans = int(out)
        assert ans == 1

def test_two_reverse(run, x):
    lines = x.strip().split('\n')
    n_k = list(map(int, lines[0].split()))
    n, k = n_k[0], n_k[1]
    if k == 2:
        perms = [list(map(int, line.split())) for line in lines[1:1+k]]
        p1, p2 = perms[0], perms[1]
        if p1 == list(reversed(p2)):
            out = run(x).strip()
            assert out.isdigit()
            ans = int(out)
            assert ans == 1

def test_example_statement(run, x):
    example_input = "4 3\n1 4 2 3\n4 1 2 3\n1 2 4 3\n"
    if x == example_input:
        out = run(x).strip()
        assert out == "3"

def test_monotonicity_pairs(run, x):
    lines = x.strip().split('\n')
    n_k = list(map(int, lines[0].split()))
    n, k = n_k[0], n_k[1]
    if n > 10:
        return
    perms = [list(map(int, line.split())) for line in lines[1:1+k]]
    def brute_lcs_two(p1, p2):
        n = len(p1)
        pos1 = {val: idx for idx, val in enumerate(p1)}
        pos2 = {val: idx for idx, val in enumerate(p2)}
        rel = [[False]*n for _ in range(n)]
        for a in range(n):
            for b in range(n):
                if a==b: continue
                if pos1[a+1] < pos1[b+1] and pos2[a+1] < pos2[b+1]:
                    rel[a][b] = True
        best = 0
        for mask in range(1, 1<<n):
            subset = [i for i in range(n) if mask & (1<<i)]
            ok = True
            for i in subset:
                for j in subset:
                    if i != j and not (rel[i][j] or rel[j][i]):
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                best = max(best, len(subset))
        return best
    min_pair_lcs = n
    for i in range(k):
        for j in range(i+1, k):
            lcs_ij = brute_lcs_two(perms[i], perms[j])
            if lcs_ij < min_pair_lcs:
                min_pair_lcs = lcs_ij
    out = run(x).strip()
    assert out.isdigit()
    ans = int(out)
    assert ans <= min_pair_lcs

def test_answer_integer(run, x):
    out = run(x).strip()
    assert out.isdigit()

def test_output_format(run, x):
    out = run(x)
    stripped = out.strip()
    assert stripped.isdigit()
    assert out == stripped + '\n' or out == stripped

def test_upper_bound_lis(run, x):
    lines = x.strip().split('\n')
    n_k = list(map(int, lines[0].split()))
    n, k = n_k[0], n_k[1]
    perms = [list(map(int, line.split())) for line in lines[1:1+k]]
    def lis_length(perm):
        piles = []
        for x in perm:
            lo, hi = 0, len(piles)
            while lo < hi:
                mid = (lo+hi)//2
                if piles[mid] >= x:
                    hi = mid
                else:
                    lo = mid+1
            if lo == len(piles):
                piles.append(x)
            else:
                piles[lo] = x
        return len(piles)
    min_lis = min(lis_length(p) for p in perms)
    out = run(x).strip()
    assert out.isdigit()
    ans = int(out)
    assert ans <= min_lis

