def test_correct_placement(run, x):
    lines_in = x.strip().split('\n')
    n = int(lines_in[0])
    a = list(map(int, lines_in[1].split()))
    day_fall = [0]*(n+1)
    for day, size in enumerate(a, start=1):
        day_fall[size] = day
    day_place = [0]*(n+1)
    day_place[n] = day_fall[n]
    for s in range(n-1, 0, -1):
        day_place[s] = max(day_fall[s], day_place[s+1])
    expected = []
    for day in range(1, n+1):
        sizes = [s for s in range(1, n+1) if day_place[s] == day]
        sizes.sort(reverse=True)
        expected.append(sizes)
    out = run(x)
    lines = out.split('\n')
    if lines and lines[-1] == '':
        lines.pop()
    if len(lines) != n:
        assert False, f"line count mismatch: expected {n}, got {len(lines)}"
    for i in range(n):
        line = lines[i].rstrip()
        if line == '':
            got = []
        else:
            got = list(map(int, line.split()))
        if got != expected[i]:
            assert False, f"line {i+1} mismatch: expected {expected[i]}, got {got}"


