def test_bruteforce(run, x):
    import sys
    MOD = 10**9+7
    data = x.strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))
    if any(i+1 == a[i] for i in range(n)):
        return
    if n > 10:
        return
    total = 0
    for mask in range(1<<n):
        adj = [[] for _ in range(n)]
        for i in range(n):
            if mask & (1<<i):
                src = a[i]-1
                dst = i
            else:
                src = i
                dst = a[i]-1
            adj[src].append(dst)
        visited = [0]*n
        cycle = False
        def dfs(u):
            nonlocal cycle
            if cycle:
                return
            visited[u] = 1
            for v in adj[u]:
                if visited[v] == 1:
                    cycle = True
                    return
                elif visited[v] == 0:
                    dfs(v)
            visited[u] = 2
        for u in range(n):
            if visited[u] == 0:
                dfs(u)
                if cycle:
                    break
        if not cycle:
            total += 1
    expected = total % MOD
    out = run(x).strip()
    assert int(out) == expected

def test_output_format(run, x):
    data = x.strip().split()
