    if any(i+1 == a[i] for i in range(n)):
        return
    out = run(x).strip()
    ans = int(out)
    assert 0 <= ans < MOD

def test_example1(run, x):
    if x == "3\n2 3 1\n":
        out = run(x).strip()
        assert out == "6"

def test_example2(run, x):
    if x == "4\n2 1 1 1\n":
        out = run(x).strip()
        assert out == "8"

def test_example3(run, x):
    if x == "5\n2 4 2 5 3\n":
        out = run(x).strip()
        assert out == "28"

def test_single_cycle(run, x):
    MOD = 10**9+7
    data = x.strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))
    if any(i+1 == a[i] for i in range(n)):
        return
    if len(set(a)) != n:
        return
    visited = set()
    cur = 1
    while cur not in visited:
        visited.add(cur)
        cur = a[cur-1]
    if len(visited) == n and cur == 1:
        expected = (pow(2, n, MOD) - 2) % MOD
        out = run(x).strip()
        assert int(out) == expected

def test_permutation(run, x):
    MOD = 10**9+7
    data = x.strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))
    if any(i+1 == a[i] for i in range(n)):
        return
    if len(set(a)) != n:
        return
    visited = [False]*n
    cycles = []
    for i in range(n):
        if not visited[i]:
            cnt = 0
            j = i
            while not visited[j]:
                visited[j] = True
                j = a[j]-1
                cnt += 1
            cycles.append(cnt)
    expected = 1
    for L in cycles:
        expected = expected * (pow(2, L, MOD) - 2) % MOD
    out = run(x).strip()
    assert int(out) == expected

def test_at_most_total(run, x):
    data = x.strip().split()
