    if any(i+1 == a[i] for i in range(n)):
        return
    out = run(x).strip()
    ans = int(out)
    total_subsets = 1 << n
    assert ans <= total_subsets

def test_permutation_even(run, x):
    data = x.strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))
    if any(i+1 == a[i] for i in range(n)):
        return
    if len(set(a)) != n:
        return
    out = run(x).strip()
    ans = int(out)
    assert ans % 2 == 0

