def test_upper_bound(run, x):
    out = run(x)
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    N = int(lines[0].strip())
    prices = list(map(int, ' '.join(lines[1:]).split()))
    if len(prices) < N:
        prices += [0] * (N - len(prices))
    else:
        prices = prices[:N]
    min_so_far = prices[0]
    bound = 0
    for i in range(1, N):
        bound += max(0, prices[i] - min_so_far)
        min_so_far = min(min_so_far, prices[i])
    profit = int(out.strip())
    assert profit <= bound

