def test_oracle(run, x):
    output = run(x)
    lines = x.splitlines()
    k1,k2,k3 = map(int, lines[0].split())
    n = k1+k2+k3
    A = [0]*n
    if len(lines) > 1:
        for num in lines[1].split():
            if num:
                A[int(num)-1] = 0
    if len(lines) > 2:
        for num in lines[2].split():
            if num:
                A[int(num)-1] = 1
    if len(lines) > 3:
        for num in lines[3].split():
            if num:
                A[int(num)-1] = 2
    dp0 = dp1 = dp2 = 0
    for val in A:
        if val == 0:
            dp0 += 1
        elif val == 1:
            dp1 = max(dp0, dp1) + 1
        else:
            dp2 = max(dp0, dp1, dp2) + 1
    L = max(dp0, dp1, dp2)
    correct = n - L
    ans = int(output.strip())
    assert ans == correct

def test_bounds(run, x):
    output = run(x)
    lines = x.splitlines()
    k1,k2,k3 = map(int, lines[0].split())
    n = k1+k2+k3
    ans = int(output.strip())
    assert 0 <= ans <= n

def test_integer(run, x):
    output = run(x)
    s = output.strip()
    assert s.isdigit()

def test_format(run, x):
    output = run(x)
    assert output.endswith('\n')
    lines = output.strip().split('\n')
    assert len(lines) == 1
    assert lines[0].isdigit()

def test_already_sorted(run, x):
