    A = [0]*n
    if len(lines) > 1:
        for num in lines[1].split():
            if num:
                A[int(num)-1] = 0
    if len(lines) > 2:
        for num in lines[2].split():
            if num:
                A[int(num)-1] = 1
    if len(lines) > 3:
        for num in lines[3].split():
            if num:
                A[int(num)-1] = 2
    non_decreasing = all(A[i] <= A[i+1] for i in range(n-1))
    if non_decreasing:
        ans = int(output.strip())
