    A = [0]*n
    if len(lines) > 1:
        for num in lines[1].split():
            if num:
                A[int(num)-1] = 0
    if len(lines) > 2:
        for num in lines[2].split():
            if num:
                A[int(num)-1] = 1
    if len(lines) > 3:
        for num in lines[3].split():
            if num:
                A[int(num)-1] = 2
    if all(val == A[0] for val in A):
        ans = int(output.strip())
