def test_small_bruteforce(run, x):
    output = run(x)
    lines = x.splitlines()
    k1,k2,k3 = map(int, lines[0].split())
    n = k1+k2+k3
    if n > 8:
        return
    A = [0]*n
    if len(lines) > 1:
        for num in lines[1].split():
            if num:
                A[int(num)-1] = 0
    if len(lines) > 2:
        for num in lines[2].split():
