def test_bruteforce_small(run, x):
    data = list(map(int, x.split()))
    if not data:
        return
    t = data[0]
    pos = 1
    outputs = run(x).splitlines()
    for case in range(t):
        n = data[pos]; special = data[pos+1]; pos += 2
        if n > 13:
            pos += 2*(n-1)
            continue
        adj = [[] for _ in range(n)]
        for i in range(n-1):
            u = data[pos]-1; v = data[pos+1]-1; pos += 2
            adj[u].append(v); adj[v].append(u)
        special_idx = special-1
        from functools import lru_cache
        @lru_cache(None)
        def win(mask, turn):
            if not (mask & (1<<special_idx)):
                return False
            def degree(node, mask):
                cnt = 0
                for nb in adj[node]:
                    if mask & (1<<nb):
                        cnt += 1
                return cnt
            if degree(special_idx, mask) <= 1:
                return True
            moves = []
            for i in range(n):
                if i == special_idx:
                    continue
                if (mask>>i)&1 and degree(i, mask) <= 1:
                    moves.append(mask & ~(1<<i))
            if turn == 0:
                for newmask in moves:
                    if not win(newmask, 1):
                        return True
                return False
            else:
                for newmask in moves:
                    if win(newmask, 0):
                        return False
                return True
        start = (1<<n)-1
        ayush_wins = win(start, 0)
        expected = "Ayush" if ayush_wins else "Ashish"
        assert outputs[case] == expected, f"Case {case+1}: expected {expected}, got {outputs[case]}"


def test_output_format(run, x):
    out = run(x)
    lines = out.split('\n')
    if lines and lines[-1] == '':
        lines.pop()
    for line in lines:
        assert line in ("Ayush", "Ashish"), f"Invalid output line: {line}"
    if out and not out.endswith('\n'):
        assert False, "Output must end with newline"
    data = list(map(int, x.split()))
    if data:
        t = data[0]
        assert len(lines) == t, f"Expected {t} lines, got {len(lines)}"

