            break
        questions.append((i, L, R, ans))
    if not valid:
        return
    low_all = 2**(h-1)
    high_all = 2**h - 1
    intervals = [(low_all, high_all)]
    for i, L, R, ans in questions:
        offset = 1 << (h - i)
        cond_low = L * offset
        cond_high = (R + 1) * offset - 1
        new_intervals = []
        if ans == 1:
            for lo, hi in intervals:
                inter_lo = max(lo, cond_low)
                inter_hi = min(hi, cond_high)
                if inter_lo <= inter_hi:
