                else:
                    if lo < cond_low:
                        new_intervals.append((lo, cond_low - 1))
                    if hi > cond_high:
                        new_intervals.append((cond_high + 1, hi))
        intervals = new_intervals
        if not intervals:
            break
    total = 0
    candidate = None
    for lo, hi in intervals:
        total += hi - lo + 1
        if total == 1 and candidate is None:
            candidate = lo
    if total == 0:
        expected = 'Game cheated!'
