def test_constraints_satisfied(run, x):
    output = run(x).strip()
    try:
        leaf = int(output)
    except ValueError:
        return
    lines = x.strip().split('\n')
    if not lines:
        return
    hq = lines[0].split()
    if len(hq) < 2:
        return
    h = int(hq[0])
    q = int(hq[1])
    valid = True
    for j in range(1, q+1):
        if j >= len(lines):
            break
        parts = lines[j].split()
        if len(parts) < 4:
            valid = False
            break
        i, L, R, ans = map(int, parts)
        if not (1 <= i <= h):
            valid = False
            break
        if not (2**(i-1) <= L <= R <= 2**i - 1):
            valid = False
            break
        offset = 1 << (h - i)
        ancestor = leaf // offset
        if ans == 1:
            if not (L <= ancestor <= R):
                assert False, f'Leaf {leaf} fails yes question {i} {L} {R}'
        else:
            if L <= ancestor <= R:
                assert False, f'Leaf {leaf} fails no question {i} {L} {R}'
    if not valid:
        return

