def test_height_one_case(run, x):
    lines = x.strip().split('\n')
    if not lines:
        return
    hq = lines[0].split()
    if len(hq) < 2:
        return
    h = int(hq[0])
    if h != 1:
        return
    q = int(hq[1])
    questions = []
    valid = True
    for j in range(1, q+1):
        if j >= len(lines):
            break
        parts = lines[j].split()
        if len(parts) < 4:
            valid = False
            break
        i, L, R, ans = map(int, parts)
        if not (1 <= i <= h):
            valid = False
            break
        if not (2**(i-1) <= L <= R <= 2**i - 1):
            valid = False
            break
        questions.append((i, L, R, ans))
    if not valid:
        return
    possible = True
    for i, L, R, ans in questions:
        if ans == 1:
            if not (L <= 1 <= R):
                possible = False
                break
        else:
            if L <= 1 <= R:
                possible = False
                break
    output = run(x).strip()
    if possible:
