def test_lower_bound_ecc_arbitrary(run, x):
    out = run(x).strip()
    try:
        val = int(out)
    except ValueError:
        assert False, "Output is not an integer"
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    adj = [[] for _ in range(n)]
    for line in lines[1:1+m]:
        a, b = map(int, line.split())
        adj[a-1].append(b-1)
        adj[b-1].append(a-1)
    from collections import deque
    dist = [-1]*n
    q = deque([0])
    dist[0] = 0
    while q:
        u = q.popleft()
        for v in adj[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                q.append(v)
    ecc = max(dist)
    assert val >= ecc, f"Brain latency {val} must be at least eccentricity of node 1 ({ecc})"

def test_lower_bound_ecc_leaf(run, x):
