def test_small_exact(run, x):
    out = run(x).strip()
    try:
        val = int(out)
    except ValueError:
        assert False, "Output is not an integer"
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    if n > 100:
        return
    adj = [[] for _ in range(n)]
    for line in lines[1:1+m]:
        a, b = map(int, line.split())
        adj[a-1].append(b-1)
        adj[b-1].append(a-1)
    from collections import deque
    def bfs(start):
        dist = [-1]*n
        q = deque([start])
        dist[start] = 0
        while q:
            u = q.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    q.append(v)
        return max(dist)
    diam = max(bfs(i) for i in range(n))
    assert val == diam, f"Brain latency {val} does not match computed diameter {diam}"

def test_path_graph(run, x):
    out = run(x).strip()
    try:
        val = int(out)
    except ValueError:
        assert False, "Output is not an integer"
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    if m != n-1:
        return
    adj = [[] for _ in range(n)]
    for line in lines[1:1+m]:
        a, b = map(int, line.split())
        adj[a-1].append(b-1)
        adj[b-1].append(a-1)
    deg = [len(adj[i]) for i in range(n)]
    if deg.count(1) == 2 and deg.count(2) == n-2:
        assert val == n-1, f"For a path graph with n={n}, brain latency must be {n-1}, got {val}"

def test_star_graph(run, x):
    out = run(x).strip()
    try:
        val = int(out)
    except ValueError:
        assert False, "Output is not an integer"
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    if m != n-1:
        return
    adj = [[] for _ in range(n)]
    for line in lines[1:1+m]:
        a, b = map(int, line.split())
        adj[a-1].append(b-1)
        adj[b-1].append(a-1)
    deg = [len(adj[i]) for i in range(n)]
    if n > 2 and deg.count(n-1) == 1 and deg.count(1) == n-1:
        assert val == 2, f"For a star graph with n={n}, brain latency must be 2, got {val}"

def test_complete_graph(run, x):
    out = run(x).strip()
    try:
        val = int(out)
    except ValueError:
        assert False, "Output is not an integer"
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    if m != n*(n-1)//2:
        return
    if n == 1:
        assert val == 0, f"For a complete graph with n=1, brain latency must be 0"
    else:
        assert val == 1, f"For a complete graph with n={n}, brain latency must be 1, got {val}"

