def test_brute_force_correctness(run, x):
    lines = x.strip().split()
    if not lines:
        return
    n = int(lines[0])
    if n > 8:
        return  # guard: brute force only for small n
    a = list(map(int, lines[1:1+n]))
    b = [bin(v).count('1') for v in a]
    correct = 0
    for l in range(n):
        s = 0
        mx = 0
        for r in range(l, n):
            s += b[r]
            mx = max(mx, b[r])
            if s % 2 == 0 and mx <= s - mx:
                correct += 1
    out = run(x).strip()
    assert out.isdigit() and int(out) == correct

def test_output_integer(run, x):
    out = run(x).strip()
    assert out.isdigit()

def test_non_negative(run, x):
    out = run(x).strip()
    assert out.isdigit() and int(out) >= 0

def test_leq_total(run, x):
    lines = x.strip().split()
    if not lines:
        return
    n = int(lines[0])
    total = n * (n + 1) // 2
    out = run(x).strip()
    assert out.isdigit() and int(out) <= total

def test_example1(run, x):
    if x == "3\n6 7 14\n":
        out = run(x).strip()
        assert out == "2"

def test_example2(run, x):
    if x == "4\n1 2 1 16\n":
        out = run(x).strip()
        assert out == "4"

def test_single_element(run, x):
    lines = x.strip().split()
    if len(lines) < 2:
        return
    n = int(lines[0])
    if n != 1:
        return
    a = int(lines[1])
    # according to the statement a_i >= 1, so answer must be 0
    out = run(x).strip()
    assert out == "0"

def test_pair_equal_popcount(run, x):
    lines = x.strip().split()
    if len(lines) < 3:
        return
    n = int(lines[0])
    if n != 2:
        return
    a = list(map(int, lines[1:3]))
    if a[0] == 0 or a[1] == 0:
        return  # skip zeros
    b = [bin(v).count('1') for v in a]
    expected = 1 if b[0] == b[1] else 0
    out = run(x).strip()
    assert out.isdigit() and int(out) == expected

def test_pair_one_zero(run, x):
    lines = x.strip().split()
    if len(lines) < 3:
        return
    n = int(lines[0])
    if n != 2:
        return
    a = list(map(int, lines[1:3]))
    zero_cnt = (a[0] == 0) + (a[1] == 0)
    if zero_cnt != 1:
        return
    # exactly one zero, the other non‑zero → only the zero singleton is good
    out = run(x).strip()
    assert out.isdigit() and int(out) == 1

def test_upper_bound_even_sum(run, x):
    lines = x.strip().split()
    if not lines:
        return
    n = int(lines[0])
    if n > 8:
        return  # guard: O(n^2) only for small n
    a = list(map(int, lines[1:1+n]))
    b = [bin(v).count('1') for v in a]
    even_cnt = 0
    for l in range(n):
        s = 0
        for r in range(l, n):
            s += b[r]
            if s % 2 == 0:
                even_cnt += 1
    out = run(x).strip()
    assert out.isdigit() and int(out) <= even_cnt

