def test_dp_exact(run, x):
    parts = x.strip().split()
    if len(parts) < 4:
        return
    v1, v2, t, d = map(int, parts)
    if abs(v1 - v2) > (t-1)*d:
        return
    out = run(x)
    try:
        ans = int(out.strip())
    except:
        assert False, "Output not an integer"
    max_speed = max(v1, v2) + (t-1)*d
    INF_NEG = -10**9
    dp_prev = [INF_NEG] * (max_speed + 1)
    dp_prev[v1] = v1
    for i in range(1, t):
        dp_cur = [INF_NEG] * (max_speed + 1)
        for s in range(max_speed + 1):
            low = max(0, s - d)
            high = min(max_speed, s + d)
            best = INF_NEG
            for sp in range(low, high+1):
                if dp_prev[sp] > best:
                    best = dp_prev[sp]
            if best > INF_NEG:
                dp_cur[s] = best + s
        dp_prev = dp_cur
    correct = dp_prev[v2]
    if correct < 0:
        return
    assert ans == correct, f"DP oracle mismatch: expected {correct}, got {ans}"


def test_greedy_lower_bound(run, x):
    parts = x.strip().split()
    if len(parts) < 4:
        return
    v1, v2, t, d = map(int, parts)
    if abs(v1 - v2) > (t-1)*d:
        return
    out = run(x)
    try:
        ans = int(out.strip())
    except:
        assert False, "Output not an integer"
    s = v1
    total_greedy = s
    for i in range(2, t+1):
        if s < v2:
            s = min(s + d, v2)
        else:
            s = max(s - d, v2)
        total_greedy += s
    assert ans >= total_greedy, f"Output {ans} is less than greedy lower bound {total_greedy}"


def test_upper_bounds(run, x):
    parts = x.strip().split()
    if len(parts) < 4:
        return
    v1, v2, t, d = map(int, parts)
    if abs(v1 - v2) > (t-1)*d:
        return
    out = run(x)
    try:
        ans = int(out.strip())
    except:
        assert False, "Output not an integer"
    forward_sum = t * v1 + d * t * (t-1) // 2
    backward_sum = t * v2 + d * t * (t-1) // 2
    assert ans <= forward_sum, f"Output {ans} exceeds forward upper bound {forward_sum}"
    assert ans <= backward_sum, f"Output {ans} exceeds backward upper bound {backward_sum}"


def test_d0_case(run, x):
    parts = x.strip().split()
    if len(parts) < 4:
        return
    v1, v2, t, d = map(int, parts)
    if d != 0:
        return
    if v1 != v2:
        return
    out = run(x)
    try:
        ans = int(out.strip())
    except:
        assert False, "Output not an integer"
    assert ans == v1 * t, f"For d=0, expected {v1*t}, got {ans}"


def test_t2_case(run, x):
    parts = x.strip().split()
    if len(parts) < 4:
        return
    v1, v2, t, d = map(int, parts)
    if t != 2:
        return
    if abs(v1 - v2) > d:
        return
    out = run(x)
    try:
        ans = int(out.strip())
    except:
        assert False, "Output not an integer"
    assert ans == v1 + v2, f"For t=2, expected {v1+v2}, got {ans}"


def test_integer(run, x):
    out = run(x)
    s = out.strip()
    assert s.isdigit() or (s[0]=='-' and s[1:].isdigit()), "Output is not an integer"
    ans = int(s)
    assert ans >= 0, "Output is negative"


def test_loose_upper_bound(run, x):
    parts = x.strip().split()
    if len(parts) < 4:
        return
    v1, v2, t, d = map(int, parts)
    out = run(x)
    try:
        ans = int(out.strip())
    except:
        assert False, "Output not an integer"
    max_speed = max(v1, v2) + (t-1)*d
    loose_upper = t * max_speed
    assert ans <= loose_upper, f"Output {ans} exceeds loose upper bound {loose_upper}"


def test_min_upper_bound(run, x):
    parts = x.strip().split()
    if len(parts) < 4:
        return
    v1, v2, t, d = map(int, parts)
    total = 0
    for i in range(1, t+1):
        total += min(v1 + (i-1)*d, v2 + (t-i)*d)
    out = run(x)
    try:
        ans = int(out.strip())
    except:
        assert False, "Output not an integer"
    assert ans <= total, f"Output {ans} exceeds min-formula upper bound {total}"


def test_max_lower_bound(run, x):
    parts = x.strip().split()
    if len(parts) < 4:
        return
    v1, v2, t, d = map(int, parts)
    total = 0
    for i in range(1, t+1):
        total += max(0, v1 - (i-1)*d, v2 - (t-i)*d)
    out = run(x)
    try:
        ans = int(out.strip())
    except:
        assert False, "Output not an integer"
    assert ans >= total, f"Output {ans} is less than max-lower-bound {total}"


def test_provided_examples(run, x):
    out = run(x)
    s = out.strip()
    if x == "5 6\n4 2\n":
        assert s == "26"
    elif x == "10 10\n10 0\n":
        assert s == "100"

