def test_output_format(run, x):
    out = run(x).strip()
    assert out in ("sjfnb", "cslnb")

def test_all_zero(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    a = list(map(int, lines[1].split()))[:n]
    if all(v == 0 for v in a):
        out = run(x).strip()
        assert out == "cslnb"

def test_example1(run, x):
    if x == "1\n0\n":
        out = run(x).strip()
        assert out == "cslnb"

def test_example2(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    a = list(map(int, lines[1].split()))[:n]
    if n == 2 and sorted(a) == [0, 1]:
        out = run(x).strip()
        assert out == "cslnb"

def test_example3(run, x):
    if x == "2\n2 2\n":
        out = run(x).strip()
        assert out == "sjfnb"

def test_small_bruteforce(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    a = list(map(int, lines[1].split()))[:n]
    if n > 5 or max(a) > 5:
        return
    from functools import lru_cache
    @lru_cache(None)
    def win(state):
        if all(v == 0 for v in state):
            return False
        n_ = len(state)
        for i in range(n_):
            if state[i] == 0:
                continue
            new = list(state)
            new[i] -= 1
            new.sort()
            if any(new[j] == new[j+1] for j in range(n_-1)):
                continue
            if not win(tuple(new)):
                return True
        return False
    expected = "sjfnb" if win(tuple(sorted(a))) else "cslnb"
    out = run(x).strip()
    assert out == expected

def test_no_duplicate_small_sum(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    a = list(map(int, lines[1].split()))[:n]
    if len(set(a)) == n and sum(a) == n*(n-1)//2:
        out = run(x).strip()
        assert out == "cslnb"

def test_duplicate_zero(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    a = list(map(int, lines[1].split()))[:n]
    if a.count(0) >= 2:
        out = run(x).strip()
        assert out == "cslnb"

def test_single_pile(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    a = list(map(int, lines[1].split()))[:n]
    if n != 1:
        return
    expected = "cslnb" if a[0] == 0 or a[0] % 2 == 0 else "sjfnb"
    out = run(x).strip()
    assert out == expected

def test_duplicate_with_predecessor(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    a = list(map(int, lines[1].split()))[:n]
    from collections import Counter
    cnt = Counter(a)
    if max(cnt.values()) >= 3:
        return
    dup_counts = [v for v, c in cnt.items() if c == 2]
    if len(dup_counts) != 1:
        return
    x = dup_counts[0]
    if x == 0:
        return
    if cnt.get(x-1, 0) != 1:
        return
    expected = "cslnb"
    out = run(x).strip()
    assert out == expected

