def test_output_format(run, x):
    out = run(x)
    assert out in ("YES\n", "NO\n"), f"Invalid output format: {repr(out)}"


def test_character_parity(run, x):
    out = run(x).strip()
    if out == "YES":
        lines = x.strip().splitlines()
        H, W = map(int, lines[0].split())
        from collections import Counter
        cnt = Counter()
        for line in lines[1:1+H]:
            cnt.update(line.strip())
        total = H*W
        odd_count = sum(1 for v in cnt.values() if v%2==1)
        if total % 2 == 0:
            assert odd_count == 0, f"Even total cells but odd character count: {odd_count}"
        else:
            assert odd_count <= 1, f"Odd total cells but odd character count >1: {odd_count}"


def test_row_multiset_pairing(run, x):
    out = run(x).strip()
    if out == "YES":
        lines = x.strip().splitlines()
        H, W = map(int, lines[0].split())
        from collections import Counter
        rows = [line.strip() for line in lines[1:1+H]]
        row_counters = [Counter(row) for row in rows]
        used = [False]*H
        for i in range(H):
            if used[i]: continue
            for j in range(i+1, H):
                if used[j]: continue
                if row_counters[i] == row_counters[j]:
                    used[i] = used[j] = True
                    break
        unpaired = sum(1 for u in used if not u)
        if H % 2 == 0:
            assert unpaired == 0, f"Even rows but {unpaired} unpaired rows"
        else:
            assert unpaired <= 1, f"Odd rows but {unpaired} unpaired rows >1"


def test_column_multiset_pairing(run, x):
    out = run(x).strip()
    if out == "YES":
        lines = x.strip().splitlines()
        H, W = map(int, lines[0].split())
        from collections import Counter
        grid = [list(line.strip()) for line in lines[1:1+H]]
        cols = [''.join(grid[i][j] for i in range(H)) for j in range(W)]
        col_counters = [Counter(col) for col in cols]
        used = [False]*W
        for i in range(W):
            if used[i]: continue
            for j in range(i+1, W):
                if used[j]: continue
                if col_counters[i] == col_counters[j]:
                    used[i] = used[j] = True
                    break
        unpaired = sum(1 for u in used if not u)
        if W % 2 == 0:
            assert unpaired == 0, f"Even columns but {unpaired} unpaired columns"
