    out = run(x).strip()
    M = 1000000007
    parts = x.strip().split()
    if len(parts) != 2:
        return
    n = int(parts[0])
    k = int(parts[1])
    if n > 10**6:
        return
    # Euler's totient by trial division
    def phi(m):
        result = m
        i = 2
        temp = m
        while i * i <= temp:
            if temp % i == 0:
                while temp % i == 0:
                    temp //= i
                result -= result // i
            i += 1 if i == 2 else 2
        if temp > 1:
            result -= result // temp
        return result
    current = n
    t = (k + 1) // 2  # ceil(k/2)
    for _ in range(t):
        if current == 1:
            break
        current = phi(current)
    expected = current % M
    assert int(out) % M == expected, f'For {x.strip()}, expected {expected} mod {M}, got {out}'

