def test_oracle(run, x):
    import math
    n_str, s_str = x.strip().split()
    n = int(n_str)
    s = int(s_str)
    output = run(x).strip()
    if s > n:
        correct = -1
    elif s == n:
        correct = n + 1
    else:
        l = n - s
        sqrt_n = int(math.isqrt(n)) + 1
        ans = None
        for b in range(2, sqrt_n + 1):
            t = 0
            u = n
            while u:
                t += u % b
                u //= b
            if t == s:
                ans = b
                break
        for a in range(1, sqrt_n + 1):
            if l % a != 0:
                continue
            b = l // a + 1
            if b <= sqrt_n:
                continue
            if b < 2:
                continue
            if a >= b:
                continue
            c = s - a
            if c < 0 or c >= b:
                continue
            if n != a * b + c:
                continue
            if ans is None or b < ans:
                ans = b
        correct = -1 if ans is None else ans
    try:
        out_val = int(output)
    except ValueError:
        assert False, "Output is not an integer"
    assert out_val == correct, f"Oracle mismatch: got {out_val}, expected {correct}"


def test_format(run, x):
    output = run(x).strip()
    assert output == "-1" or (output.isdigit() and not output.startswith('-')), f"Invalid output format: {output}"


def test_b_ge_2(run, x):
    output = run(x).strip()
    if output != "-1":
        b = int(output)
        assert b >= 2, f"b={b} is less than 2"


def test_digit_sum(run, x):
    n_str, s_str = x.strip().split()
    n = int(n_str)
    s = int(s_str)
    output = run(x).strip()
    if output == "-1":
        return
    b = int(output)
    t = 0
    u = n
    while u:
        t += u % b
        u //= b
    assert t == s, f"Digit sum for b={b} is {t}, expected {s}"


def test_mod_condition(run, x):
    n_str, s_str = x.strip().split()
    n = int(n_str)
    s = int(s_str)
    output = run(x).strip()
    if output == "-1":
        return
    b = int(output)
    l = n - s
    if l < 0:
        assert False, "s>n but output is not -1"
    assert (b - 1) > 0, "b-1 must be positive"
    assert l % (b - 1) == 0, f"b-1={b-1} does not divide n-s={l}"


