    if max(a) > 30:
        return
    k_odd = k % 2
    from functools import lru_cache
    @lru_cache(None)
    def g(m):
        if m == 0:
            return 0
        moves = {g(m-1)}
        if m % 2 == 0:
            if k_odd == 0:
                moves.add(0)
            else:
                moves.add(g(m//2))
        mex = 0
        while mex in moves:
            mex += 1
        return mex
    xor = 0
    for size in a:
        xor ^= g(size)
    expected = "Kevin" if xor != 0 else "Nicky"
    assert output == expected

