def test_by_summation(run, x):
    n, l, r = map(int, x.strip().split())
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def len_cache(m):
        if m <= 1:
            return 1
        return 2 * len_cache(m // 2) + 1
    @lru_cache(maxsize=None)
    def val(m, pos):
        if m <= 1:
            return m
        half_len = len_cache(m // 2)
        mid = half_len + 1
        if pos < mid:
            return val(m // 2, pos)
        elif pos > mid:
            return val(m // 2, pos - mid)
        else:
            return m % 2
    ans = 0
    for i in range(l, r+1):
        ans += val(n, i)
    output = run(x).strip()
    assert output == str(ans)

def test_n0_l1_r1(run, x):
    n, l, r = map(int, x.strip().split())
    if n == 0 and l == 1 and r == 1:
        output = run(x).strip()
        assert output == "0"

def test_n1_l1_r1(run, x):
    n, l, r = map(int, x.strip().split())
    if n == 1 and l == 1 and r == 1:
        output = run(x).strip()
        assert output == "1"

def test_full_range(run, x):
    n, l, r = map(int, x.strip().split())
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def length(m):
        if m <= 1:
            return 1
        return 2 * length(m // 2) + 1
    @lru_cache(maxsize=None)
    def total_ones(m):
        if m <= 1:
            return m
        return 2 * total_ones(m // 2) + (m % 2)
    L = length(n)
    if l == 1 and r == L:
        output = run(x).strip()
        expected = total_ones(n)
        assert output == str(expected)

def test_middle_element(run, x):
    n, l, r = map(int, x.strip().split())
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def length(m):
        if m <= 1:
            return 1
        return 2 * length(m // 2) + 1
    L_half = length(n // 2)
    mid = L_half + 1
    if l == r == mid:
        output = run(x).strip()
        expected = n % 2
        assert output == str(expected)

def test_symmetry(run, x):
    n, l, r = map(int, x.strip().split())
    if l > r:
        return
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def length(m):
        if m <= 1:
            return 1
        return 2 * length(m // 2) + 1
    @lru_cache(maxsize=None)
    def val(m, pos):
        if m <= 1:
            return m
        half_len = length(m // 2)
        mid = half_len + 1
        if pos < mid:
            return val(m // 2, pos)
        elif pos > mid:
            return val(m // 2, pos - mid)
        else:
            return m % 2
    L = length(n)
    mirror_l = L - r + 1
    mirror_r = L - l + 1
    mirror_count = 0
    for i in range(mirror_l, mirror_r+1):
        mirror_count += val(n, i)
    output = run(x).strip()
    assert int(output) == mirror_count

def test_answer_bounds(run, x):
    n, l, r = map(int, x.strip().split())
    output = run(x).strip()
    ans = int(output)
    if l <= r:
        assert 0 <= ans <= r - l + 1

