    n, l, r = map(int, x.strip().split())
    if n == 8 and l == 2 and r == 7:
        output = run(x).strip()
        assert output == "3"

def test_small_n_simulation(run, x):
    n, l, r = map(int, x.strip().split())
    if n > 1023:
        return
    seq = [n]
    changed = True
    while changed:
        changed = False
        new_seq = []
        for x in seq:
            if x > 1:
                changed = True
                new_seq.extend([x//2, x%2, x//2])
            else:
                new_seq.append(x)
        seq = new_seq
    if r > len(seq):
        return
    count = sum(seq[i-1] for i in range(l, r+1))
    output = run(x).strip()
    assert output == str(count)

