def test_bruteforce_small(run, x):
    import sys
    lines = x.strip().splitlines()
    n = int(lines[0])
    c = list(map(int, lines[1].split()))
    if n > 8:
        return
    roots = [i for i in range(n) if c[i] == n]
    expected = 'NO'
    if roots:
        for root in roots:
            nodes_order = [i for i in range(n) if i != root]
            parent = [-1]*n
            parent[root] = root
            def backtrack(idx):
                if idx == len(nodes_order):
                    children = [[] for _ in range(n)]
                    for i in range(n):
                        if i != root:
                            children[parent[i]].append(i)
                    for i in range(n):
                        if children[i] and len(children[i]) < 2:
                            return False
                    visited = [False]*n
                    def dfs(v):
                        visited[v] = True
                        sz = 1
                        for u in children[v]:
                            sz += dfs(u)
                        if sz != c[v]:
                            raise ValueError
                        return sz
                    try:
                        dfs(root)
                    except ValueError:
                        return False
                    if not all(visited):
                        return False
                    return True
                node = nodes_order[idx]
                for p in range(n):
                    if p == node:
                        continue
                    if c[p] > c[node]:
                        parent[node] = p
                        if backtrack(idx+1):
                            return True
                        parent[node] = -1
                return False
            if backtrack(0):
                expected = 'YES'
                break
    output = run(x).strip()
    assert output == expected, f'Brute-force mismatch: expected {expected}, got {output}'

def test_exactly_one_n_on_yes(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    c = list(map(int, lines[1].split()))
    output = run(x).strip()
    if output == 'YES':
        assert c.count(n) == 1, f'YES output but count of n={n} is {c.count(n)}'

def test_no_2_on_yes(run, x):
    lines = x.strip().splitlines()
    c = list(map(int, lines[1].split()))
    output = run(x).strip()
    if output == 'YES':
        assert 2 not in c, f'YES output but 2 present in c'

def test_internal_size_ge_3_on_yes(run, x):
    lines = x.strip().splitlines()
    c = list(map(int, lines[1].split()))
    output = run(x).strip()
    if output == 'YES':
        for val in c:
            if val > 1:
                assert val >= 3, f'YES output but c={val} which is >1 and <3'

def test_min_leaves_on_yes(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    c = list(map(int, lines[1].split()))
    output = run(x).strip()
    if output == 'YES':
        ones = c.count(1)
        required = (n + 2) // 2   # ceil((n+1)/2)
        assert ones >= required, f'YES output but ones={ones} < required {required}'

def test_all_ones_sufficient(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    c = list(map(int, lines[1].split()))
    if c.count(n) == 1 and all(val == 1 or val == n for val in c):
        output = run(x).strip()
        if n == 1:
            assert output == 'YES', f'n=1 must be YES'
        elif n == 2:
            assert output == 'NO', f'n=2 with [2,1] must be NO'
        else:
            assert output == 'YES', f'Pattern n={n} with n-1 ones must be YES'

def test_output_format(run, x):
    output = run(x)
    out = output.strip()
    assert out in ('YES', 'NO'), f'Output must be YES or NO, got {output!r}'

def test_n1(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    if n == 1:
        output = run(x).strip()
        assert output == 'YES', f'For n=1, must be YES'

def test_2_implies_no(run, x):
    lines = x.strip().splitlines()
    c = list(map(int, lines[1].split()))
    if 2 in c:
        output = run(x).strip()
        assert output == 'NO', f'c contains 2, must output NO'

def test_max_eq_n(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    c = list(map(int, lines[1].split()))
    if max(c) != n:
        output = run(x).strip()
        assert output == 'NO', f'max(c)={max(c)} != n={n}, must output NO'

