    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    first = lines[0].strip().split()
    if len(first) < 2:
        return
    n, m = map(int, first)
    if m > 10:
        return
    doors = list(map(int, lines[1].strip().split()))
    if len(doors) != n:
        return
    idx = 2
    switch_rooms = []
    for i in range(m):
        if idx >= len(lines):
            return
        parts = list(map(int, lines[idx].strip().split()))
        idx += 1
        if not parts:
            return
        x_i = parts[0]
        rooms = parts[1:]
        if len(rooms) != x_i:
            return
        switch_rooms.append(rooms)
    appearances = [0] * (n + 1)
    for rooms in switch_rooms:
        for r in rooms:
            if 1 <= r <= n:
                appearances[r] += 1
    for d in range(1, n + 1):
        if appearances[d] != 2:
            return
    controls = [[] for _ in range(n + 1)]
    for sw_idx, rooms in enumerate(switch_rooms):
        for r in rooms:
            controls[r].append(sw_idx)
    solvable = False
    for mask in range(1 << m):
        ok = True
        for d in range(1, n + 1):
            sw1, sw2 = controls[d]
            parity = ((mask >> sw1) & 1) ^ ((mask >> sw2) & 1)
            if (doors[d - 1] ^ parity) != 1:
                ok = False
                break
        if ok:
            solvable = True
            break
    expected = 'YES' if solvable else 'NO'
    assert run(x).strip() == expected

def test_correct_solver_valid(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    first = lines[0].strip().split()
    if len(first) < 2:
        return
    n, m = map(int, first)
    doors = list(map(int, lines[1].strip().split()))
    if len(doors) != n:
        return
    idx = 2
    switch_rooms = []
    for i in range(m):
        if idx >= len(lines):
            return
        parts = list(map(int, lines[idx].strip().split()))
        idx += 1
        if not parts:
            return
        x_i = parts[0]
        rooms = parts[1:]
        if len(rooms) != x_i:
            return
        switch_rooms.append(rooms)
    appearances = [0] * (n + 1)
    for rooms in switch_rooms:
        for r in rooms:
            if 1 <= r <= n:
                appearances[r] += 1
    for d in range(1, n + 1):
        if appearances[d] != 2:
            return
    controls = [[] for _ in range(n + 1)]
    for sw_idx, rooms in enumerate(switch_rooms):
        for r in rooms:
            controls[r].append(sw_idx)
    from collections import deque
    adj = [[] for _ in range(m)]
    for d in range(1, n + 1):
        sw1, sw2 = controls[d]
        c = doors[d - 1] ^ 1
        adj[sw1].append((sw2, c))
        adj[sw2].append((sw1, c))
    visited = [False] * m
    color = [0] * m
    ok = True
    for i in range(m):
        if not visited[i]:
            dq = deque([i])
            visited[i] = True
            color[i] = 0
            while dq:
                u = dq.popleft()
                for v, c in adj[u]:
                    expected_color = color[u] ^ c
                    if not visited[v]:
                        visited[v] = True
                        color[v] = expected_color
                        dq.append(v)
                    else:
                        if color[v] != expected_color:
                            ok = False
                            break
                if not ok:
                    break
        if not ok:
            break
    expected = 'YES' if ok else 'NO'
    assert run(x).strip() == expected

