tests_src:
def test_full_oracle(run, x):
    n = int(x.strip())
    visited = set()
    y = n
    while y not in visited:
        visited.add(y)
        y += 1
        while y % 10 == 0:
            y //= 10
    correct = len(visited)
    output = run(x).strip()
    assert output.isdigit() and int(output) == correct

def test_output_positive_integer(run, x):
    output = run(x).strip()
    assert output.isdigit()
    val = int(output)
    assert val >= 1

def test_upper_bound(run, x):
    n = int(x.strip())
    d = len(str(n))
    bound = 9 if d == 1 else 9 * d + 1
    output = run(x).strip()
    assert int(output) <= bound

def test_power_of_10(run, x):
    n = int(x.strip())
    if n < 10:
        return
    temp = n
    while temp % 10 == 0:
        temp //= 10
    if temp != 1:
        return
    d = len(str(n))
    expected = 10 + 9 * (d - 1)
    output = run(x).strip()
    assert int(output) == expected

def test_10_followed_by_nines(run, x):
    n = int(x.strip())
    s = str(n)
    if len(s) < 3:
        return
    if s[:2] == '10' and all(c == '9' for c in s[2:]):
        output = run(x).strip()
        assert int(output) == 19

def test_1_followed_by_nines(run, x):
    n = int(x.strip())
    s = str(n)
    if len(s) < 2:
        return
    if s[0] == '1' and all(c == '9' for c in s[1:]):
        output = run(x).strip()
        assert int(output) == 10

def test_single_digit(run, x):
    n = int(x.strip())
    if 1 <= n <= 9:
        output = run(x).strip()
        assert int(output) == 9

def test_n_10(run, x):
    if x.strip() == '10':
        output = run(x).strip()
        assert int(output) == 19

def test_n_10_pow_9(run, x):
    if x.strip() == '1000000000':
        output = run(x).strip()
        assert int(output) == 91

def test_lower_bound_9(run, x):
    output = run(x).strip()
    assert output.isdigit()
    val = int(output)
    assert val >= 9

