    {
      "name": "test_small_n_exact",
      "source": "def test_small_n_exact(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n_k = lines[0].split()
    if len(n_k) < 2:
        return
    n = int(n_k[0])
    k = int(n_k[1])
    s = lines[1].strip()
    if n > 12:
        return
    from itertools import combinations
    distinct = set()
    length_counts = {}
    for mask in range(1 << n):
        subseq = ''.join(s[i] for i in range(n) if (mask >> i) & 1)
        distinct.add(subseq)
    for sub in distinct:
        L = len(sub)
        length_counts[L] = length_counts.get(L, 0) + 1
    remaining = k
    cost = 0
    for L in sorted(length_counts.keys(), reverse=True):
        cnt = length_counts[L]
        take = min(remaining, cnt)
        cost += take * (n - L)
        remaining -= take
        if remaining == 0:
            break
    expected = -1 if remaining > 0 else cost
    out = run(x).strip()
    if expected == -1:
        assert out == "-1", f"Expected -1, got {out}"
    else:
        assert out == str(expected), f"Expected {expected}, got {out}""
    },
