      "name": "test_all_distinct_exact_cost",
      "source": "def test_all_distinct_exact_cost(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n_k = lines[0].split()
    if len(n_k) < 2:
        return
    n = int(n_k[0])
    k = int(n_k[1])
    s = lines[1].strip()
    if len(set(s)) != n:
        return
    import math
    remaining = k
    total_cost = 0
    for L in range(n, -1, -1):
        cnt = math.comb(n, L)
        take = min(remaining, cnt)
        total_cost += take * (n - L)
        remaining -= take
        if remaining == 0:
            break
    expected = -1 if remaining > 0 else total_cost
    out = run(x).strip()
