def test_oracle(run, x):
    n = int(x.strip())
    hex_str = hex(n)[2:]
    holes = {'0':1, '1':0, '2':0, '3':0, '4':1, '5':0, '6':1, '7':0, '8':2, '9':1, 'a':1, 'b':2, 'c':0, 'd':1, 'e':0, 'f':0}
    expected = sum(holes[ch] for ch in hex_str)
    output = run(x).strip()
    assert int(output) == expected

def test_non_negative(run, x):
    output = run(x).strip()
    val = int(output)
    assert val >= 0

def test_integer(run, x):
    output = run(x).strip()
    assert output.isdigit() and len(output) > 0

def test_bound_per_digits(run, x):
    n = int(x.strip())
    hex_len = len(hex(n)[2:])
    max_holes = 2 * hex_len
    output = int(run(x).strip())
    assert output <= max_holes

def test_zero(run, x):
    n = int(x.strip())
    output = run(x).strip()
    if n == 0:
        assert int(output) == 1

def test_example_11(run, x):
    output = run(x).strip()
    if x.strip() == "11":
        assert int(output) == 2

def test_example_14(run, x):
    output = run(x).strip()
    if x.strip() == "14":
        assert int(output) == 0

def test_example_61441(run, x):
    output = run(x).strip()
    if x.strip() == "61441":
        assert int(output) == 2

def test_power_of_16(run, x):
    n = int(x.strip())
    output = int(run(x).strip())
    if n > 0:
        temp = n
        exponent = 0
        while temp % 16 == 0:
            temp //= 16
            exponent += 1
        if temp == 1:
            assert output == exponent

def test_all_zero_hole(run, x):
    n = int(x.strip())
    hex_str = hex(n)[2:]
    zero_hole_digits = {'1','2','3','5','7','c','e','f'}
    output = int(run(x).strip())
    if all(ch in zero_hole_digits for ch in hex_str):
        assert output == 0

