def test_oracle(run, x):
    import sys
    from collections import deque
    lines = x.strip().splitlines()
    first = lines[0].split()
    n, m, s = map(int, first)
    s -= 1
    adj = [[] for _ in range(n)]
    radj = [[] for _ in range(n)]
    for i in range(1, m+1):
        u, v = map(int, lines[i].split())
        u -= 1; v -= 1
        adj[u].append(v)
        radj[v].append(u)
    visited = [False]*n
    order = []
    stack = []
    for i in range(n):
        if not visited[i]:
            stack.append(i)
            while stack:
                u = stack[-1]
                if not visited[u]:
                    visited[u] = True
                    for v in adj[u]:
                        if not visited[v]:
                            stack.append(v)
                else:
                    stack.pop()
                    order.append(u)
    visited = [False]*n
    scc_id = [-1]*n
    scc_count = 0
    for u in reversed(order):
        if not visited[u]:
            stack = [u]
            visited[u] = True
            scc_id[u] = scc_count
            while stack:
                cur = stack.pop()
                for v in radj[cur]:
                    if not visited[v]:
                        visited[v] = True
                        scc_id[v] = scc_count
                        stack.append(v)
            scc_count += 1
    cond_adj = [set() for _ in range(scc_count)]
    for u in range(n):
        for v in adj[u]:
            a = scc_id[u]; b = scc_id[v]
            if a != b:
                cond_adj[a].add(b)
    s_scc = scc_id[s]
    reachable = [False]*scc_count
    q = deque([s_scc])
    reachable[s_scc] = True
    while q:
        cur = q.popleft()
        for nxt in cond_adj[cur]:
            if not reachable[nxt]:
                reachable[nxt] = True
                q.append(nxt)
    indegree = [0]*scc_count
    for u in range(n):
        for v in adj[u]:
            a = scc_id[u]; b = scc_id[v]
            if a != b:
                indegree[b] += 1
    answer = 0
    for i in range(scc_count):
        if not reachable[i] and indegree[i] == 0:
            answer += 1
    output = run(x)
    out_val = int(output.strip())
    assert out_val == answer, f"Oracle expected {answer}, got {out_val}"


