    s -= 1
    edges = []
    for i in range(1, m+1):
        u, v = map(int, lines[i].split())
        u -= 1; v -= 1
        edges.append((u, v))
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
    visited = [False]*n
    q = deque([s])
    visited[s] = True
    while q:
        u = q.popleft()
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                q.append(v)
    unreachable = [i for i in range(n) if not visited[i]]
    undir = [[] for _ in range(n)]
    for u, v in edges:
        if not visited[u] and not visited[v]:
            undir[u].append(v)
            undir[v].append(u)
    comp_visited = [False]*n
    wcc = 0
    for u in unreachable:
        if not comp_visited[u]:
            wcc += 1
            stack = [u]
            comp_visited[u] = True
            while stack:
                cur = stack.pop()
                for nb in undir[cur]:
                    if not comp_visited[nb]:
                        comp_visited[nb] = True
                        stack.append(nb)
    output = run(x)
    val = int(output.strip())
    assert val >= wcc, f"Output {val} less than weak component count {wcc}"


