tests_src:
def test_direct_oracle(run, x):
    D, T, S = map(int, x.split())
    expected = "Yes\n" if D <= T * S else "No\n"
    assert run(x) == expected

def test_output_format(run, x):
    out = run(x)
    assert out in ("Yes\n", "No\n")

def test_no_extra_whitespace(run, x):
    out = run(x)
    stripped = out.rstrip("\n")
    assert stripped in ("Yes", "No")
    assert out == stripped + "\n"

def test_yes_implies_D_le_TS(run, x):
    D, T, S = map(int, x.split())
    out = run(x)
    if out.strip() == "Yes":
        assert D <= T * S

def test_no_implies_D_gt_TS(run, x):
    D, T, S = map(int, x.split())
    out = run(x)
    if out.strip() == "No":
        assert D > T * S

def test_equality_case(run, x):
    D, T, S = map(int, x.split())
    out = run(x)
    if D == T * S:
        assert out.strip() == "Yes"

def test_off_by_one_case(run, x):
    D, T, S = map(int, x.split())
    out = run(x)
    if D == T * S + 1:
        assert out.strip() == "No"

def test_capitalization(run, x):
    out = run(x)
    stripped = out.rstrip("\n")
    if stripped:
        assert stripped[0].isupper()
        assert stripped[1:].islower() or not stripped[1:]

def test_ends_with_newline(run, x):
    out = run(x)
    assert out.endswith("\n")

def test_single_line(run, x):
    out = run(x)
    lines = out.splitlines()
    assert len(lines) == 1
    assert lines[0] in ("Yes", "No")

def test_le_implies_yes(run, x):
    D, T, S = map(int, x.split())
    if D <= T * S:
        out = run(x).strip()
        assert out == "Yes"

def test_gt_implies_no(run, x):
    D, T, S = map(int, x.split())
    if D > T * S:
        out = run(x).strip()
        assert out == "No"

def test_yes_implies_le(run, x):
    D, T, S = map(int, x.split())
    out = run(x).strip()
    if out == "Yes":
        assert D <= T * S

def test_no_implies_gt(run, x):
    D, T, S = map(int, x.split())
    out = run(x).strip()
    if out == "No":
        assert D > T * S

def test_boundary_exact(run, x):
    D, T, S = map(int, x.split())
    if D == T * S:
        out = run(x).strip()
        assert out == "Yes"

def test_boundary_one_more(run, x):
    D, T, S = map(int, x.split())
    if D == T * S + 1:
        out = run(x).strip()
        assert out == "No"

def test_correct_by_ceil(run, x):
    D, T, S = map(int, x.split())
    need = (D + S - 1) // S
    expected = "Yes" if need <= T else "No"
    out = run(x).strip()
    assert out == expected

def test_output_shape(run, x):
    out = run(x).strip()
    assert out in {"Yes", "No"}

def test_small_inputs_oracle(run, x):
    D, T, S = map(int, x.split())
    if D <= 1000 and T <= 1000 and S <= 1000:
        expected = "Yes" if D <= T * S else "No"
        out = run(x).strip()
        assert out == expected

def test_positive_integers(run, x):
    D, T, S = map(int, x.split())
    out = run(x).strip()
    # The output must be Yes or No; no other strings allowed.
    assert out in {"Yes", "No"}
    # Additionally, if output is Yes, then D <= T*S must hold (already covered by test_yes_implies_le).
    # This test ensures the output is one of the two allowed strings, which is a direct requirement.

