tests_src:
def test_format(run, x):
    s = x.strip()
    if not (4 <= len(s) <= 10):
        return
    out = run(x)
    assert out in ("AC\n", "WA\n"), f"Invalid output: {repr(out)}"

def test_sample(run, x):
    if x != "AtCoder\n":
        return
    out = run(x)
    assert out == "AC\n", f"Sample should output AC, got {repr(out)}"

def test_first_letter_not_A_implies_WA(run, x):
    s = x.strip()
    if not (4 <= len(s) <= 10):
        return
    out = run(x)
    if s[0] != 'A':
        assert out == "WA\n", f"First letter not A but output is {out}"

def test_C_count_not_one_implies_WA(run, x):
    s = x.strip()
    if not (4 <= len(s) <= 10):
        return
    out = run(x)
    if s[2:-1].count('C') != 1:
        assert out == "WA\n", f"C count in range not 1 but output is {out}"

def test_extra_uppercase_implies_WA(run, x):
    s = x.strip()
    if not (4 <= len(s) <= 10):
        return
    out = run(x)
    if s[2:-1].count('C') == 1:
        c_idx = None
        for i in range(2, len(s)-1):
            if s[i] == 'C':
                c_idx = i
                break
        extra = False
        for i in range(len(s)):
            if i == 0 or i == c_idx:
                continue
            if s[i].isupper():
                extra = True
                break
        if extra:
            assert out == "WA\n", f"Extra uppercase but output is {out}"

def test_all_conditions_imply_AC(run, x):
    s = x.strip()
    if not (4 <= len(s) <= 10):
        return
    out = run(x)
    if s[0] == 'A':
        if s[2:-1].count('C') == 1:
            c_idx = None
            for i in range(2, len(s)-1):
                if s[i] == 'C':
                    c_idx = i
                    break
            all_lower = True
            for i in range(len(s)):
                if i == 0 or i == c_idx:
                    continue
                if not s[i].islower():
                    all_lower = False
                    break
            if all_lower:
                assert out == "AC\n", f"All conditions hold but output is {out}"

def test_AC_implies_first_A(run, x):
    s = x.strip()
    if not (4 <= len(s) <= 10):
        return
    out = run(x)
    if out == "AC\n":
        assert s[0] == 'A', f"Output AC but first letter is not A"

def test_AC_implies_exactly_one_C_in_range(run, x):
    s = x.strip()
    if not (4 <= len(s) <= 10):
        return
    out = run(x)
    if out == "AC\n":
        assert s[2:-1].count('C') == 1, f"Output AC but C count in range is not 1"

def test_AC_implies_no_extra_uppercase(run, x):
    s = x.strip()
    if not (4 <= len(s) <= 10):
        return
    out = run(x)
    if out == "AC\n":
        assert s[2:-1].count('C') == 1, "Output AC but C count not 1"
        c_idx = None
        for i in range(2, len(s)-1):
            if s[i] == 'C':
                c_idx = i
                break
        for i in range(len(s)):
            if i == 0 or i == c_idx:
                continue
            if s[i].isupper():
                assert False, f"Output AC but extra uppercase at index {i}"

def test_reference(run, x):
    s = x.strip()
    if not (4 <= len(s) <= 10):
        return
    correct = "WA\n"
    if s[0] == 'A':
        if s[2:-1].count('C') == 1:
            c_idx = None
            for i in range(2, len(s)-1):
                if s[i] == 'C':
                    c_idx = i
                    break
            ok = True
            for i in range(len(s)):
                if i == 0 or i == c_idx:
                    continue
                if not s[i].islower():
                    ok = False
                    break
            if ok:
                correct = "AC\n"
    out = run(x)
    assert out == correct, f"Output {out} expected {correct}"

