def test_brute_force_oracle(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    try:
        N = int(lines[0].strip())
    except:
        return
    if not (2 <= N <= 50):
        return
    parts = lines[1].split()
    if len(parts) != N:
        return
    try:
        p = [int(part) for part in parts]
    except:
        return
    if set(p) != set(range(1, N+1)):
        return
    sorted_p = list(range(1, N+1))
    if p == sorted_p:
        correct = 'YES'
    else:
        sortable = False
        for i in range(N):
            for j in range(i+1, N):
                p[i], p[j] = p[j], p[i]
                if p == sorted_p:
                    sortable = True
                    p[i], p[j] = p[j], p[i]
                    break
                p[i], p[j] = p[j], p[i]
            if sortable:
                break
        correct = 'YES' if sortable else 'NO'
    output = run(x)
    if output.strip() != correct.strip():
