tests_src:
def test_output_format(run, x):
    out = run(x).strip()
    try:
        val = int(out)
    except ValueError:
        assert False, 'Output not an integer'
    assert 0 <= val <= 2018, f'Output {val} not in [0,2018]'

def test_zero_when_L_is_zero(run, x):
    L, R = map(int, x.strip().split())
    if L == 0:
        out = run(x).strip()
        assert out == '0', f'When L=0, expected 0 got {out}'

def test_zero_when_multiple_of_2019_exists(run, x):
    L, R = map(int, x.strip().split())
    first_multiple = ((L + 2018) // 2019) * 2019
    if first_multiple <= R:
        out = run(x).strip()
        assert out == '0', f'Multiple of 2019 present, expected 0 got {out}'

def test_zero_when_range_length_ge_2019(run, x):
    L, R = map(int, x.strip().split())
    if R - L + 1 >= 2019:
        out = run(x).strip()
        assert out == '0', f'Range length >=2019, expected 0 got {out}'

def test_small_range_bruteforce_oracle(run, x):
    L, R = map(int, x.strip().split())
    size = R - L + 1
    if size <= 2000:
        ans = 2019
        for i in range(L, R+1):
            for j in range(i+1, R+1):
                val = (i * j) % 2019
                if val < ans:
                    ans = val
        out = run(x).strip()
        assert int(out) == ans, f'For small range, expected {ans} got {out}'

def test_non_zero_consistency(run, x):
    L, R = map(int, x.strip().split())
    out = run(x).strip()
    val = int(out)
    if val != 0:
        first_multiple = ((L + 2018) // 2019) * 2019
        assert first_multiple > R, f'Output non-zero but multiple {first_multiple} exists'
        assert R - L + 1 < 2019, f'Output non-zero but range length {R-L+1} >= 2019'

def test_specific_input_2020_2021(run, x):
    if x == '2020 2021\n':
        out = run(x).strip()
        assert out == '2', f"For input '2020 2021', expected 2 got {out}"

def test_consecutive_pair(run, x):
    L, R = map(int, x.strip().split())
    if R == L + 1:
        out = run(x).strip()
        expected = (L * R) % 2019
        assert int(out) == expected, f'Consecutive pair: expected {expected}, got {out}'

def test_sample_input(run, x):
    if x == '2020 2040\n':
        out = run(x).strip()
        assert out == '2', f"Sample input 2020 2040: expected 2, got {out}"

def test_specific_input_2_2018(run, x):
    if x == '2 2018\n':
        L, R = 2, 2018
        ans = 2019
        for i in range(L, R+1):
            for j in range(i+1, R+1):
                val = (i * j) % 2019
                if val < ans:
                    ans = val
        out = run(x).strip()
        assert int(out) == ans, f'For input 2 2018, expected {ans}, got {out}'

