def test_exact_mst(run, x):
    import sys
    lines = [line.strip() for line in x.strip().splitlines() if line.strip()]
    if not lines:
        return
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    offers = []
    for i in range(m):
        x_i, y_i, w_i = map(int, lines[2 + i].split())
        offers.append((x_i - 1, y_i - 1, w_i))
    min_a = min(a)
    min_idx = a.index(min_a)
    edges = []
    for i in range(n):
        if i != min_idx:
            edges.append((a[i] + min_a, i, min_idx))
    for x_i, y_i, w_i in offers:
        edges.append((w_i, x_i, y_i))
    edges.sort()
    parent = list(range(n))
    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u
    def union(u, v):
        ru, rv = find(u), find(v)
        if ru != rv:
            parent[rv] = ru
            return True
        return False
    total = 0
    used = 0
    for cost, u, v in edges:
        if union(u, v):
            total += cost
            used += 1
            if used == n - 1:
                break
    if n == 1:
        total = 0
    ans = int(run(x).strip())
    assert ans == total, f"Expected {total}, got {ans}"

def test_n1_zero(run, x):
    lines = x.strip().splitlines()
    if not lines:
        return
    first = lines[0].strip().split()
    if not first:
        return
    n = int(first[0])
    if n == 1:
        ans = int(run(x).strip())
        assert ans == 0, f"For n=1 expected 0, got {ans}"

def test_n2_min_edge(run, x):
    lines = [line.strip() for line in x.strip().splitlines() if line.strip()]
    if len(lines) < 1:
        return
    n, m = map(int, lines[0].split())
    if n != 2:
        return
    a = list(map(int, lines[1].split()))
    min_cost = a[0] + a[1]
    for i in range(m):
        x_i, y_i, w_i = map(int, lines[2 + i].split())
        if (x_i == 1 and y_i == 2) or (x_i == 2 and y_i == 1):
            if w_i < min_cost:
                min_cost = w_i
    ans = int(run(x).strip())
    assert ans == min_cost, f"For n=2 expected {min_cost}, got {ans}"

def test_m0_formula(run, x):
    lines = [line.strip() for line in x.strip().splitlines() if line.strip()]
    if not lines:
        return
    n, m = map(int, lines[0].split())
    if m != 0:
        return
    a = list(map(int, lines[1].split()))
    min_a = min(a)
    total = sum(a) + (n - 2) * min_a
    ans = int(run(x).strip())
    assert ans == total, f"For m=0 expected {total}, got {ans}"

def test_upper_bound(run, x):
    lines = [line.strip() for line in x.strip().splitlines() if line.strip()]
    if not lines:
        return
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    min_a = min(a)
    upper = sum(a) + (n - 2) * min_a
    ans = int(run(x).strip())
    assert ans <= upper, f"Answer {ans} exceeds upper bound {upper}"

def test_lower_bound_n_minus_1(run, x):
    lines = [line.strip() for line in x.strip().splitlines() if line.strip()]
    if not lines:
        return
    n, m = map(int, lines[0].split())
    if n < 2:
        return
    ans = int(run(x).strip())
    assert ans >= n - 1, f"Answer {ans} below lower bound {n-1}"

def test_nonnegative(run, x):
    output = run(x).strip()
    ans = int(output)
    assert ans >= 0, f"Answer negative: {ans}"

def test_useless_offers(run, x):
    lines = [line.strip() for line in x.strip().splitlines() if line.strip()]
    if not lines:
        return
    n, m = map(int, lines[0].split())
    if m == 0:
        return
    a = list(map(int, lines[1].split()))
    useless = True
    for i in range(m):
        x_i, y_i, w_i = map(int, lines[2 + i].split())
        if w_i < a[x_i - 1] + a[y_i - 1]:
            useless = False
            break
    if useless:
        min_a = min(a)
        expected = sum(a) + (n - 2) * min_a
        ans = int(run(x).strip())
        assert ans == expected, f"With useless offers expected {expected}, got {ans}"

def test_examples(run, x):
    examples = [
        ("3 2\n1 3 3\n2 3 5\n2 1 1\n", 5),
        ("4 0\n1 3 3 7\n", 16),
        ("5 4\n1 2 3 4 5\n1 2 8\n1 3 10\n1 4 7\n1 5 15\n", 18)
    ]
    for inp, exp in examples:
        if x.rstrip('\n') == inp.rstrip('\n'):
            ans = int(run(x).strip())
            assert ans == exp, f"Example input expected {exp}, got {ans}"
            return

def test_output_format(run, x):
    import re
    output = run(x)
    if output.endswith('\n'):
        output = output[:-1]
    assert re.fullmatch(r'\d+', output), f"Output '{output}' is not a nonnegative integer or contains invalid characters"

