    def decompose(seq):
        lengths = []
        cur_len = 0
        for num in seq:
            if num == 1:
                if cur_len > 0:
                    lengths.append(cur_len)
                cur_len = 1
            else:
                if cur_len == 0:
                    return None
                if num != cur_len + 1:
                    return None
                cur_len = num
        if cur_len > 0:
            lengths.append(cur_len)
        return lengths
