def test_output_le_1e6(run, x):
    out = run(x)
    m = int(out.strip())
    assert m <= 1000000

def test_output_format(run, x):
    out = run(x)
    s = out.strip()
    assert s.isdigit()

def test_samples(run, x):
    s_val = int(x.strip())
    out = run(x)
    m = int(out.strip())
    if s_val == 1:
        assert m == 4
    elif s_val == 2:
        assert m == 4
    elif s_val == 8:
        assert m == 5

def test_minimal_m(run, x):
    s_val = int(x.strip())
    out = run(x)
    m = int(out.strip())
    seen = {s_val: 1}
    a = s_val
    i = 2
    while True:
        if a % 2 == 0:
            a = a // 2
        else:
            a = 3 * a + 1
        if a in seen:
