        u, v = map(int, data[i].split())
        adj[u].append(v)
        adj[v].append(u)
    visited = [False] * (n + 1)
    cycles = 0
    for v in range(1, n + 1):
        if not visited[v]:
            stack = [v]
            comp = []
            while stack:
                u = stack.pop()
                if visited[u]:
                    continue
                visited[u] = True
                comp.append(u)
                for w in adj[u]:
                    if not visited[w]:
                        stack.append(w)
            if len(comp) >= 3 and all(len(adj[node]) == 2 for node in comp):
                cycles += 1
    out = run(x)
    assert int(out.strip()) == cycles

