tests_src:
def test_output_is_integer(run, x):
    output = run(x).strip()
    assert output.isdigit()

def test_output_range(run, x):
    output = run(x).strip()
    n = int(output)
    assert 0 <= n <= 3

def test_no_R_gives_zero(run, x):
    S = x.strip()
    output = run(x).strip()
    if 'R' not in S:
        assert int(output) == 0

def test_any_R_gives_at_least_one(run, x):
    S = x.strip()
    output = run(x).strip()
    if 'R' in S:
        assert int(output) >= 1

def test_all_R_gives_three(run, x):
    S = x.strip()
    output = run(x).strip()
    if S == 'RRR':
        assert int(output) == 3

def test_RR_substring_gives_at_least_two(run, x):
    S = x.strip()
    output = run(x).strip()
    if 'RR' in S:
        assert int(output) >= 2

def test_output_not_exceed_total_R(run, x):
    S = x.strip()
    output = run(x).strip()
    total_R = S.count('R')
    assert int(output) <= total_R

def test_exact_oracle(run, x):
    S = x.strip()
    output = run(x).strip()
    max_len = 0
    cur = 0
    for ch in S:
        if ch == 'R':
            cur += 1
            if cur > max_len:
                max_len = cur
        else:
            cur = 0
    expected = max_len
    assert int(output) == expected

def test_output_two_implies_RR_and_not_RRR(run, x):
    S = x.strip()
    output = run(x).strip()
    if int(output) == 2:
        assert 'RR' in S
        assert 'RRR' not in S

def test_output_one_implies_no_RR_and_some_R(run, x):
    S = x.strip()
    output = run(x).strip()
    if int(output) == 1:
        assert 'RR' not in S
        assert 'R' in S

