def test_parse(run, x):
    out = run(x)
    tokens = out.split()
    assert tokens, "output is empty"
    try:
        n = int(tokens[0])
    except ValueError:
        assert False, "first token not integer"
    assert len(tokens) == 1 + n, "token count mismatch"
    for tok in tokens[1:]:
        try:
            int(tok)
        except ValueError:
            assert False, "non-integer token"


def test_n_nonnegative(run, x):
    out = run(x)
    tokens = out.split()
    assert tokens, "output is empty"
    try:
        n = int(tokens[0])
    except ValueError:
        assert False, "first token not integer"
    assert n >= 0, "negative count"


def test_n_at_most_81(run, x):
    out = run(x)
    tokens = out.split()
    assert tokens, "output is empty"
    try:
        n = int(tokens[0])
    except ValueError:
        assert False, "first token not integer"
    assert n <= 81, "count exceeds maximum possible solutions"


def test_numbers_in_range(run, x):
    out = run(x)
    tokens = out.split()
    assert tokens, "output is empty"
    try:
        n = int(tokens[0])
    except ValueError:
        assert False, "first token not integer"
    numbers = tokens[1:]
    assert len(numbers) == n, "number count mismatch"
    for tok in numbers:
        try:
            val = int(tok)
        except ValueError:
            assert False, "non-integer token"
        assert 0 < val < 10**9, "solution out of range"


def test_strictly_increasing(run, x):
    out = run(x)
    tokens = out.split()
    assert tokens, "output is empty"
    try:
        n = int(tokens[0])
    except ValueError:
        assert False, "first token not integer"
    numbers = tokens[1:1+n]
    prev = None
    for tok in numbers:
        try:
            val = int(tok)
        except ValueError:
            assert False, "non-integer token"
        if prev is not None:
            assert val > prev, "solutions not in increasing order"
        prev = val


def test_no_duplicates(run, x):
    out = run(x)
    tokens = out.split()
    assert tokens, "output is empty"
    try:
        n = int(tokens[0])
    except ValueError:
        assert False, "first token not integer"
    numbers = tokens[1:1+n]
    vals = []
    for tok in numbers:
        try:
            vals.append(int(tok))
        except ValueError:
            assert False, "non-integer token"
    assert len(set(vals)) == len(vals), "duplicate solutions found"


def test_satisfy_equation(run, x):
    a, b, c = map(int, x.strip().split())
    out = run(x)
    tokens = out.split()
    assert tokens, "output is empty"
    try:
        n = int(tokens[0])
    except ValueError:
        assert False, "first token not integer"
    numbers = tokens[1:1+n]
    for tok in numbers:
        try:
            x_val = int(tok)
        except ValueError:
            assert False, "non-integer token"
        s = sum(int(d) for d in str(x_val))
        assert x_val == b * (s ** a) + c, "equation not satisfied"


def test_complete_solution(run, x):
    a, b, c = map(int, x.strip().split())
    out = run(x)
    tokens = out.split()
    assert tokens, "output is empty"
    try:
        n = int(tokens[0])
    except ValueError:
        assert False, "first token not integer"
    numbers = set()
    for tok in tokens[1:1+n]:
        try:
            numbers.add(int(tok))
        except ValueError:
            assert False, "non-integer token"
    correct = set()
    for s in range(1, 82):
        x_val = b * (s ** a) + c
        if 0 < x_val < 10**9:
            if sum(int(d) for d in str(x_val)) == s:
                correct.add(x_val)
    assert numbers == correct, "solutions mismatch"


def test_count_matches(run, x):
    out = run(x)
    tokens = out.split()
    assert tokens, "output is empty"
    try:
        n = int(tokens[0])
    except ValueError:
        assert False, "first token not integer"
    numbers = tokens[1:]
    assert len(numbers) == n, "count does not match number of solutions"


def test_digit_sum_range(run, x):
    out = run(x)
    tokens = out.split()
    assert tokens, "output is empty"
    try:
        n = int(tokens[0])
    except ValueError:
        assert False, "first token not integer"
    numbers = tokens[1:1+n]
    for tok in numbers:
        try:
            x_val = int(tok)
        except ValueError:
            assert False, "non-integer token"
        s = sum(int(d) for d in str(x_val))
        assert 1 <= s <= 81, "digit sum out of range"

