def test_output_format(run, x):
    out = run(x)
    cleaned = out.strip()
    assert cleaned == "Yes" or cleaned == "No"

def test_sorted_s_less_sorted_t_implies_yes(run, x):
    out = run(x).strip()
    lines = x.strip().splitlines()
    if len(lines) >= 2:
        s = lines[0].strip()
        t = lines[1].strip()
        if sorted(s) < sorted(t):
            assert out == "Yes"

def test_sorted_s_greater_sorted_t_reverse_implies_no(run, x):
    out = run(x).strip()
    lines = x.strip().splitlines()
    if len(lines) >= 2:
        s = lines[0].strip()
        t = lines[1].strip()
        if sorted(s) > sorted(t, reverse=True):
            assert out == "No"

def test_same_multiset_not_all_same_implies_yes(run, x):
    out = run(x).strip()
    lines = x.strip().splitlines()
    if len(lines) >= 2:
        s = lines[0].strip()
        t = lines[1].strip()
        if sorted(s) == sorted(t):
            if len(set(s)) > 1:
                assert out == "Yes"

def test_single_chars(run, x):
    out = run(x).strip()
    lines = x.strip().splitlines()
    if len(lines) >= 2:
        s = lines[0].strip()
        t = lines[1].strip()
        if len(s) == 1 and len(t) == 1:
            expected = "Yes" if s < t else "No"
            assert out == expected

def test_all_a_all_a(run, x):
    out = run(x).strip()
    lines = x.strip().splitlines()
    if len(lines) >= 2:
        s = lines[0].strip()
        t = lines[1].strip()
        if all(c == 'a' for c in s) and all(c == 'a' for c in t):
            expected = "Yes" if len(s) < len(t) else "No"
            assert out == expected

def test_all_z_all_a(run, x):
    out = run(x).strip()
    lines = x.strip().splitlines()
    if len(lines) >= 2:
        s = lines[0].strip()
        t = lines[1].strip()
        if all(c == 'z' for c in s) and all(c == 'a' for c in t):
            assert out == "No"

def test_all_a_all_b(run, x):
    out = run(x).strip()
    lines = x.strip().splitlines()
    if len(lines) >= 2:
        s = lines[0].strip()
        t = lines[1].strip()
        if all(c == 'a' for c in s) and all(c == 'b' for c in t):
