tests_src:
def test_brute_force(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    s = lines[1].strip()
    z = list(map(int, lines[2].split()))
    best = None
    for i in range(n):
        for j in range(i+1, n):
            if s[i] == 'R' and s[j] == 'L':
                t = (z[j] - z[i]) // 2
                if best is None or t < best:
                    best = t
    correct = -1 if best is None else best
    out = run(x).strip()
    assert out.isdigit() or (out[0] == '-' and out[1:].isdigit())
    ans = int(out)
    assert ans == correct

def test_output_integer(run, x):
    out = run(x).strip()
    assert out.isdigit() or (out[0] == '-' and out[1:].isdigit())

def test_output_ge_minus_one(run, x):
    out = run(x).strip()
    assert out.isdigit() or out == '-1'
    ans = int(out)
    assert ans >= -1

def test_output_not_zero(run, x):
    out = run(x).strip()
    assert out != '0'
    assert out != '-0'

def test_minus_one_implies_no_RL(run, x):
    out = run(x).strip()
    if out == '-1':
        lines = x.strip().split('\n')
        n = int(lines[0])
        s = lines[1].strip()
        has_RL = False
        for i in range(n):
            for j in range(i+1, n):
                if s[i] == 'R' and s[j] == 'L':
                    has_RL = True
                    break
            if has_RL:
                break
        assert not has_RL

def test_positive_implies_exists_RL(run, x):
    out = run(x).strip()
    if out.isdigit() and int(out) > 0:
        lines = x.strip().split('\n')
        n = int(lines[0])
        s = lines[1].strip()
        has_RL = False
        for i in range(n):
            for j in range(i+1, n):
                if s[i] == 'R' and s[j] == 'L':
                    has_RL = True
                    break
            if has_RL:
                break
        assert has_RL

def test_output_equals_min_adjacent_if_any(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    s = lines[1].strip()
    z = list(map(int, lines[2].split()))
    min_adj = None
    for i in range(n-1):
        if s[i] == 'R' and s[i+1] == 'L':
            t = (z[i+1] - z[i]) // 2
            if min_adj is None or t < min_adj:
                min_adj = t
    correct = -1 if min_adj is None else min_adj
    out = run(x).strip()
    assert out.isdigit() or out == '-1'
    ans = int(out)
    assert ans == correct

def test_output_le_all_RL_pairs(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    s = lines[1].strip()
    z = list(map(int, lines[2].split()))
    out = run(x).strip()
    assert out.isdigit() or out == '-1'
    ans = int(out)
    if ans > 0:
        for i in range(n):
            for j in range(i+1, n):
                if s[i] == 'R' and s[j] == 'L':
                    t = (z[j] - z[i]) // 2
                    assert ans <= t

def test_output_format_single_line(run, x):
    out = run(x)
    lines = out.splitlines()
    assert len(lines) == 1 or (len(lines) == 2 and lines[1] == '')
    line = lines[0]
    assert line.isdigit() or (line[0] == '-' and line[1:].isdigit())

def test_output_le_max_possible_time(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    z = list(map(int, lines[2].split()))
    if n >= 2:
        max_time = (z[-1] - z[0]) // 2
    else:
        max_time = 0
    out = run(x).strip()
    if out != '-1':
        ans = int(out)
        assert ans <= max_time

