def test_dp(run, x):
    n, m, k = map(int, x.strip().split())
    if not (1 <= n <= 2000 and 1 <= m <= 2000 and 0 <= k <= n-1):
        return
    MOD = 998244353
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    dp[1][0] = m % MOD
    for i in range(2, n + 1):
        for j in range(0, min(k, i - 1) + 1):
            val = dp[i - 1][j]
            if j > 0:
                val = (val + dp[i - 1][j - 1] * (m - 1)) % MOD
            dp[i][j] = val
    expected = dp[n][k] % MOD
    out = int(run(x).strip())
    assert out == expected

def test_formula(run, x):
    n, m, k = map(int, x.strip().split())
    if not (1 <= n <= 2000 and 1 <= m <= 2000 and 0 <= k <= n-1):
        return
    MOD = 998244353
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD
    def nCr(nn, rr):
        if rr < 0 or rr > nn:
            return 0
        return fact[nn] * pow(fact[rr], MOD - 2, MOD) % MOD * pow(fact[nn - rr], MOD - 2, MOD) % MOD
    binom = nCr(n - 1, k)
    expected = m % MOD * pow(m - 1, k, MOD) % MOD * binom % MOD
    out = int(run(x).strip())
    assert out == expected

def test_small_bruteforce(run, x):
    n, m, k = map(int, x.strip().split())
    if not (1 <= n <= 2000 and 1 <= m <= 2000 and 0 <= k <= n-1):
        return
    out_str = run(x)
    if n > 8 or m > 5:
        return
    MOD = 998244353
    import itertools
    colors = range(m)
    total = 0
    for seq in itertools.product(colors, repeat=n):
        changes = sum(1 for i in range(1, n) if seq[i] != seq[i - 1])
        if changes == k:
            total += 1
    expected = total % MOD
    out = int(out_str.strip())
    assert out == expected

