def test_brute_force(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    s = lines[1].strip()
    z = list(map(int, lines[2].split()))
    best = None
    for i in range(n):
        for j in range(i+1, n):
            if s[i] == 'R' and s[j] == 'L':
                d = z[j] - z[i]
                t = d // 2
                if best is None or t < best:
                    best = t
    correct = -1 if best is None else best
    output = run(x).strip()
    assert output == str(correct)

def test_output_integer(run, x):
    output = run(x).strip()
    assert output != ''
    int(output)

def test_minus1_only_if_no_RL(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    s = lines[1].strip()
    output = run(x).strip()
    if output == '-1':
        has_RL = False
        for i in range(n):
            for j in range(i+1, n):
                if s[i] == 'R' and s[j] == 'L':
                    has_RL = True
                    break
            if has_RL:
                break
        assert not has_RL

def test_not_minus1_if_RL_exists(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    s = lines[1].strip()
    output = run(x).strip()
    has_RL = False
    for i in range(n):
        for j in range(i+1, n):
            if s[i] == 'R' and s[j] == 'L':
                has_RL = True
                break
        if has_RL:
            break
    if has_RL:
        assert output != '-1'

def test_equals_min_adjacent(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    s = lines[1].strip()
    z = list(map(int, lines[2].split()))
    output = run(x).strip()
    t = int(output)
    best_adj = None
    for i in range(n-1):
        if s[i] == 'R' and s[i+1] == 'L':
            d = z[i+1] - z[i]
            time = d // 2
            if best_adj is None or time < best_adj:
                best_adj = time
    if best_adj is None:
        assert t == -1
    else:
        assert t == best_adj

def test_positive_if_not_minus1(run, x):
    output = run(x).strip()
    if output != '-1':
        t = int(output)
        assert t >= 1

def test_le_all_RL_times(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    s = lines[1].strip()
    z = list(map(int, lines[2].split()))
    output = run(x).strip()
    t = int(output)
    if t != -1:
        for i in range(n):
            for j in range(i+1, n):
                if s[i] == 'R' and s[j] == 'L':
                    d = z[j] - z[i]
                    coll_time = d // 2
                    assert t <= coll_time

