def test_exact_answer(run, x):
    def solve_correct(inp):
        lines = inp.strip().splitlines()
        first = lines[0].split()
        n, m, k = int(first[0]), int(first[1]), int(first[2])
        grid = [list(line.strip()) for line in lines[1:1+n]]
        start = None
        for i in range(n):
            for j in range(m):
                if grid[i][j] == 'X':
                    start = (i, j)
                    break
            if start:
                break
        from collections import deque
        dp = [[[False]*m for _ in range(n)] for __ in range(k+1)]
        dp[0][start[0]][start[1]] = True
        for step in range(1, k+1):
            for i in range(n):
                for j in range(m):
                    if grid[i][j] == '*':
                        continue
                    for di, dj in [(1,0),(-1,0),(0,1),(0,-1)]:
                        ni, nj = i+di, j+dj
                        if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] != '*':
                            if dp[step-1][ni][nj]:
                                dp[step][i][j] = True
                                break
        if not dp[k][start[0]][start[1]]:
            return 'IMPOSSIBLE'
        path = []
        cur = start
        remaining = k
        dir_order = [('D',1,0), ('L',0,-1), ('R',0,1), ('U',-1,0)]
        while remaining > 0:
            chosen = None
            for dir_char, di, dj in dir_order:
                ni, nj = cur[0]+di, cur[1]+dj
                if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] != '*':
                    if dp[remaining-1][ni][nj]:
                        chosen = dir_char
                        cur = (ni, nj)
                        break
            assert chosen is not None
            path.append(chosen)
            remaining -= 1
        return ''.join(path)
    correct = solve_correct(x)
    out = run(x).strip()
    assert out == correct

