def test_integer_output(run, x):
    out = run(x).strip()
    try:
        int(out)
    except ValueError:
        assert False, "Output is not an integer"

def test_arithmetic_correct(run, x):
    a,b,c,d = map(int, x.strip().split())
    if b - a == c - b == d - c:
        next_term = d + (b - a)
        out = run(x).strip()
        assert out == str(next_term), f"Arithmetic progression next term should be {next_term}, got {out}"

def test_geometric_correct(run, x):
    a,b,c,d = map(int, x.strip().split())
    if a == 0 or b == 0:
        return
    if a*c == b*b and b*d == c*c:
        num = d * b
        den = a
        if num % den == 0:
            next_term = num // den
            out = run(x).strip()
            assert out == str(next_term), f"Geometric progression next term should be {next_term}, got {out}"

def test_neither_42(run, x):
    a,b,c,d = map(int, x.strip().split())
    if b - a == c - b == d - c:
        return
    if a != 0 and b != 0:
        if a*c == b*b and b*d == c*c:
            num = d * b
            den = a
            if num % den == 0:
                return
    out = run(x).strip()
    assert out == "42", f"Sequence is neither arithmetic nor geometric, should output 42, got {out}"

def test_correct_answer(run, x):
    def correct_answer(a,b,c,d):
        if b - a == c - b == d - c:
            return d + (b - a)
        if a == 0 or b == 0:
            return 42
        if a*c == b*b and b*d == c*c:
            num = d * b
            den = a
            if num % den == 0:
                return num // den
            else:
                return 42
        return 42
    a,b,c,d = map(int, x.strip().split())
    expected = correct_answer(a,b,c,d)
    out = run(x).strip()
    assert out == str(expected), f"Expected {expected}, got {out}"

def test_zero_not_arithmetic_42(run, x):
    a,b,c,d = map(int, x.strip().split())
    if a == b == c == d == 0:
        return
    if (a == 0 or b == 0 or c == 0 or d == 0):
        if b - a == c - b == d - c:
            return
        out = run(x).strip()
        assert out == "42", f"Sequence contains zero and is not arithmetic, should output 42, got {out}"

def test_constant_sequence(run, x):
    a,b,c,d = map(int, x.strip().split())
    if a == b == c == d:
        out = run(x).strip()
        assert out == str(a), f"Constant sequence should output {a}, got {out}"

def test_geometric_ratio_consistent(run, x):
    a,b,c,d = map(int, x.strip().split())
    if a == 0 or b == 0:
        return
    if a*c != b*b or b*d != c*c:
        return
    out = run(x).strip()
    out_val = int(out)
    assert out_val * a == d * b, f"Geometric progression: next * a should equal d * b"

def test_geometric_sign_consistent(run, x):
    a,b,c,d = map(int, x.strip().split())
    if a == 0 or b == 0:
        return
    if a*c != b*b or b*d != c*c:
        return
    out = run(x).strip()
    out_val = int(out)
    ratio_positive = (a * b > 0)
    assert (out_val * d > 0) == ratio_positive, f"Geometric progression: sign of next term inconsistent with ratio sign"

def test_provided_example(run, x):
    if x.strip() == "1 334 667 1000":
        out = run(x).strip()
        assert out == "1333", f"For example input, expected 1333, got {out}"

