def test_exact_dp(run, x):
    import sys
    lines = x.strip().split()
    if len(lines) < 3:
        return
    n = int(lines[0])
    a = int(lines[1])
    b = int(lines[2])
    sizes = [a]*4 + [b]*2
    from itertools import product
    found = False
    for k in range(1, 7):
        for assignment in product(range(k), repeat=6):
            bins = [0]*k
            ok = True
            for idx, bin_idx in enumerate(assignment):
                bins[bin_idx] += sizes[idx]
                if bins[bin_idx] > n:
                    ok = False
                    break
            if ok:
                found = True
                break
        if found:
            break
    optimal = k if found else 6
    out = run(x).strip()
    assert out.isdigit()
    assert int(out) == optimal

def test_lower_bound(run, x):
    lines = x.strip().split()
    if len(lines) < 3:
        return
    n = int(lines[0])
    a = int(lines[1])
    b = int(lines[2])
    out = run(x).strip()
    assert out.isdigit()
    ans = int(out)
    total = 4*a + 2*b
    import math
    lower = (total + n - 1) // n
    assert ans >= lower

def test_upper_bound(run, x):
    out = run(x).strip()
    assert out.isdigit()
    ans = int(out)
    assert ans <= 6

def test_total_length_fits_one_bar(run, x):
    lines = x.strip().split()
    if len(lines) < 3:
        return
    n = int(lines[0])
    a = int(lines[1])
    b = int(lines[2])
    if n >= 4*a + 2*b:
        out = run(x).strip()
        assert out == '1'

