            right = 10**6 - a[i] if i < n else 0
            min_max = min(min_max, max(left, right))
        return min_max <= T
    lo, hi = 0, 10**6
    while lo < hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            hi = mid
        else:
            lo = mid + 1
