def test_formula(run, x):
    s = x.strip()
    letters = set(ch for ch in s if 'A' <= ch <= 'J')
    L = len(letters)
    q = s.count('?')
    first = s[0]
    # helper for permutations
    def perm(n, k):
        res = 1
        for i in range(k):
            res *= n - i
        return res
    # letter assignments
    if first in letters:
        if L == 0:
            letter_assign = 1
        else:
            letter_assign = 9 * perm(9, L-1)
    else:
        letter_assign = perm(10, L)
    # question factor
    if q == 0:
        factor_q = 1
    else:
        if first == '?':
            factor_q = 9 * (10 ** (q - 1))
        else:
            factor_q = 10 ** q
    correct = letter_assign * factor_q
    out = run(x).strip()
    assert out.isdigit()
    assert int(out) == correct

def test_small_bruteforce(run, x):
    s = x.strip()
    if len(s) > 5:
        return
    from itertools import product
    count = 0
    for digits in product('0123456789', repeat=len(s)):
        if digits[0] == '0':
            continue
        ok = True
        letter_map = {}
        for i, ch in enumerate(s):
            if ch == '?':
                continue
            elif '0' <= ch <= '9':
                if digits[i] != ch:
                    ok = False
                    break
            else:
                if ch not in letter_map:
                    letter_map[ch] = digits[i]
                elif letter_map[ch] != digits[i]:
                    ok = False
                    break
        if len(set(letter_map.values())) != len(letter_map):
            ok = False
        if ok:
            count += 1
    out = run(x).strip()
    assert out.isdigit()
    assert int(out) == count

def test_output_integer(run, x):
    out = run(x).strip()
    assert out.isdigit()
    val = int(out)
    assert val >= 0
    if len(out) > 1:
        assert out[0] != '0'

def test_first_char_letter_divisibility(run, x):
    s = x.strip()
    if s[0] in 'ABCDEFGHIJ':
        out = run(x).strip()
        val = int(out)
        assert val % 9 == 0

def test_question_marks_divisibility(run, x):
    s = x.strip()
    q_rest = s.count('?')
    if s[0] == '?':
        q_rest -= 1
    if q_rest > 0:
        out = run(x).strip()
        val = int(out)
        assert val % (10 ** q_rest) == 0

def test_no_letters_no_question(run, x):
    s = x.strip()
    if all(ch in '0123456789' for ch in s):
        out = run(x).strip()
        assert out == '1'

def test_length_one(run, x):
    s = x.strip()
    if len(s) != 1:
        return
    out = run(x).strip()
    if s[0] in '0123456789':
        assert out == '1'
    elif s[0] in 'ABCDEFGHIJ':
        assert out == '9'
    elif s[0] == '?':
        assert out == '9'

def test_only_letters_distinct(run, x):
    s = x.strip()
    if all('A' <= ch <= 'J' for ch in s):
        if len(set(s)) == len(s):
            L = len(s)
            def perm(n, k):
                res = 1
                for i in range(k):
                    res *= n - i
                return res
            if L == 0:
                correct = 1
            else:
                correct = 9 * perm(9, L-1)
            out = run(x).strip()
            assert int(out) == correct

def test_letter_count_bound(run, x):
    s = x.strip()
    n = len(s)
    import math
    bound = 9 * (10 ** (n-1)) * math.factorial(10)
    out = run(x).strip()
    val = int(out)
    assert val <= bound

def test_upper_bound(run, x):
    s = x.strip()
    n = len(s)
    out = run(x).strip()
    assert out.isdigit()
    if out == '0':
        return
    bound_str = '9' + '0' * (n - 1)
    if len(out) > n:
        assert False, 'output length exceeds n'
    elif len(out) == n:
        assert out <= bound_str, 'output exceeds 9*10^(n-1)'

