def test_brute_force_small(run, x):
    s = x.strip()
    if len(s) > 6:
        return
    from itertools import product
    digits = '0123456789'
    count = 0
    for seq in product(digits, repeat=len(s)):
        if seq[0] == '0':
            continue
        ok = True
        letter_map = {}
        for i, ch in enumerate(s):
            if ch == '?':
                continue
            elif '0' <= ch <= '9':
                if seq[i] != ch:
                    ok = False
                    break
            else:
                if ch in letter_map:
                    if letter_map[ch] != seq[i]:
                        ok = False
                        break
                else:
                    if seq[i] in letter_map.values():
                        ok = False
                        break
                    letter_map[ch] = seq[i]
        if ok:
            count += 1
    expected = str(count)
    output = run(x).strip()
    assert output == expected

def test_upper_bound(run, x):
    s = x.strip()
    n = len(s)
    output = run(x).strip()
    val = int(output)
    upper = 9 * (10 ** (n-1))
    assert val <= upper

def test_no_letters(run, x):
    s = x.strip()
    if any('A' <= c <= 'J' for c in s):
        return
    q = s.count('?')
    if q == 0:
        expected = 1
    else:
        if s[0] == '?':
            expected = 9 * (10 ** (q-1))
        else:
            expected = 10 ** q
    output = run(x).strip()
    assert output == str(expected)

def test_all_distinct_letters_no_question(run, x):
    s = x.strip()
    if '?' in s:
        return
    letters = [c for c in s if 'A' <= c <= 'J']
    if len(set(letters)) != len(letters):
        return
    m = len(letters)
    if s[0] in letters:
        expected = 9
        for i in range(1, m):
            expected *= (10 - i)
    else:
        expected = 1
        for i in range(m):
            expected *= (10 - i)
    output = run(x).strip()
    assert output == str(expected)

def test_single_letter_repeated(run, x):
    s = x.strip()
    letters = [c for c in s if 'A' <= c <= 'J']
    if len(set(letters)) != 1:
        return
    letter = letters[0]
    first_letter_pos = s.index(letter)
    if first_letter_pos == 0:
        letter_choices = 9
    else:
        letter_choices = 10
    q = s.count('?')
    if q == 0:
        expected = letter_choices
    else:
        if s[0] == '?':
            expected = 9 * (10 ** (q-1)) * letter_choices
        else:
            expected = (10 ** q) * letter_choices
    output = run(x).strip()
    assert output == str(expected)

def test_known_examples(run, x):
    s = x.strip()
    known = {
        "?": "9",
        "A": "9",
        "AJ": "81",
        "AJJ": "81",
        "1?AA": "100",
        "1A?A": "100",
        "??": "90",
        "A?": "90",
        "?A": "90",
        "AA": "9",
        "AB": "81",
        "ABC": "648",
        "1": "1",
        "12": "1",
        "123": "1",
        "1A": "10",
        "A1": "9",
        "A0": "9",
        "???": "900",
        "?????": "90000",
        "??????": "900000",
        "A?B": "810",
        "AB?": "810",
        "?AB": "810",
        "ABCDEFGHIJ": "3265920",
        "ABCDEFGHI?": "32659200",
        "A?B?C?D?E?": "2721600000",
        "1A2B3C": "720",
        "9B8A7C6D": "5040",
    }
    if s in known:
        expected = known[s]
        output = run(x).strip()
        assert output == expected

def test_ten_distinct_letters(run, x):
    s = x.strip()
    letters = {c for c in s if 'A' <= c <= 'J'}
    if len(letters) != 10:
        return
    q = s.count('?')
    if s[0] in letters:
        letter_assignments = 9 * 362880  # 9 * 9!
    else:
        letter_assignments = 3628800     # 10!
    if q == 0:
        question_factor = 1
    else:
        if s[0] == '?':
            question_factor = 9 * (10 ** (q-1))
        else:
            question_factor = 10 ** q
    expected = letter_assignments * question_factor
    output = run(x).strip()
    assert int(output) == expected

def test_output_format(run, x):
    output = run(x).strip()
    assert output.isdigit()
    if output != "0":
        assert output[0] != '0'
    val = int(output)
    assert val >= 0

def test_combinatorial_formula(run, x):
    s = x.strip()
    # Count distinct letters and '?'
    letters = [c for c in s if 'A' <= c <= 'J']
    distinct_letters = set(letters)
    k = len(distinct_letters)
    q = s.count('?')
    # Helper for permutations
    def perm(n, r):
        if r > n:
            return 0
        res = 1
        for i in range(r):
            res *= (n - i)
        return res
    # Letter assignments
    if s[0] in distinct_letters:
        letter_assignments = 9 * perm(9, k-1) if k > 0 else 1
    else:
        letter_assignments = perm(10, k)
    # Question factor
    if s[0] == '?':
        if q == 0:
            question_factor = 1
        else:
            question_factor = 9 * (10 ** (q-1))
    else:
        question_factor = 10 ** q
    expected = letter_assignments * question_factor
    output = run(x).strip()
    assert output == str(expected)

def test_positive_output(run, x):
    output = run(x).strip()
    val = int(output)
    assert val > 0

