def test_non_negative(run, x):
    out = run(x)
    ans = int(out.strip())
    assert ans >= 0

def test_upper_bound(run, x):
    a, b, c, d = map(int, x.strip().split())
    out = run(x)
    ans = int(out.strip())
    total = (b - a + 1) * (c - b + 1) * (d - c + 1)
    assert ans <= total

def test_all_triangles_when_D_lt_AplusB(run, x):
    a, b, c, d = map(int, x.strip().split())
    out = run(x)
    ans = int(out.strip())
    if d < a + b:
        total = (b - a + 1) * (c - b + 1) * (d - c + 1)
        assert ans == total

def test_B_eq_C_eq_D(run, x):
    a, b, c, d = map(int, x.strip().split())
    out = run(x)
    ans = int(out.strip())
    if b == c and c == d:
        expected = b - a + 1
        assert ans == expected

def test_A_eq_B_eq_C_eq_D(run, x):
    a, b, c, d = map(int, x.strip().split())
    out = run(x)
    ans = int(out.strip())
    if a == b and b == c and c == d:
        assert ans == 1

def test_small_range_oracle(run, x):
    def brute_count(a, b, c, d):
        cnt = 0
        for xv in range(a, b+1):
            for yv in range(b, c+1):
                z_min = c
                z_max = min(d, xv + yv - 1)
                if z_max >= z_min:
                    cnt += z_max - z_min + 1
        return cnt
    a, b, c, d = map(int, x.strip().split())
    out = run(x)
    ans = int(out.strip())
    total_triples = (b - a + 1) * (c - b + 1) * (d - c + 1)
    if total_triples <= 2000000:
        expected = brute_count(a, b, c, d)
        assert ans == expected

def test_B_eq_C(run, x):
    a, b, c, d = map(int, x.strip().split())
    out = run(x)
    ans = int(out.strip())
    if b == c:
        expected = 0
        for xv in range(a, b+1):
            z_max = min(d, xv + b - 1)
            if z_max >= b:
                expected += z_max - b + 1
        assert ans == expected

def test_A_eq_B_eq_C(run, x):
    a, b, c, d = map(int, x.strip().split())
    out = run(x)
    ans = int(out.strip())
    if a == b and b == c:
        expected = max(0, min(d, 2*a - 1) - a + 1)
        assert ans == expected

def test_output_format(run, x):
    out = run(x)
    s = out.strip()
    assert s.isdigit()

def test_examples_match(run, x):
    out = run(x)
    ans = out.strip()
    inp = x.strip()
    if inp == "1 2 3 4":
        assert ans == "4"
    elif inp == "1 2 2 5":
        assert ans == "3"
    elif inp == "500000 500000 500000 500000":
        assert ans == "1"

