tests_src:
def test_full_oracle(run, x):
    A, B, C, D = map(int, x.split())
    if (B - A + 1) * (C - B + 1) > 10**6:
        return
    out = run(x)
    ans = int(out.strip())
    cnt = 0
    for xv in range(A, B + 1):
        for yv in range(B, C + 1):
            min_z = C
            max_z = min(D, xv + yv - 1)
            if max_z >= min_z:
                cnt += max_z - min_z + 1
    assert ans == cnt

def test_non_negative_integer(run, x):
    out = run(x)
    s = out.strip()
    assert s.isdigit()  # non-negative integer
    ans = int(s)
    assert ans >= 0

def test_upper_bound(run, x):
    A, B, C, D = map(int, x.split())
    total = (B - A + 1) * (C - B + 1) * (D - C + 1)
    out = run(x)
    ans = int(out.strip())
    assert ans <= total

def test_lower_bound_1(run, x):
    out = run(x)
    ans = int(out.strip())
    assert ans >= 1

def test_fixed_z(run, x):
    A, B, C, D = map(int, x.split())
    if D == C:
        out = run(x)
        ans = int(out.strip())
        cnt = 0
        for xv in range(A, B + 1):
            for yv in range(B, C + 1):
                if xv + yv > C:
                    cnt += 1
        assert ans == cnt

def test_all_equal(run, x):
    A, B, C, D = map(int, x.split())
    if A == B == C == D:
        out = run(x)
        ans = int(out.strip())
        assert ans == 1

def test_small_bruteforce(run, x):
    A, B, C, D = map(int, x.split())
    total_triples = (B - A + 1) * (C - B + 1) * (D - C + 1)
    if total_triples <= 10000:
        out = run(x)
        ans = int(out.strip())
        cnt = 0
        for xv in range(A, B + 1):
            for yv in range(B, C + 1):
                for zv in range(C, D + 1):
                    if xv + yv > zv:
                        cnt += 1
        assert ans == cnt

def test_output_format(run, x):
    out = run(x)
    s = out.strip()
    assert s.isdigit() and (out == s + '\n' or out == s)

def test_examples(run, x):
    examples = {
        '1 2 3 4': '4',
        '1 2 2 5': '3',
        '500000 500000 500000 500000': '1'
    }
    key = x.strip()
    if key in examples:
        out = run(x).strip()
        assert out == examples[key]

def test_all_triangles(run, x):
    A, B, C, D = map(int, x.split())
    if A + B > D:
        out = run(x)
        ans = int(out.strip())
        total = (B - A + 1) * (C - B + 1) * (D - C + 1)
        assert ans == total

