def test_brute_force(run, x):
    s = x.strip()
    if len(s) > 20:
        return
    distinct = set()
    for i in range(len(s)+1):
        for c in 'abcdefghijklmnopqrstuvwxyz':
            distinct.add(s[:i] + c + s[i:])
    expected = len(distinct)
    output = run(x).strip()
    assert output == str(expected)

def test_mod25_eq1(run, x):
    s = x.strip()
    if len(s) > 20:
        return
    output = run(x).strip()
    val = int(output)
    assert val % 25 == 1

def test_formula(run, x):
    s = x.strip()
    if len(s) > 20:
        return
    expected = len(s) * 25 + 26
    output = run(x).strip()
    assert int(output) == expected

def test_example_a(run, x):
    if x == "a\n":
        output = run(x).strip()
        assert output == "51"

def test_example_hi(run, x):
    if x == "hi\n":
        output = run(x).strip()
        assert output == "76"

def test_example_y(run, x):
    if x == "y\n":
        output = run(x).strip()
        assert output == "51"

def test_example_abc(run, x):
    if x == "abc\n":
        output = run(x).strip()
        assert output == "101"

def test_length20_distinct(run, x):
    if x == "abcdefghijklmnopqrst\n":
