def test_brute_force_small_correct(run, x):
    data = x.strip().split()
    if len(data) < 2:
        return
    n = int(data[0])
    if n > 10:
        return
    d = int(data[1])
    a = list(map(int, data[2:2 + n]))
    # prefix sums S[0]=0, S[i]=sum a[0..i-1]
    S = [0]*(n+1)
    for i in range(1, n+1):
        S[i] = S[i-1] + a[i-1]
    best = n+1
    for mask in range(1<<n):
        feasible = True
        D = [0]*(n+1)  # cumulative deposits
        for i in range(1, n+1):
            lower = D[i-1]
            if (mask >> (i-1)) & 1:
                lower = max(lower, D[i-1] + 1)
            if a[i-1] == 0:
                lower = max(lower, -S[i])
            upper = d - S[i]
            if lower > upper:
                feasible = False
                break
            D[i] = lower
        if feasible:
            cnt = bin(mask).count('1')
            if cnt < best:
                best = cnt
    correct = -1 if best == n+1 else best
    out = run(x).strip()
    assert out == str(correct), f"Brute force expects {correct}, got {out}"

