def test_direct_comparison(run, x):
    def correct_answer(x):
        lines = x.strip().splitlines()
        n = int(lines[0])
        c = []
        d = []
        for i in range(1, n+1):
            ci, di = map(int, lines[i].split())
            c.append(ci)
            d.append(di)
        s = 0
        max_L = -10**18
        min_U = 10**18
        for i in range(n):
            if d[i] == 1:
                L = 1900 - s
                if L > max_L:
                    max_L = L
            else:
                U = 1899 - s
                if U < min_U:
                    min_U = U
            s += c[i]
        total = s
        if min_U == 10**18:
            return 'Infinity'
        if max_L == -10**18:
            max_x1 = min_U
            final = max_x1 + total
            return str(final)
        if max_L > min_U:
            return 'Impossible'
        max_x1 = min_U
        final = max_x1 + total
        return str(final)
    out = run(x).strip()
    expected = correct_answer(x).strip()
    assert out == expected

