                term = term * comb[n][r] % MOD * comb[n][c] % MOD
                if sign == -1:
                    correct = (correct - term) % MOD
                else:
                    correct = (correct + term) % MOD
        assert ans == correct"
    },
    {
      "name": "test_bruteforce_n4_k2",
      "source": "def test_bruteforce_n4_k2(run, x):
    n, k = map(int, x.split())
    if n == 4 and k == 2:
        output = run(x)
        ans = int(output.strip())
        MOD = 10**9+7
        import itertools
        total = 0
        for values in itertools.product(range(1, k+1), repeat=n*n):
            ok = True
            for i in range(n):
                row_min = min(values[i*n:(i+1)*n])
                if row_min != 1:
                    ok = False
                    break
            if not ok:
                continue
            for j in range(n):
                col_min = min(values[j::n])
                if col_min != 1:
                    ok = False
                    break
            if ok:
                total += 1
        assert ans == total % MOD"
    }
