def test_impossible_when_short(run, x):
    lines = x.strip().split('\n')
    s = lines[0]
    k = int(lines[1])
    if len(s) < k:
        out = run(x).strip()
        assert out == "impossible"

def test_zero_when_enough(run, x):
    lines = x.strip().split('\n')
    s = lines[0]
    k = int(lines[1])
    d = len(set(s))
    if len(s) >= k and d >= k:
        out = run(x).strip()
        assert out == "0"

def test_exact_when_need(run, x):
    lines = x.strip().split('\n')
    s = lines[0]
    k = int(lines[1])
    d = len(set(s))
    if len(s) >= k and d < k:
        out = run(x).strip()
        expected = k - d
        assert out == str(expected)

def test_k1_zero(run, x):
    lines = x.strip().split('\n')
    k = int(lines[1])
    if k == 1:
        out = run(x).strip()
        assert out == "0"

def test_k26(run, x):
    lines = x.strip().split('\n')
    s = lines[0]
    k = int(lines[1])
    if k == 26:
        out = run(x).strip()
        if len(s) >= 26:
            d = len(set(s))
            expected = max(0, 26 - d)
            assert out == str(expected)
        else:
            assert out == "impossible"

def test_bound_len(run, x):
    out = run(x).strip()
    if out != "impossible":
        val = int(out)
        lines = x.strip().split('\n')
        s = lines[0]
        assert val <= len(s)

def test_nonneg(run, x):
    out = run(x).strip()
    if out != "impossible":
        val = int(out)
        assert val >= 0

def test_already_all_letters(run, x):
    lines = x.strip().split('\n')
    s = lines[0]
    k = int(lines[1])
    d = len(set(s))
    if d == 26 and k == 26:
        out = run(x).strip()
        assert out == "0"

def test_full_oracle(run, x):
    lines = x.strip().split('\n')
    s = lines[0]
    k = int(lines[1])
    d = len(set(s))
    if len(s) < k:
        expected = "impossible"
    else:
        expected = str(max(0, k - d))
    out = run(x).strip()
    assert out == expected

def test_format(run, x):
    MOD = 10**9 + 7
    output = run(x)
    assert output.endswith('\n'), 'output must end with newline'
    line = output[:-1]
    assert line.isdigit() or (line.startswith('-') and line[1:].isdigit()), 'output must be an integer'
    val = int(line)
    assert 0 <= val < MOD, 'output must be between 0 and MOD-1'
    assert output == f'{val}\n', 'output must be exactly the integer followed by newline'

def test_zero_iff_unreachable(run, x):
    x_val, y_val = map(int, x.strip().split())
    output = run(x)
    ans = int(output.strip())
    if (2*y_val - x_val) % 3 == 0 and (2*x_val - y_val) % 3 == 0:
        a = (2*y_val - x_val) // 3
        b = (2*x_val - y_val) // 3
        reachable = a >= 0 and b >= 0
    else:
        reachable = False
    assert (ans == 0) == (not reachable), 'answer should be zero iff unreachable'

def test_one_if_zero_moves(run, x):
    x_val, y_val = map(int, x.strip().split())
    output = run(x)
    ans = int(output.strip())
    if (2*y_val - x_val) % 3 == 0 and (2*x_val - y_val) % 3 == 0:
        a = (2*y_val - x_val) // 3
        b = (2*x_val - y_val) // 3
        if a >= 0 and b >= 0 and (a == 0 or b == 0):
            assert ans == 1, 'if one move type count is zero, there is exactly one way'

def test_small_exact(run, x):
    MOD = 10**9 + 7
    x_val, y_val = map(int, x.strip().split())
    output = run(x)
    ans = int(output.strip())
    if (2*y_val - x_val) % 3 == 0 and (2*x_val - y_val) % 3 == 0:
        a = (2*y_val - x_val) // 3
        b = (2*x_val - y_val) // 3
        if a >= 0 and b >= 0:
            n = a + b
            if n <= 1000:
                k = min(a, b)
                res = 1
                for i in range(1, k+1):
                    res = res * (n - k + i) % MOD
                    res = res * pow(i, MOD-2, MOD) % MOD
                assert ans == res, f'for small total moves, answer should be C({n},{a}) mod MOD'

def test_nonzero_implies_nonnegative(run, x):
    x_val, y_val = map(int, x.strip().split())
    output = run(x)
    ans = int(output.strip())
    if ans != 0:
        assert (2*y_val - x_val) % 3 == 0 and (2*x_val - y_val) % 3 == 0, 'nonzero implies divisibility'
        a = (2*y_val - x_val) // 3
        b = (2*x_val - y_val) // 3
        assert a >= 0 and b >= 0, 'nonzero implies nonnegative a,b'

