def test_positive_if_reachable(run, x):
    x_val, y_val = map(int, x.strip().split())
    output = run(x)
    ans = int(output.strip())
    if (2*y_val - x_val) % 3 == 0 and (2*x_val - y_val) % 3 == 0:
        a = (2*y_val - x_val) // 3
        b = (2*x_val - y_val) // 3
        if a >= 0 and b >= 0:
            assert ans > 0, 'reachable position must have positive number of ways'

def test_small_dp(run, x):
    MOD = 10**9 + 7
    x_val, y_val = map(int, x.strip().split())
    output = run(x)
    ans = int(output.strip())
    if x_val <= 20 and y_val <= 20:
        dp = [[0]*(y_val+1) for _ in range(x_val+1)]
        dp[0][0] = 1
        for i in range(x_val+1):
            for j in range(y_val+1):
                if i >= 1 and j >= 2:
                    dp[i][j] = (dp[i][j] + dp[i-1][j-2]) % MOD
                if i >= 2 and j >= 1:
                    dp[i][j] = (dp[i][j] + dp[i-2][j-1]) % MOD
        expected = dp[x_val][y_val]
        assert ans == expected, f'DP for small coordinates gives {expected}'

