    x_val, y_val = map(int, x.strip().split())
    output = run(x)
    ans = int(output.strip())
    if (x_val + y_val) % 3 != 0:
        assert ans == 0, 'if (X+Y) not divisible by 3, answer must be 0'

def test_specific_zero(run, x):
    x_val, y_val = map(int, x.strip().split())
    output = run(x)
    ans = int(output.strip())
    unreachable = [
        (1,1), (2,2), (7,7), (10,10), (100,100),
        (999998,999998), (1000000,1000000)
    ]
    if (x_val, y_val) in unreachable:
        assert ans == 0, f'Input ({x_val}, {y_val}) is unreachable, must output 0'

