def test_small_bruteforce(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n, k = map(int, lines[0].split())
    s = lines[1].strip()
    if not (s[0] == '0' and s[-1] == '0'):
        return
    if n > 10:
        return
    free = [i for i, ch in enumerate(s) if ch == '0']
    import itertools
    best = n
    forced = {0, n - 1}
    other_free = [pos for pos in free if pos not in forced]
    max_take = min(k, len(free))
    for t in range(2, max_take + 1):
        for comb in itertools.combinations(other_free, t - 2):
            positions = sorted([0] + list(comb) + [n - 1])
            max_break = max(positions[i + 1] - positions[i] - 1 for i in range(len(positions) - 1))
            if max_break < best:
                best = max_break
    ans = int(run(x).strip())
    assert ans == best

def test_output_range(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n, k = map(int, lines[0].split())
    s = lines[1].strip()
    if not (s[0] == '0' and s[-1] == '0'):
        return
    ans_str = run(x).strip()
    ans = int(ans_str)
    assert 0 <= ans <= n - 2

def test_lower_bound_max_gap(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n, k = map(int, lines[0].split())
    s = lines[1].strip()
    if not (s[0] == '0' and s[-1] == '0'):
        return
    free = [i for i, ch in enumerate(s) if ch == '0']
    max_gap = 0
    for i in range(len(free) - 1):
        gap = free[i + 1] - free[i] - 1
        if gap > max_gap:
            max_gap = gap
    ans = int(run(x).strip())
    assert ans >= max_gap

def test_k_eq_2(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n, k = map(int, lines[0].split())
    s = lines[1].strip()
    if not (s[0] == '0' and s[-1] == '0'):
        return
    if k != 2:
        return
    ans = int(run(x).strip())
    assert ans == n - 2

def test_k_ge_num_free(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n, k = map(int, lines[0].split())
    s = lines[1].strip()
    if not (s[0] == '0' and s[-1] == '0'):
        return
    free_cnt = s.count('0')
    if k < free_cnt:
        return
    free = [i for i, ch in enumerate(s) if ch == '0']
    max_gap = 0
    for i in range(len(free) - 1):
        gap = free[i + 1] - free[i] - 1
        if gap > max_gap:
            max_gap = gap
    ans = int(run(x).strip())
    assert ans == max_gap

def test_feasibility_minimality(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n, k = map(int, lines[0].split())
    s = lines[1].strip()
    if not (s[0] == '0' and s[-1] == '0'):
        return
    if n > 2000:
        return
    ans = int(run(x).strip())
    def feasible(m):
        INF = 10**9
        dp = [INF] * n
        for i in range(n):
            if s[i] == '1':
                continue
            if i == 0:
                dp[i] = 1
            else:
                for j in range(max(0, i - m - 1), i):
                    if s[j] == '0' and dp[j] != INF:
                        if i - j - 1 <= m:
                            dp[i] = min(dp[i], dp[j] + 1)
        return dp[n - 1] <= k
    assert feasible(ans), f"m={ans} not feasible"
    if ans > 0:
        assert not feasible(ans - 1), f"m={ans-1} feasible, so {ans} not minimal"

def test_example1(run, x):
    if x == "3 3\n010\n":
        output = run(x)
        assert output == "1\n"

def test_example2(run, x):
    if x == "8 3\n01010110\n":
        output = run(x)
        assert output == "3\n"

def test_all_zero(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n, k = map(int, lines[0].split())
    s = lines[1].strip()
    if '1' in s:
        return
    expected = (n - 2) // (k - 1)
    ans = int(run(x).strip())
    assert ans == expected

def test_lower_bound_from_k(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n, k = map(int, lines[0].split())
    s = lines[1].strip()
    if not (s[0] == '0' and s[-1] == '0'):
        return
    free_cnt = s.count('0')
    max_t = min(k, free_cnt)
    lb = n
    for t in range(2, max_t + 1):
        val = (n - 2) // (t - 1)
        if val < lb:
            lb = val
    ans = int(run(x).strip())
    assert ans >= lb

def test_small_dp(run, x):
    parts = x.strip().split()
    if len(parts) < 2: return
    X, Y = map(int, parts[:2])
    if not (1 <= X <= 10**6 and 1 <= Y <= 10**6): return
    if X + Y > 30: return
    MOD = 10**9+7
    dp = [[0]*(Y+1) for _ in range(X+1)]
    dp[0][0] = 1
    for i in range(X+1):
        for j in range(Y+1):
            if i >= 1 and j >= 2:
                dp[i][j] = (dp[i][j] + dp[i-1][j-2]) % MOD
            if i >= 2 and j >= 1:
                dp[i][j] = (dp[i][j] + dp[i-2][j-1]) % MOD
    expected = dp[X][Y]
    out = run(x).strip()
    try:
        ans = int(out)
    except:
        assert False, "Output not an integer"
    assert ans == expected, f"DP expects {expected}, got {ans}"

def test_mod_range(run, x):
    parts = x.strip().split()
    if len(parts) < 2: return
    X, Y = map(int, parts[:2])
    if not (1 <= X <= 10**6 and 1 <= Y <= 10**6): return
    MOD = 10**9+7
    out = run(x).strip()
    try:
        ans = int(out)
    except:
        assert False, "Output not an integer"
    assert 0 <= ans < MOD, f"Output {ans} out of range [0, {MOD})"

def test_zero_if_sum_not_divisible(run, x):
    parts = x.strip().split()
