                continue
            if u == end:
                return d
            for v, w in adj[u]:
                nd = d + w
                if nd < dist[v]:
                    dist[v] = nd
                    heapq.heappush(heap, (nd, v))
        return float('inf')
    total = 0.0
    for j in range(5):
        for k in range(5):
            d = dijkstra(bottom_center_idx[j], top_center_idx[k])
            total += d
    expected = total / 25.0
    out = run(x).strip()
    got = float(out)
    if abs(expected - got) > 1e-6 and abs(expected - got) / max(1.0, expected) > 1e-6:
        assert False"
    }
