def test_format(run, x):
    out = run(x).strip()
    if out == '':
        assert False, 'empty output'
    if out == '-1':
        return
    parts = out.split()
    assert len(parts) == 2, 'output must be two integers or -1'
    try:
        int(parts[0])
        int(parts[1])
    except ValueError:
        assert False, 'output must be integers'

def test_pocket_valid(run, x):
    vals = list(map(int, x.strip().split()))
    if len(vals) != 6:
        return
    n, m, x0, y0, vx, vy = vals
    if (x0 == 0 or x0 == n) and (y0 == 0 or y0 == m):
        return  # initial pocket, skip
    out = run(x).strip()
    if out == '-1':
        return
    parts = out.split()
    px, py = int(parts[0]), int(parts[1])
    assert (px, py) in [(0,0),(n,0),(0,m),(n,m)], f'output {px} {py} is not a pocket'

def test_axis_aligned_vx0(run, x):
    vals = list(map(int, x.strip().split()))
    if len(vals) != 6:
        return
    n, m, x0, y0, vx, vy = vals
    if (x0 == 0 or x0 == n) and (y0 == 0 or y0 == m):
        return
    if vx != 0:
        return
    out = run(x).strip()
    if x0 != 0 and x0 != n:
        assert out == '-1', f'vx=0, x not on edge => no pocket, got {out}'
    else:
        assert out != '-1', f'vx=0, x on edge => pocket exists, got -1'
        parts = out.split()
        px, py = int(parts[0]), int(parts[1])
        assert px == x0, f'pocket x must equal starting x when vx=0'
        assert py == (m if vy > 0 else 0), f'wrong pocket y for vy={vy}'

def test_axis_aligned_vy0(run, x):
    vals = list(map(int, x.strip().split()))
    if len(vals) != 6:
        return
    n, m, x0, y0, vx, vy = vals
    if (x0 == 0 or x0 == n) and (y0 == 0 or y0 == m):
        return
    if vy != 0:
        return
    out = run(x).strip()
    if y0 != 0 and y0 != m:
        assert out == '-1', f'vy=0, y not on edge => no pocket, got {out}'
    else:
        assert out != '-1', f'vy=0, y on edge => pocket exists, got -1'
        parts = out.split()
        px, py = int(parts[0]), int(parts[1])
        assert py == y0, f'pocket y must equal starting y when vy=0'
        assert px == (n if vx > 0 else 0), f'wrong pocket x for vx={vx}'

def test_diagonal_gcd_condition_fails(run, x):
    vals = list(map(int, x.strip().split()))
    if len(vals) != 6:
        return
    n, m, x0, y0, vx, vy = vals
    if (x0 == 0 or x0 == n) and (y0 == 0 or y0 == m):
        return
    if vx == 0 or vy == 0:
        return
    import math
    A = (-vx * x0) % n
    B = (-vy * y0) % m
    g = math.gcd(n, m)
    condition = (A % g == B % g)
    if not condition:
        out = run(x).strip()
        assert out == '-1', f'gcd condition fails => no pocket, got {out}'

def test_diagonal_gcd_necessary(run, x):
    vals = list(map(int, x.strip().split()))
    if len(vals) != 6:
        return
    n, m, x0, y0, vx, vy = vals
    if (x0 == 0 or x0 == n) and (y0 == 0 or y0 == m):
        return
    if vx == 0 or vy == 0:
        return
    out = run(x).strip()
    if out == '-1':
        return
    import math
    A = (-vx * x0) % n
    B = (-vy * y0) % m
    g = math.gcd(n, m)
    assert A % g == B % g, f'gcd condition must hold when pocket is output'

