def test_exact_match(run, x):
    def correct_output(s):
        words = []
        word = ''
        for ch in s:
            if ch in ',;':
                words.append(word)
                word = ''
            else:
                word += ch
        words.append(word)
        a_words = []
        b_words = []
        for w in words:
            if w.isdigit() and (w == '0' or not w.startswith('0')):
                a_words.append(w)
            else:
                b_words.append(w)
        a_str = ','.join(a_words) if a_words else '-'
        b_str = ','.join(b_words) if b_words else '-'
        if a_str != '-':
            a_str = '"' + a_str + '"'
        if b_str != '-':
            b_str = '"' + b_str + '"'
        return a_str + '\n' + b_str + '\n'
    s = x.rstrip('\n')
    expected = correct_output(s)
    assert run(x) == expected

def test_two_lines(run, x):
    out = run(x)
    lines = out.splitlines()
    assert len(lines) == 2

def test_first_line_format(run, x):
    lines = run(x).splitlines()
    first = lines[0]
    if first == '-':
        return
    assert first.startswith('"') and first.endswith('"')
    assert first.count('"') == 2

def test_second_line_format(run, x):
    lines = run(x).splitlines()
    second = lines[1]
    if second == '-':
        return
    assert second.startswith('"') and second.endswith('"')
    assert second.count('"') == 2

def test_a_numbers_valid(run, x):
    lines = run(x).splitlines()
