    s = x.rstrip('\n')
    words = []
    cur = []
    for ch in s:
        if ch in ',;':
            words.append(''.join(cur))
            cur = []
        else:
            cur.append(ch)
    words.append(''.join(cur))
    a = []
    b = []
    for w in words:
        if w.isdigit() and (w == '0' or w[0] != '0'):
            a.append(w)
        else:
            b.append(w)
    line1 = '"' + ','.join(a) + '"' if a else '-'
    line2 = '"' + ','.join(b) + '"' if b else '-'
    expected = line1 + '\n' + line2 + '\n'
    assert out == expected
